import type { BankQuestion } from "@/lib/bank";

/** DBMS and SQL (CS Fundamentals): 582 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cs-dbms-sql-1","question":"Which pair of properties must every primary key satisfy?","options":["Unique and NOT NULL","Unique and indexed as clustered","Unique and referenced by a foreign key","NOT NULL and numeric"],"answer":0,"explanation":"A primary key identifies each row, so its values must be unique and can never be NULL. It need not be numeric or clustered, and nothing has to reference it.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-2","question":"Which ACID property guarantees that a transaction's changes are applied completely or not at all?","options":["Isolation","Atomicity","Durability","Consistency"],"answer":1,"explanation":"Atomicity is all-or-nothing: if the transaction fails midway, the recovery manager undoes its partial changes. Durability is about committed changes surviving crashes.","difficulty":"easy","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-3","question":"Which of these SQL commands is a DDL (Data Definition Language) command?","options":["INSERT","UPDATE","ALTER","SELECT"],"answer":2,"explanation":"DDL commands define or change structure: CREATE, ALTER, DROP, TRUNCATE, RENAME. INSERT and UPDATE are DML; SELECT is a query (DQL/DML).","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dbms-sql-4", "question": "In an ER model, a weak entity set is identified by:", "options": ["A composite of all its attributes", "A foreign key to any entity set", "Its own primary key alone", "Its partial key (discriminator) together with the primary key of its owner (identifying) entity set"], "answer": 3, "explanation": "A weak entity has no key of its own; its discriminator becomes unique only when combined with the owner's primary key through the identifying relationship.", "difficulty": "easy", "source": "Accenture · Capgemini pattern"},
  {"id": "cs-dbms-sql-5", "question": "Which SQL clause filters groups AFTER aggregation?", "options": ["HAVING", "WHERE", "GROUP BY", "ORDER BY"], "answer": 0, "explanation": "WHERE filters individual rows before grouping and cannot use aggregates; HAVING filters the groups formed by GROUP BY and can test COUNT, SUM, AVG and so on.", "difficulty": "easy", "source": "Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-6","question":"Which statement about the SQL command TRUNCATE TABLE is correct?","options":["It removes rows matching a WHERE clause","It removes all rows but keeps the table structure","It removes the table definition along with its data","It only removes rows whose columns are NULL"],"answer":1,"explanation":"TRUNCATE empties the table and keeps its structure; DROP removes the table itself; DELETE can remove selected rows with WHERE.","difficulty":"easy","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-7","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nWhat does this query return?\n```sql\nSELECT COUNT(*), COUNT(dept), COUNT(DISTINCT dept)\nFROM Emp;\n```","options":["6, 6, 3","7, 6, 4","7, 6, 3","7, 7, 4"],"answer":2,"explanation":"COUNT(*) counts all 7 rows. COUNT(dept) skips Dev's NULL: 6. COUNT(DISTINCT dept) counts HR, IT, Sales = 3; NULL is not counted as a distinct value.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dbms-sql-8", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does this query return?\n```sql\nSELECT e.name, d.city\nFROM Emp e INNER JOIN Dept d ON e.dept = d.dname;\n```", "options": ["7", "3", "6", "4"], "answer": 3, "explanation": "Matches: Asha (HR) and Ravi, Meena, Kiran (IT) = 4. Sales has no row in Dept, Dev's NULL dept matches nothing, and Ops has no employees.", "difficulty": "moderate", "source": "Wipro · Cognizant pattern"},
  {"id": "cs-dbms-sql-9", "question": "Two tables have 6 rows and 4 rows. How many rows does `SELECT * FROM A, B;` (no WHERE clause) return?", "options": ["24", "6", "10", "4"], "answer": 0, "explanation": "A comma join without a condition is a Cartesian product: 6 × 4 = 24 rows. 10 would be a UNION ALL of the two tables.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-10","question":"A relation is in 2NF if it is in 1NF and:","options":["It has no multivalued dependency","No non-prime attribute is functionally dependent on a proper subset of any candidate key","Every determinant is a candidate key","It has no transitive dependency of a non-prime attribute on a key"],"answer":1,"explanation":"2NF removes partial dependencies. Removing transitive dependencies gives 3NF; 'every determinant is a candidate key' is BCNF; multivalued dependencies are 4NF.","difficulty":"easy","source":"Accenture · Capgemini pattern"},
  {"id":"cs-dbms-sql-11","question":"R(A, B, C, D) has functional dependencies A → B and B → C. What is the candidate key of R?","options":["ABD","A","AD","AB"],"answer":2,"explanation":"A⁺ = {A, B, C}, which misses D. D appears on no right-hand side, so it must be in every key; (AD)⁺ = {A, B, C, D}. ABD is a superkey but not minimal.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-12","question":"Which statement about a clustered index is correct?","options":["A clustered index never speeds up range queries","A table can have any number of clustered indexes","A clustered index must be on a non-key column","A table can have at most one clustered index, because the rows can be physically ordered in only one way"],"answer":3,"explanation":"A clustered index fixes the physical order of rows (or leaf pages) by its key, so only one is possible. Range queries benefit most, since matching rows are stored together.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-13","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows do the two queries return?\n```sql\n-- Query 1\nSELECT dept FROM Emp UNION SELECT dname FROM Dept;\n-- Query 2\nSELECT dept FROM Emp UNION ALL SELECT dname FROM Dept;\n```","options":["5 and 10","4 and 9","4 and 10","5 and 9"],"answer":0,"explanation":"UNION ALL keeps everything: 7 + 3 = 10. UNION removes duplicates and treats the NULLs as one value: {NULL, HR, IT, Sales, Ops} = 5. Forgetting that NULL survives as a row gives 4.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-14","question":"Transaction T2 reads a value that T1 has written but not yet committed; T1 later rolls back. What is this anomaly called?","options":["Non-repeatable read","Dirty read","Lost update","Phantom read"],"answer":1,"explanation":"Reading uncommitted data is a dirty read; READ COMMITTED and above prevent it. A non-repeatable read reads committed data that changes between two reads.","difficulty":"easy","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-15","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhich names does this query return?\n```sql\nSELECT name FROM Emp WHERE name LIKE '_a%';\n```","options":["Ravi, Meena, Lata, Kiran","Asha, Meena, Lata","Ravi, Lata","Asha, Ravi, Lata"],"answer":2,"explanation":"_ matches exactly one character and % any number, so the second letter must be 'a': Ravi and Lata. Kiran's 'a' is fourth; names ending in 'a' would need '%a'.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-16","question":"A candidate key is best described as:","options":["Any set of attributes that uniquely identifies a tuple","An attribute that references another table's key","The key chosen by the designer to identify rows","A minimal superkey: no proper subset of it is a superkey"],"answer":3,"explanation":"A superkey identifies tuples uniquely; a candidate key is a superkey with nothing removable. The one chosen among candidate keys is the primary key; a referencing attribute is a foreign key.","difficulty":"easy","source":"Accenture · Capgemini pattern"},
  {"id":"cs-dbms-sql-17","question":"In an ER diagram, entity sets Student and Course are related by a many-to-many relationship Enrols that has an attribute grade. What is the minimum number of tables needed?","options":["3","1","2","4"],"answer":0,"explanation":"M:N needs its own table holding both keys and grade, plus one table for each entity: 3. Only 1:N or 1:1 relationships can be folded into an entity's table.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-18","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does this query return?\n```sql\nSELECT e.name, d.city\nFROM Emp e LEFT JOIN Dept d ON e.dept = d.dname;\n```","options":["8","7","5","4"],"answer":1,"explanation":"A LEFT JOIN keeps every Emp row: the 4 matches plus John, Lata (Sales, no Dept row) and Dev (NULL dept) with city NULL = 7. Ops is dropped because it is on the right side.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-19","question":"Which mechanism does a DBMS mainly rely on to guarantee durability of committed transactions?","options":["Normalisation","Locking","Write-ahead logging, with log records forced to stable storage at commit","Indexing"],"answer":2,"explanation":"Under WAL, the commit record and the transaction's log records reach stable storage before commit is acknowledged, so the changes can be redone after a crash. Locking provides isolation.","difficulty":"easy","source":"IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-20","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nHow many rows does this query return?\n```sql\nSELECT dept, COUNT(*) FROM Emp GROUP BY dept;\n```","options":["7","3","6","4"],"answer":3,"explanation":"Groups: HR, IT, Sales and one group for NULL (Dev). GROUP BY puts all NULLs in a single group even though NULL = NULL is not true in a WHERE clause.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-21", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT dept FROM Emp\nGROUP BY dept\nHAVING AVG(salary) > 50000;\n```", "options": ["IT", "IT and Sales", "IT and HR", "IT, HR and Sales"], "answer": 0, "explanation": "Averages: HR 50000 (not > 50000), IT (70000 + 70000 + 90000)/3 ≈ 76667, Sales 40000 (Lata's NULL is ignored by AVG, not counted as 0), NULL group 45000. Only IT qualifies.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-22","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT MAX(salary) FROM Emp\nWHERE salary < (SELECT MAX(salary) FROM Emp);\n```","options":["90000","70000","Two rows: 70000 and 70000","50000"],"answer":1,"explanation":"The subquery gives 90000; the outer query takes the largest salary below it, 70000, as one value. This is the classic second-highest-salary query; duplicates do not matter because MAX returns one row.","difficulty":"moderate","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-23","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nWhich names does this query return?\n```sql\nSELECT name FROM Emp\nWHERE dept NOT IN (SELECT dname FROM Dept);\n```","options":["No rows","John, Lata, Dev","John, Lata","Dev"],"answer":2,"explanation":"The subquery {HR, IT, Ops} has no NULL, so NOT IN works normally for Sales: John and Lata. Dev's dept is NULL, and NULL NOT IN (...) is UNKNOWN, so Dev is not returned.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-24", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhich employees does this query return?\n```sql\nSELECT e.name\nFROM Emp e JOIN Emp m ON e.mgr = m.id\nWHERE m.dept = 'IT';\n```", "options": ["Ravi, Kiran", "Ravi, Meena, Kiran", "Meena, Kiran, Dev", "Meena, Kiran"], "answer": 3, "explanation": "This is a self-join: m is the manager. Employees whose manager is in IT: Meena and Kiran (manager Ravi, IT). Ravi himself is in IT but his manager Asha is in HR.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-25","question":"R(A, B, C) has functional dependencies AB → C and C → B. What is the highest normal form of R?","options":["3NF but not BCNF","2NF","BCNF","1NF"],"answer":0,"explanation":"Candidate keys are AB and AC, so all attributes are prime. C → B: C is not a superkey, so BCNF fails; but B is prime, so 3NF holds. This is the textbook 3NF-but-not-BCNF shape.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-26", "question": "R(A, B, C) with A → B and B → C. Which decomposition is lossless?", "options": ["R1(A), R2(B, C)", "R1(A, B), R2(B, C)", "R1(A, B), R2(C)", "R1(A, C), R2(B, C)"], "answer": 1, "explanation": "A binary decomposition is lossless if the common attributes functionally determine one side. (AB) ∩ (BC) = B and B → C, so B is a key of R2. In (AC, BC) the common attribute C determines nothing. Decompositions with no common attribute are lossy.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-27", "question": "Is the schedule R1(A), R2(A), W1(A), W2(A) conflict serializable?", "options": ["Yes, equivalent to T1 → T2", "Yes, equivalent to T2 → T1", "Yes, because no transaction reads a dirty value", "No; the precedence graph has a cycle T1 → T2 → T1"], "answer": 3, "explanation": "R1(A) before W2(A) gives T1 → T2; R2(A) before W1(A) gives T2 → T1. A cycle means it is not conflict serializable; this is the lost-update pattern, where T1's write is overwritten.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-28", "question": "Which isolation level prevents dirty reads and non-repeatable reads but may still allow phantom reads (in the SQL standard)?", "options": ["READ UNCOMMITTED", "READ COMMITTED", "REPEATABLE READ", "SERIALIZABLE"], "answer": 2, "explanation": "REPEATABLE READ keeps rows already read stable, but new rows matching a predicate can appear (phantoms). Only SERIALIZABLE forbids all three; READ COMMITTED still allows non-repeatable reads.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-29","question":"Which statement about basic two-phase locking (2PL) is correct?","options":["It guarantees freedom from cascading rollback but not serializability","It guarantees conflict serializability and freedom from deadlock","It requires all locks to be acquired before the transaction starts","It guarantees conflict serializability but not freedom from deadlock or cascading rollback"],"answer":3,"explanation":"Growing then shrinking phases ensure conflict serializability. Two transactions can still wait on each other's locks (deadlock), and releasing locks before commit allows cascading rollbacks; strict 2PL fixes the latter, conservative 2PL the former.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-30", "question": "A B+ tree is built on a key of 9 bytes. A block is 1024 bytes and a block pointer is 6 bytes. What is the maximum order p (number of child pointers) of an internal node?", "options": ["68", "63", "69", "113"], "answer": 0, "explanation": "An internal node holds p pointers and p − 1 keys: 6p + 9(p − 1) ≤ 1024 → 15p ≤ 1033 → p ≤ 68.9, so p = 68. 69 comes from rounding up; 113 uses keys only.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-31","question":"R(A, B, C, D) has A as its only candidate key. How many superkeys does R have?","options":["15","8","7","4"],"answer":1,"explanation":"Every superkey must contain A; each of B, C and D may be in or out: 2³ = 8 (A, AB, AC, AD, ABC, ABD, ACD, ABCD). 15 is the total number of non-empty subsets.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-32", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does `SELECT AVG(salary) FROM Emp;` return (rounded)?", "options": ["52143", "NULL, because one salary is NULL", "60833", "70000"], "answer": 2, "explanation": "AVG ignores NULLs: (50000 + 70000 + 70000 + 40000 + 90000 + 45000) / 6 = 365000/6 ≈ 60833. Dividing by all 7 rows (treating NULL as 0) gives 52143.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-33","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nFor Asha's row, what are the values of rk and drk?\n```sql\nSELECT name,\n       RANK()       OVER (ORDER BY salary DESC) AS rk,\n       DENSE_RANK() OVER (ORDER BY salary DESC) AS drk\nFROM Emp\nWHERE salary IS NOT NULL;\n```","options":["rk = 3, drk = 4","rk = 4, drk = 4","rk = 3, drk = 3","rk = 4, drk = 3"],"answer":3,"explanation":"Order: 90000 (1), 70000, 70000 (both 2), then 50000. RANK skips after a tie, so Asha gets 4; DENSE_RANK does not skip, so she gets 3.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-34","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT COUNT(DISTINCT salary), COUNT(salary) FROM Emp;\n```","options":["5, 6","6, 6","6, 7","5, 7"],"answer":0,"explanation":"Non-NULL salaries: 50000, 70000, 70000, 40000, 90000, 45000 → COUNT = 6, distinct = 5 (70000 twice). Lata's NULL is skipped by both.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dbms-sql-35", "question": "Schedule: W1(A), R2(A), C2, C1, where C means commit. Which classification is correct?", "options": ["Recoverable but not cascadeless", "Not recoverable", "Recoverable and cascadeless", "Strict"], "answer": 1, "explanation": "T2 reads A written by T1 and commits before T1 commits. If T1 now aborts, T2 has committed a value that never existed, so the schedule is not recoverable. Committing T1 first would make it recoverable (still not cascadeless).", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-36","question":"Under basic timestamp ordering, TS(T1) = 10 and TS(T2) = 20. T2 has read item X, so read-TS(X) = 20. T1 now issues write(X). What happens?","options":["The write is ignored under the Thomas write rule","T2 is rolled back","T1 is rolled back","The write is performed"],"answer":2,"explanation":"A write by T1 is rejected when TS(T1) < read-TS(X): a younger transaction already read the old value, so T1 is aborted and restarted. The Thomas write rule only ignores obsolete writes when a younger transaction has WRITTEN X, not read it.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-37","question":"R(A, B, C, D, E, F) has FDs A → B, BC → D, D → E, E → C, CE → F. Which of these is NOT a candidate key?","options":["AC","AE","AD","AB"],"answer":3,"explanation":"(AB)⁺ = {A, B} only. (AC)⁺: A → B, BC → D, D → E, CE → F, all attributes. (AD)⁺: D → E → C, then B and F. (AE)⁺: E → C, then B, D, F. So AC, AD and AE are keys; AB is not.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-38", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT COUNT(*), SUM(salary), MAX(salary)\nFROM Emp WHERE dept = 'Ops';\n```", "options": ["One row: 0, NULL, NULL", "One row: 0, 0, 0", "One row: NULL, NULL, NULL", "No rows"], "answer": 0, "explanation": "An aggregate query without GROUP BY always returns exactly one row. Over an empty set, COUNT gives 0 but SUM and MAX give NULL.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-39","question":"Which isolation-related statement is correct for the SQL standard levels?","options":["READ COMMITTED prevents non-repeatable reads","READ UNCOMMITTED allows dirty reads","SERIALIZABLE allows phantom reads","REPEATABLE READ allows dirty reads"],"answer":1,"explanation":"Each level forbids more: READ UNCOMMITTED allows all three anomalies; READ COMMITTED forbids dirty reads; REPEATABLE READ also forbids non-repeatable reads; SERIALIZABLE forbids phantoms too.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-40","question":"Which statement about dense and sparse indexes is correct?","options":["A primary index must always be dense","A dense index has an entry for only one record per block","A sparse index can be used only if the data file is sorted on the search key","A secondary index on a non-ordering field can be sparse"],"answer":2,"explanation":"A sparse index stores one entry per block and relies on the file being ordered on that key to find records in between. A secondary index must be dense because the file is not ordered on that field; a primary index is usually sparse.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-41","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat is returned?\n```sql\nSELECT COUNT(*) FROM Emp WHERE salary <> 70000;\n```","options":["7","6","5","4"],"answer":3,"explanation":"Rows with salary 50000, 40000, 90000, 45000 qualify = 4. Lata's NULL salary makes NULL <> 70000 UNKNOWN, so her row is filtered out; 5 is the common wrong answer.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-42","question":"Which statement about view serializability is correct?","options":["Every conflict-serializable schedule is view serializable, and a schedule that is view but not conflict serializable must contain a blind write","View serializability can be tested in polynomial time with a precedence graph","Every view-serializable schedule is conflict serializable","View and conflict serializability are the same"],"answer":0,"explanation":"Conflict ⊂ view. The extra view-serializable schedules all involve blind writes (writes without a prior read). Testing view serializability is NP-complete, unlike the precedence-graph test for conflict serializability.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-43","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nThe query below is meant to list employees who manage nobody. What does it return?\n```sql\nSELECT name FROM Emp\nWHERE id NOT IN (SELECT mgr FROM Emp);\n```","options":["Meena, Kiran, Dev, Lata and Asha","No rows","Meena, Kiran, Dev, Lata","Asha only"],"answer":1,"explanation":"The subquery contains NULL (Asha's mgr). x NOT IN (…, NULL) is never TRUE: it is FALSE if x matches and UNKNOWN otherwise, so no row qualifies. Use NOT EXISTS or filter mgr IS NOT NULL to get Meena, Kiran, Dev, Lata.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-44","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nHow many rows does each query return?\n```sql\n-- Q1\nSELECT name FROM Emp e\nWHERE NOT EXISTS (SELECT 1 FROM Emp x WHERE x.mgr = e.id);\n-- Q2\nSELECT name FROM Emp\nWHERE id NOT IN (SELECT mgr FROM Emp);\n```","options":["Q1: 3, Q2: 0","Q1: 0, Q2: 4","Q1: 4, Q2: 0","Q1: 4, Q2: 4"],"answer":2,"explanation":"NOT EXISTS only asks whether a matching row exists, and NULL mgr values simply never match: Meena, Kiran, Dev, Lata = 4. NOT IN against a list containing NULL is never TRUE, so Q2 returns 0 rows.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-45", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT dept, COUNT(*) AS a, COUNT(salary) AS b\nFROM Emp\nGROUP BY dept\nHAVING COUNT(salary) < COUNT(*);\n```", "options": ["No rows", "NULL, 1, 0 and Sales, 2, 1", "NULL, 1, 1 and Sales, 2, 1", "Sales, 2, 1"], "answer": 3, "explanation": "Only Sales has a NULL salary (Lata): COUNT(*) = 2, COUNT(salary) = 1. The NULL-dept group is Dev, whose salary 45000 is not NULL, so it has 1 and 1 and fails the test.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-46","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does each query return?\n```sql\n-- Q1\nSELECT e.name FROM Emp e LEFT JOIN Dept d\n  ON e.dept = d.dname\nWHERE d.city <> 'Delhi';\n-- Q2\nSELECT e.name FROM Emp e LEFT JOIN Dept d\n  ON e.dept = d.dname AND d.city <> 'Delhi';\n```","options":["Q1: 1, Q2: 7","Q1: 4, Q2: 7","Q1: 4, Q2: 4","Q1: 1, Q2: 1"],"answer":0,"explanation":"Q1: the WHERE runs after the join. Rows with city NULL (John, Lata, Dev) give UNKNOWN and IT rows give FALSE, leaving only Asha (Pune): 1 row; the outer join has become an inner join. Q2: the condition is part of ON, so every Emp row is kept (unmatched ones get NULLs): 7.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-47", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat is the value of running for Ravi (id 2)?\n```sql\nSELECT id, salary,\n       SUM(salary) OVER (ORDER BY salary) AS running\nFROM Emp\nWHERE salary IS NOT NULL;\n```", "options": ["205000", "275000", "365000", "135000"], "answer": 1, "explanation": "With ORDER BY and no frame clause, the default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, which includes all peers with the same salary. 40000 + 45000 + 50000 + 70000 + 70000 = 275000 for both Ravi and Meena. 205000 assumes a row-by-row (ROWS) frame.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-48","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat do the two queries return?\n```sql\n-- Q1\nSELECT salary FROM (\n  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r\n  FROM Emp WHERE salary IS NOT NULL) t\nWHERE r = 3;\n-- Q2\nSELECT salary FROM (\n  SELECT salary, ROW_NUMBER() OVER (ORDER BY salary DESC) AS r\n  FROM Emp WHERE salary IS NOT NULL) t\nWHERE r = 3;\n```","options":["Q1: 45000, Q2: 70000","Q1: 50000, Q2: 50000","Q1: 50000, Q2: 70000","Q1: 70000, Q2: 50000"],"answer":2,"explanation":"Distinct salaries descending: 90000, 70000, 50000, so the 3rd highest distinct salary (DENSE_RANK = 3) is 50000. ROW_NUMBER numbers the rows 90000, 70000, 70000, …, so row 3 is the second 70000. Use DENSE_RANK for the 'nth highest salary' problem.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-49","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhich employees are returned?\n```sql\nSELECT name FROM Emp e\nWHERE salary > (SELECT AVG(salary) FROM Emp x\n                WHERE x.dept = e.dept);\n```","options":["Kiran, Ravi and Meena","Kiran and Asha","Kiran and Dev","Kiran only"],"answer":3,"explanation":"Department averages: HR 50000, IT ≈ 76667, Sales 40000 (NULL ignored). Only Kiran (90000) beats his average; Asha and John equal theirs. For Dev, x.dept = NULL matches no row, the average is NULL, and the comparison is UNKNOWN.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-50","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does this query return?\n```sql\nSELECT *\nFROM Emp e FULL OUTER JOIN Dept d ON e.dept = d.dname;\n```","options":["8","7","4","5"],"answer":0,"explanation":"4 matched rows + 3 unmatched Emp rows (John, Lata, Dev) + 1 unmatched Dept row (Ops) = 8. 7 is what a LEFT JOIN returns (it drops Ops), 5 a RIGHT JOIN and 4 an INNER JOIN; NULL = NULL never matches, so Dev stays unmatched.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-51","question":"Table A(x) rows: (1), (1), (2), (NULL).\nTable B(x) rows: (1), (1), (1), (NULL), (3).\nHow many rows do the inner join and the left join return?\n```sql\nSELECT * FROM A JOIN B ON A.x = B.x;\nSELECT * FROM A LEFT JOIN B ON A.x = B.x;\n```","options":["6 and 7","6 and 8","7 and 8","2 and 4"],"answer":1,"explanation":"Each of A's two 1s matches B's three 1s: 2 × 3 = 6; NULLs never match each other. The left join adds A's unmatched rows 2 and NULL: 6 + 2 = 8. Counting NULL = NULL as a match gives 7.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-52","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT CASE WHEN salary > 60000 THEN 'H'\n            WHEN salary <= 60000 THEN 'L'\n            ELSE 'U' END AS band,\n       COUNT(*)\nFROM Emp GROUP BY band;\n```","options":["H 3, L 3","H 4, L 3","H 3, L 3, U 1","H 3, L 4"],"answer":2,"explanation":"H: Ravi, Meena, Kiran. L: Asha, John, Dev. Lata's NULL salary fails both comparisons (UNKNOWN), so it falls to ELSE 'U'. The two WHEN conditions look exhaustive but are not when NULLs exist.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-53","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT dept, MAX(salary)\nFROM Emp\nWHERE salary < 90000\nGROUP BY dept\nHAVING COUNT(*) > 1;\n```","options":["IT 70000 and Sales 40000","IT 90000","IT 70000, Sales 40000 and HR 50000","IT 70000"],"answer":3,"explanation":"WHERE runs first and drops Kiran (90000) and Lata (NULL < 90000 is UNKNOWN). Remaining groups: HR 1, IT 2 (Ravi, Meena), Sales 1 (John), NULL 1. Only IT has COUNT > 1, with MAX 70000. Sales loses Lata before grouping.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-54","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT COUNT(*)\nFROM Emp a, Emp b\nWHERE a.salary < b.salary;\n```","options":["14","49","15","21"],"answer":0,"explanation":"Only the 6 non-NULL salaries can satisfy the condition. Of the C(6, 2) = 15 unordered pairs, exactly one ordering of each satisfies '<', except the tied pair (70000, 70000), which satisfies neither: 15 − 1 = 14.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-55","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nWhat does this query return (SQL standard behaviour, as in PostgreSQL and SQLite)?\n```sql\nSELECT dept FROM Emp\nEXCEPT\nSELECT dname FROM Dept;\n```","options":["Sales, Sales and NULL","Sales and NULL","No rows","Sales"],"answer":1,"explanation":"EXCEPT works on distinct rows and, unlike WHERE comparisons, treats NULLs as equal to each other. Emp's distinct depts {NULL, HR, IT, Sales} minus {HR, IT, Ops} = {NULL, Sales}. Duplicates are removed, so Sales appears once.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-56","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nIn the SQL standard (and in MySQL, PostgreSQL, Oracle), what does this query return?\n```sql\nSELECT COUNT(*) FROM Emp\nWHERE salary > ALL (SELECT salary FROM Emp\n                    WHERE dept = 'Sales');\n```","options":["3","6","0","4"],"answer":2,"explanation":"The subquery returns {40000, NULL}. For any salary s > 40000, 's > ALL' becomes TRUE AND UNKNOWN = UNKNOWN; for s ≤ 40000 it is FALSE. No row gets TRUE, so the count is 0. Ignoring the NULL gives 4, the trap.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-57","question":"Table Enroll(sid, cid) rows: (1, 'C1'), (1, 'C2'), (2, 'C1'), (3, 'C1'), (3, 'C2'), (3, 'C3'), (4, 'C3').\nTable Course(cid) rows: ('C1'), ('C2'), ('C3').\nWhat does this query return?\n```sql\nSELECT DISTINCT sid FROM Enroll e\nWHERE NOT EXISTS (\n  SELECT * FROM Course c\n  WHERE NOT EXISTS (\n    SELECT * FROM Enroll x\n    WHERE x.sid = e.sid AND x.cid = c.cid));\n```","options":["1, 2, 3 and 4","1 and 3","No rows","3"],"answer":3,"explanation":"This double NOT EXISTS is relational division: students for whom there is no course they have not taken, i.e. students enrolled in ALL courses. Only student 3 has C1, C2 and C3; student 1 lacks C3.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-58", "question": "R(A, B, C, D, E) has FDs A → B, B → C, C → A, D → E. How many candidate keys does R have, and what is its highest normal form?", "options": ["3 keys; 1NF", "4 keys; 2NF", "1 key (AD); 2NF", "3 keys; 3NF"], "answer": 0, "explanation": "A, B and C determine each other in a cycle and D determines E, so the keys are AD, BD and CD. D → E is a partial dependency (D is part of every key and E is non-prime), so R is not even in 2NF.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-59", "question": "R(A, B, C, D, E, F) has FDs AB → C, C → D, D → B, E → F. Which statement is correct?", "options": ["The only candidate key is ABE, and R is in 3NF", "The candidate keys are ABE, ACE and ADE, and R is in 1NF but not 2NF", "The candidate keys are AE and BE, and R is in 2NF", "The candidate keys are ABE, ACE and ADE, and R is in 3NF but not BCNF"], "answer": 1, "explanation": "A and E appear on no right side, so they are in every key; adding any one of B, C or D completes it (B, C, D form a cycle given A): ABE, ACE, ADE. E → F makes the non-prime F depend on part of a key, so 2NF fails.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-60", "question": "R(A, B, C, D) has FDs AB → CD, C → A, D → B. How many candidate keys does R have, and what is its highest normal form?", "options": ["4 keys; 3NF but not BCNF", "4 keys; BCNF", "2 keys; BCNF", "3 keys; 2NF"], "answer": 0, "explanation": "Keys: AB, AD (D → B), BC (C → A) and CD. Every attribute is prime, so 3NF holds automatically. C → A and D → B have determinants that are not superkeys, so BCNF fails.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-61","question":"R(A, B, C, D) has FDs AB → CD, C → A, D → B, giving candidate keys AB, AD, BC and CD. How many superkeys does R have?","options":["8","9","11","15"],"answer":1,"explanation":"Two-attribute superkeys are exactly the 4 keys (AC and BD are not). Every 3-attribute set contains one of them (4 sets), plus ABCD: 4 + 4 + 1 = 9. No single attribute is a superkey.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-62", "question": "R(A, B, C) with AB → C and C → B is decomposed into R1(A, C) and R2(B, C) to reach BCNF. Which statement is correct?", "options": ["It is both lossless and dependency preserving", "The decomposition is lossy but dependency preserving", "The decomposition is lossless but does not preserve AB → C", "It is neither lossless nor dependency preserving"], "answer": 2, "explanation": "Common attribute C → B, so C is a key of R2 and the join is lossless. But AB → C spans both tables and cannot be checked in either one. This is why BCNF decomposition can lose dependencies while 3NF synthesis never does.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-63", "question": "Schedule: R2(A), R1(B), W2(A), R3(A), W1(B), W3(A), R2(B), W2(B). Which statement is correct?", "options": ["Conflict serializable, equivalent only to T1 → T2 → T3", "Conflict serializable, equivalent to both T1 → T2 → T3 and T2 → T1 → T3", "Not conflict serializable", "Conflict serializable, equivalent only to T2 → T3 → T1"], "answer": 0, "explanation": "Conflicts on A: W2(A) before R3(A) and W3(A) → T2 → T3. Conflicts on B: R1(B) before W2(B) and W1(B) before R2(B) → T1 → T2. The graph T1 → T2 → T3 is acyclic with only one topological order.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-64", "question": "Schedule: R1(A), W2(A), W1(A), W3(A). Which statement is correct?", "options": ["Conflict serializable but not view serializable", "Conflict serializable and view serializable", "Not conflict serializable but view serializable, equivalent to T1 → T2 → T3", "Neither conflict nor view serializable"], "answer": 2, "explanation": "R1(A) before W2(A) gives T1 → T2, and W2(A) before W1(A) gives T2 → T1: a cycle. But in serial T1, T2, T3, T1 reads the initial A and T3 writes the final A, exactly as in the schedule, so it is view serializable. W2 and W3 are blind writes.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-65","question":"Classify the schedule W1(A), W2(A), C1, C2 (C = commit; T2 does not read A).","options":["Recoverable but not cascadeless","Strict","Not recoverable","Cascadeless but not strict"],"answer":3,"explanation":"No transaction reads uncommitted data, so it is cascadeless (and so recoverable). It is not strict, because T2 overwrites A before T1 has committed or aborted; strictness forbids both reading and writing an uncommitted item.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-66", "question": "How many of the following statements are correct?\n1. Strict 2PL holds all exclusive locks until commit or abort and so avoids cascading rollbacks.\n2. Conservative (static) 2PL acquires all locks before the transaction begins and is deadlock-free.\n3. Rigorous 2PL releases shared locks early but holds exclusive locks until commit.\n4. Every schedule produced by basic 2PL is conflict serializable.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is wrong: rigorous 2PL holds ALL locks, shared and exclusive, until commit; holding only exclusive locks is strict 2PL.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-67", "question": "Deadlock prevention with timestamps: T1 (timestamp 5) is older than T2 (timestamp 10). T2 holds a lock on X and T1 requests it; separately, T1 holds a lock on Y and T2 requests it. What happens under wait-die and under wound-wait?", "options": ["Both schemes roll back the older transaction in both cases", "Wait-die: T1 waits for X, T2 is rolled back on Y. Wound-wait: T2 is rolled back on X, T2 waits for Y", "Both schemes make the younger transaction wait in both cases", "Wait-die: T1 is rolled back on X, T2 waits for Y. Wound-wait: T1 waits for X, T2 is rolled back on Y"], "answer": 1, "explanation": "Wait-die: an older requester waits, a younger requester dies. So T1 waits for X; T2 asking for Y dies. Wound-wait: an older requester wounds (rolls back) the younger holder, so T2 is rolled back for X; a younger requester waits, so T2 waits for Y. In both, only the younger transaction is ever rolled back.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-68", "question": "Immediate-update recovery with a checkpoint. Log (oldest first): <T1 start>, <T1 commit>, <T2 start>, <checkpoint, active = {T2}>, <T3 start>, <T2 commit>, <T4 start>, <T3 commit>, crash. Which transactions are redone and which are undone?", "options": ["Redo T2, T3; undo T4", "Redo T1, T2, T3; undo T4", "Redo T2; undo T3, T4", "Redo T3; undo T2, T4"], "answer": 0, "explanation": "T1 committed before the checkpoint, so its changes are already on disk: ignore it. T2 and T3 committed after the checkpoint: redo. T4 never committed: undo. Redoing T1 is the common over-cautious answer.", "difficulty": "very-hard", "source": "IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-69","question":"A file of 30,000 records (100 bytes each, unspanned) is sorted on key K and stored in 1,024-byte blocks. A primary (sparse) index on K uses 15-byte entries (9-byte key + 6-byte pointer), one per data block. How many block accesses are needed to find a record by binary search on the data file, and by binary search on the index plus one data access?","options":["15 and 7","12 and 7","15 and 13","12 and 6"],"answer":1,"explanation":"Data: 1024/100 = 10 records per block, 3,000 blocks, ⌈log₂ 3000⌉ = 12 accesses. Index: 1024/15 = 68 entries per block; 3,000 entries need ⌈3000/68⌉ = 45 blocks; ⌈log₂ 45⌉ = 6, plus 1 data block = 7. 15 is ⌈log₂ 30000⌉, wrongly searching records instead of blocks.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-70","question":"A B+ tree indexes 1,000,000 keys. Every leaf holds 100 keys and every internal node has 100 children, and all nodes are completely full. How many node (block) accesses are needed to fetch one record, counting the data block?","options":["5","3","4","6"],"answer":2,"explanation":"Leaves: 1,000,000/100 = 10,000. Next level: 10,000/100 = 100 nodes, then 1 root. Tree height = 3 levels (root, internal, leaf), plus 1 data block = 4. Taking log₁₀₀(10⁶) = 3 and forgetting the data block gives 3.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-71","question":"An ER design has entity sets E1 and E2 joined by a one-to-one relationship R. Both E1 and E2 participate TOTALLY in R, and neither has a multivalued attribute. What is the minimum number of relational tables needed?","options":["2","3","4","1"],"answer":3,"explanation":"With 1:1 and total participation on both sides, every E1 entity pairs with exactly one E2 entity and vice versa, so E1, R and E2 can be merged into one table. With partial participation on one side, 2 tables are needed to avoid NULLs.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-72", "question": "Assertion (A): In SQL, `WHERE dept = NULL` returns no rows even when dept contains NULL values.\nReason (R): A comparison with NULL using = evaluates to UNKNOWN, and WHERE keeps only rows for which the condition is TRUE.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true, R is false", "A is false, R is true"], "answer": 0, "explanation": "NULL = NULL is UNKNOWN, not TRUE, so no row passes. The right test is dept IS NULL. GROUP BY, DISTINCT and set operators are the places where NULLs are treated as equal.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-73", "question": "How many of the following statements are correct?\n1. A phantom read occurs when re-running a query with the same predicate returns new rows inserted and committed by another transaction.\n2. Two-phase locking on individual rows alone is enough to prevent phantoms.\n3. Lost updates can happen under READ UNCOMMITTED.\n4. Snapshot isolation prevents dirty reads and non-repeatable reads but allows write skew.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 3 and 4 are correct. 2 is false: row locks cannot lock rows that do not exist yet; preventing phantoms needs predicate, index-range (next-key) or table locks.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-74","question":"Match each concept with its description:\n(P) Partial dependency  (Q) Transitive dependency  (R) BCNF violation  (S) Multivalued dependency\n(1) A non-prime attribute depends on a non-prime attribute\n(2) A determinant that is not a superkey determines a prime attribute\n(3) A non-prime attribute depends on part of a candidate key\n(4) Two independent sets of values recorded against the same key","options":["P-3, Q-1, R-2, S-4","P-3, Q-1, R-4, S-2","P-3, Q-2, R-1, S-4","P-1, Q-3, R-2, S-4"],"answer":0,"explanation":"Partial dependency breaks 2NF (3); transitive dependency breaks 3NF (1); a non-superkey determining a prime attribute passes 3NF but breaks BCNF (2); independent multi-valued facts are what 4NF removes (4).","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id": "cs-dbms-sql-75", "question": "How many of the following statements about indexing are correct?\n1. A B+ tree stores data pointers only in its leaves, which are linked for range scans.\n2. A B-tree may store data pointers in internal nodes too, so a search can end above the leaf level.\n3. A hash index supports range queries such as salary BETWEEN 40000 AND 60000 efficiently.\n4. A table can have several clustered indexes as long as they are on different columns.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only 1 and 2 are correct. 3 is false: hashing scatters neighbouring keys, so it only helps equality lookups; range queries need an ordered structure like a B+ tree. 4 is false: rows can be physically ordered only one way, so there is at most one clustered index.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-76","question":"A relation is in 2NF, but a non-key attribute depends on another non-key attribute (a transitive dependency on the key). Which normal form removes such dependencies?","options":["1NF","2NF","3NF","4NF"],"answer":2,"explanation":"3NF requires that no non-prime attribute be transitively dependent on a key. 2NF only removes partial dependencies on part of a composite key; 4NF deals with multivalued dependencies.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-77","question":"Which SQL command removes a table completely — its rows, its structure and its definition in the catalogue?","options":["DELETE FROM","TRUNCATE TABLE","ALTER TABLE … REMOVE","DROP TABLE"],"answer":3,"explanation":"DROP TABLE deletes the table object itself. DELETE and TRUNCATE remove rows but keep the empty table; there is no ALTER TABLE … REMOVE command.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-78","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT COUNT(*), COUNT(amount), COUNT(DISTINCT cust) FROM Orders;\n```","options":["6, 5, 4","6, 6, 4","6, 5, 6","5, 5, 4"],"answer":0,"explanation":"COUNT(*) counts all 6 rows; COUNT(amount) skips the NULL amount (5); COUNT(DISTINCT cust) counts Ana, Ben, Chen, Dia = 4. 6, 6, 4 forgets that COUNT(column) ignores NULLs.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-79","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nHow many rows does this query return, and what is the total shown for Delhi?\n```sql\nSELECT city, SUM(amount) FROM Orders GROUP BY city;\n```","options":["2 rows; Delhi = 1400","3 rows; Delhi = 1400","3 rows; Delhi = NULL","2 rows; Delhi = 2100"],"answer":1,"explanation":"GROUP BY puts all NULL cities into one group, so the groups are Pune, Delhi and NULL: 3 rows. SUM ignores the NULL amount in Delhi: 700 + 700 = 1400. A NULL inside a group does not make SUM NULL.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-80","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT AVG(amount) FROM Orders;\n```","options":["400","416.67","480","NULL"],"answer":2,"explanation":"AVG ignores NULLs: (500 + 300 + 700 + 200 + 700) / 5 = 2400 / 5 = 480. 400 divides by all 6 rows, as if the NULL were 0.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-81","question":"Transaction T1 reads a row, transaction T2 then updates that row and commits, and T1 reads the same row again and sees a different value. Which anomaly is this?","options":["Dirty read","Phantom read","Lost update","Non-repeatable read"],"answer":3,"explanation":"Reading the same row twice and getting different committed values is a non-repeatable read. A dirty read sees uncommitted data; a phantom is a new or vanished row in a range query; a lost update overwrites another transaction’s write.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-82","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nTable Customers(name, tier) rows: ('Ana', 'Gold'), ('Ben', 'Silver'), ('Eve', 'Gold').\nHow many rows does this query return?\n```sql\nSELECT cust FROM Orders\nUNION\nSELECT name FROM Customers;\n```","options":["5","9","7","4"],"answer":0,"explanation":"UNION removes duplicates: Ana, Ben, Chen, Dia (from Orders) plus Eve (new from Customers) = 5. 9 is UNION ALL (6 + 3).","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-83","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT cust FROM Orders\nGROUP BY cust\nHAVING COUNT(*) > 1 AND SUM(amount) > 700;\n```","options":["'Ana' and 'Ben'","Only 'Ana'","Only 'Ben'","No rows"],"answer":1,"explanation":"Ana has 2 rows with sum 800 (passes). Ben has 2 rows but SUM ignores his NULL, giving 700, which is not > 700. Chen and Dia have one row each. Choosing Ben too treats the condition as ≥ 700 or the NULL as a value.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-84","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nHow many rows does this query return?\n```sql\nSELECT id FROM Orders WHERE city <> 'Pune';\n```","options":["4","2","3","6"],"answer":2,"explanation":"Rows 2, 4 and 6 (Delhi) qualify. Row 5 has city NULL, and NULL <> 'Pune' evaluates to UNKNOWN, which WHERE treats as false. 4 wrongly counts the NULL row.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-85","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT DISTINCT amount FROM Orders\nWHERE amount IS NOT NULL\nORDER BY amount DESC\nLIMIT 1 OFFSET 1;\n```","options":["700","300","200","500"],"answer":3,"explanation":"Distinct non-NULL amounts in descending order: 700, 500, 300, 200. OFFSET 1 skips the first, so the result is 500 — the second-highest distinct amount. Without DISTINCT the second row would be the duplicate 700.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-86","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nTable Customers(name, tier) rows: ('Ana', 'Gold'), ('Ben', 'Silver'), ('Eve', 'Gold').\nWhat value does this query show for 'Eve'?\n```sql\nSELECT c.name, COUNT(o.id)\nFROM Customers c LEFT JOIN Orders o ON c.name = o.cust\nGROUP BY c.name;\n```","options":["0","1","NULL","Eve does not appear"],"answer":0,"explanation":"The LEFT JOIN keeps Eve with NULLs in all Orders columns. COUNT(o.id) ignores that NULL, giving 0. COUNT(*) would have given 1, because it counts the padded row itself.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-87","question":"R(A, B, C, D, E) has functional dependencies A → BC, CD → E and B → D. Which of the following is a candidate key?","options":["CD","A","BC","B"],"answer":1,"explanation":"A⁺: A → B, C; B → D; CD → E, so A⁺ = ABCDE and A (a single attribute) is a candidate key. CD⁺ = CDE, BC⁺ = BCDE and B⁺ = BD — none reaches A.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-88","question":"Account X holds 100. T1 reads X (100); T2 reads X (100); T1 writes X = 150 and commits; T2 writes X = 80 and commits. What is the final value of X, and what is this anomaly called?","options":["150; lost update","130; dirty read","80; lost update","80; phantom read"],"answer":2,"explanation":"T2’s write was based on its stale read and overwrites T1’s committed change, leaving 80. T1’s update is lost. No uncommitted data was read, so it is not a dirty read, and no rows appear or vanish, so it is not a phantom.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-89","question":"Table Orders has a composite B-tree index on (city, amount). Which WHERE clause can use this index to narrow the search most effectively?","options":["WHERE amount > 500","WHERE amount = 500 OR city = 'Delhi'","WHERE UPPER(city) = 'DELHI'","WHERE city = 'Delhi' AND amount > 500"],"answer":3,"explanation":"A composite index is sorted by city first, then amount, so it serves predicates on its leftmost prefix: an equality on city plus a range on amount is ideal. amount alone skips the leading column; the OR needs both columns independently; wrapping city in a function hides it from a plain index.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-90","question":"Which of these queries is NOT valid in standard SQL?","options":["SELECT cust, amount FROM Orders GROUP BY cust;","SELECT cust, SUM(amount) FROM Orders GROUP BY cust;","SELECT cust FROM Orders GROUP BY cust HAVING MAX(amount) > 300;","SELECT COUNT(*) FROM Orders;"],"answer":0,"explanation":"With GROUP BY, every selected column must be grouped or aggregated; amount is neither, and a group like Ana has two different amounts. (MySQL’s loose mode may accept it and pick an arbitrary value, but it is invalid in standard SQL.)","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-91","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhich ids does this correlated query return?\n```sql\nSELECT id FROM Orders o\nWHERE amount > (SELECT AVG(amount) FROM Orders WHERE city = o.city);\n```","options":["1 and 4","Only 1","1, 4 and 6","1 and 5"],"answer":1,"explanation":"Pune average = (500 + 300)/2 = 400, so id 1 qualifies. Delhi average ignores the NULL: (700 + 700)/2 = 700, and 700 > 700 is false. For id 5, city = NULL matches no rows, the AVG is NULL and the comparison is UNKNOWN. Only id 1. Choosing 4 and 6 averages Delhi over 3 rows (466.67).","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-92","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nFor the order with id 1, what are the values of r and dr?\n```sql\nSELECT id,\n       RANK()       OVER (ORDER BY amount DESC) AS r,\n       DENSE_RANK() OVER (ORDER BY amount DESC) AS dr\nFROM Orders WHERE amount IS NOT NULL;\n```","options":["r = 2, dr = 2","r = 3, dr = 3","r = 3, dr = 2","r = 2, dr = 3"],"answer":2,"explanation":"Amounts in order: 700, 700, 500, … The two 700s share rank 1. RANK leaves a gap, so 500 gets rank 3; DENSE_RANK does not, so 500 gets 2. ROW_NUMBER would give 3 as well, but without ties.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-93","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Orders\nWHERE amount > 250 OR amount <= 250;\n```","options":["6","4","0","5"],"answer":3,"explanation":"The condition looks like a tautology, but for row 2 (amount NULL) both comparisons are UNKNOWN, and UNKNOWN OR UNKNOWN is UNKNOWN, so the row is filtered out. 5 rows remain. 6 assumes two-valued logic.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-94","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nTable Customers(name, tier) rows: ('Ana', 'Gold'), ('Ben', 'Silver'), ('Eve', 'Gold').\nHow many rows does this query return?\n```sql\nSELECT * FROM Orders o\nFULL OUTER JOIN Customers c ON c.name = o.cust;\n```","options":["7","4","9","18"],"answer":0,"explanation":"Matched pairs: Ana × 2 orders + Ben × 2 orders = 4. Unmatched Orders rows (Chen, Dia) add 2, and the unmatched customer Eve adds 1: 4 + 2 + 1 = 7. 4 is the INNER JOIN; 18 is the cross product.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-95","question":"R(A, B, C, D) has FDs A → B and C → D. It is decomposed into R1(A, B), R2(C, D) and R3(A, C). Which statement is correct?","options":["It is lossy, because R1 and R2 share no attribute","The decomposition is lossless and dependency-preserving","It is lossless but not dependency-preserving","It is dependency-preserving but lossy"],"answer":1,"explanation":"AC is the key of R (AC⁺ = ABCD), and R3 contains it. Joining R3 with R1 on A (A → B, A is a key of R1) and then with R2 on C (C → D) is lossless at each step. A → B lives in R1 and C → D in R2, so dependencies are preserved. R1 and R2 need not share attributes because R3 links them.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-96","question":"R(A, B, C, D) has exactly two candidate keys: A and BC. How many superkeys does R have?","options":["12","14","10","4"],"answer":2,"explanation":"Superkeys containing A: 2³ = 8. Containing both B and C: 2² = 4. Containing A, B and C: 2 (counted in both). By inclusion–exclusion 8 + 4 − 2 = 10. 12 forgets to subtract the overlap, 14 adds it instead, and 4 counts only the supersets of BC.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-97","question":"You need the customers who have placed no orders. Orders.cust may contain NULL values. Which query is correct in that case?","options":["SELECT name FROM Customers WHERE name NOT IN (SELECT cust FROM Orders);","SELECT c.name FROM Customers c LEFT JOIN Orders o ON o.cust = c.name WHERE o.cust IS NOT NULL;","SELECT c.name FROM Customers c JOIN Orders o ON o.cust = c.name WHERE o.id IS NULL;","SELECT name FROM Customers c WHERE NOT EXISTS (SELECT 1 FROM Orders o WHERE o.cust = c.name);"],"answer":3,"explanation":"If the subquery returns a NULL, “name NOT IN (…, NULL)” is never TRUE, so the NOT IN version returns no rows at all. NOT EXISTS is unaffected by NULLs. The LEFT JOIN version keeps only matched customers (the test is inverted), and an INNER JOIN never yields NULL ids.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-98","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat values of run does this query give for pid 3, pid 7 and pid 8?\n```sql\nSELECT pid,\n       SUM(budget) OVER (PARTITION BY dept ORDER BY pid) AS run\nFROM Proj;\n```","options":["pid 3: NULL, pid 7: 1300, pid 8: 750","pid 3: NULL, pid 7: NULL, pid 8: 750","pid 3: 0, pid 7: 1300, pid 8: 750","pid 3: NULL, pid 7: 1300, pid 8: 100"],"answer":0,"explanation":"PARTITION BY puts the two NULL-dept rows (pids 5 and 8) in one partition, exactly as GROUP BY would. With ORDER BY the frame runs from the start of the partition to the current row, and SUM skips NULLs. Ops (pids 3, 4, 6): pid 3 has only its own NULL budget in the frame, so the sum is NULL, not 0. R&D (pids 1, 2, 7): at pid 7 the frame holds 900, 400 and NULL, giving 1300 - a NULL in the current row does not make the running sum NULL. NULL partition (pids 5, 8): 650, then 650 + 100 = 750.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-99","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nHow many rows of the result have diff = NULL, and what is diff for pid 6?\n```sql\nSELECT pid,\n       budget - LAG(budget) OVER (ORDER BY pid) AS diff\nFROM Proj;\n```","options":["3 rows are NULL; pid 6 shows -400","5 rows are NULL; pid 6 shows -400","5 rows are NULL; pid 6 shows -150","1 row is NULL; pid 6 shows -400"],"answer":1,"explanation":"LAG returns the budget of the previous row in pid order, and any arithmetic with NULL is NULL. pid 1 has no previous row; pids 3 and 7 have NULL budgets themselves; pids 4 and 8 follow a row whose budget is NULL. That is 5 NULL results. LAG does not skip NULLs or look further back, so pid 6 is compared with pid 5: 250 - 650 = -400. The -150 answer compares pid 6 with pid 4, and the count of 3 forgets the rows that come right after a NULL.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-100","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nIn the row for a.pid = 1, what are x and y?\n```sql\nSELECT a.pid, COUNT(b.pid) AS x, COUNT(c.pid) AS y\nFROM Proj a\nLEFT JOIN Proj b ON b.parent = a.pid\nLEFT JOIN Proj c ON c.parent = b.pid\nGROUP BY a.pid;\n```","options":["x = 2, y = 3","x = 2, y = 2","x = 3, y = 2","x = 3, y = 3"],"answer":2,"explanation":"Project 1 has two children (pids 2 and 3). Project 2 has two children of its own (pids 4 and 5); project 3 has none. After both joins the group for pid 1 therefore has three rows: (1, 2, 4), (1, 2, 5) and (1, 3, NULL). COUNT(b.pid) counts non-NULL b.pid values in those rows, so x = 3 - child 2 is counted twice because the second join duplicated it. COUNT(c.pid) skips the NULL, so y = 2. To count children correctly one would need COUNT(DISTINCT b.pid).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-101","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nWITH RECURSIVE up(pid, parent, budget) AS (\n  SELECT pid, parent, budget FROM Proj WHERE pid = 8\n  UNION ALL\n  SELECT p.pid, p.parent, p.budget\n  FROM Proj p JOIN up ON p.pid = up.parent)\nSELECT COUNT(*), SUM(budget) FROM up;\n```","options":["(5, 1650)","(1, 100)","(4, 1950)","(5, 2050)"],"answer":3,"explanation":"The anchor row is project 8. Each recursive step joins p.pid to the parent of a row already found, so it climbs towards the root: 8 -> 6 -> 4 -> 2 -> 1, and stops because project 1 has parent NULL, which joins to nothing. Five rows with budgets 100 + 250 + 400 + 400 + 900 = 2050. (1, 100) would be the result if the join went downwards (p.parent = up.pid), since project 8 has no children; (4, 1950) leaves out the anchor row.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-102","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhich pids does this query return?\n```sql\nSELECT pid FROM Proj p\nWHERE 1 = (SELECT COUNT(DISTINCT q.budget)\n           FROM Proj q\n           WHERE q.dept = p.dept AND q.budget > p.budget);\n```","options":["pids 2 and 6","pids 2, 4 and 6","pids 2, 6 and 8","pids 1 and 4"],"answer":0,"explanation":"For each row the subquery counts the distinct budgets in the same department that are strictly larger; a count of 1 means the row holds the second-highest budget of its department. R&D has 900, 400 and NULL: pid 2 (400) has exactly one larger value. Ops has NULL, 400 and 250: pid 6 (250) has one larger value. Rows with a NULL budget or a NULL dept make the WHERE of the subquery unknown for every q, so their count is 0 and they are not returned - which is why pid 8 does not appear even though 650 > 100 among the NULL-dept rows. Pids 1 and 4 are the highest of their departments (count 0).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-103","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nTable Team(lead, city) rows: ('Uma', 'Pune'), ('Vik', 'Goa'), ('Wen', NULL), ('Zed', 'Pune').\nHow many rows does this query return, and what is the row for 'Zed'?\n```sql\nSELECT t.lead, COUNT(p.pid), COUNT(*)\nFROM Team t\nLEFT JOIN Proj p ON p.lead = t.lead AND p.budget > 300\nGROUP BY t.lead;\n```","options":["4 rows; ('Zed', 0, 0)","4 rows; ('Zed', 0, 1)","3 rows; there is no row for 'Zed'","4 rows; ('Zed', 1, 1)"],"answer":1,"explanation":"A LEFT JOIN keeps every Team row. Zed leads no project, so he gets one row padded with NULLs: COUNT(p.pid) ignores the NULL and gives 0, but COUNT(*) counts the padded row itself and gives 1. Because the budget test is in the ON clause and not in WHERE, unmatched leads are kept rather than filtered out, so there are 4 rows (Uma, Vik and Wen each match exactly one project with budget above 300). COUNT(*) can never be 0 for a group that exists.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-104","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhich rows does this query return?\n```sql\nSELECT pid FROM Proj\nWHERE NOT (dept = 'Ops' AND budget > 300);\n```","options":["4 rows: pids 1, 2, 6, 7","7 rows: every pid except 4","5 rows: pids 1, 2, 6, 7, 8","3 rows: pids 1, 2, 6"],"answer":2,"explanation":"Evaluate the AND with three-valued logic, then negate. FALSE AND anything is FALSE, so NOT gives TRUE: pids 1, 2, 7 (dept is 'R&D', even though pid 7's budget is NULL), pid 6 (budget 250 fails) and pid 8 (dept is NULL, but 100 > 300 is FALSE, so the AND is FALSE). Pid 4 makes the AND TRUE. Pid 3 (TRUE AND unknown) and pid 5 (unknown AND TRUE) give unknown, and NOT unknown is still unknown, so they are dropped. Treating NULL comparisons as simply false would return all rows except pid 4.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-105","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nSELECT lead, COUNT(CASE WHEN budget >= 400 THEN 1 END) AS big\nFROM Proj\nGROUP BY lead\nHAVING SUM(CASE WHEN dept = 'Ops' THEN budget END) IS NULL;\n```","options":["1 row: ('Uma', 1)","2 rows: ('Xia', 1), ('Yash', 0)","3 rows: ('Uma', 1), ('Xia', 1), ('Yash', 1)","3 rows: ('Uma', 1), ('Xia', 1), ('Yash', 0)"],"answer":3,"explanation":"A CASE with no ELSE yields NULL when no branch matches, and SUM over only NULLs is NULL. Uma's Ops project has a NULL budget, so her Ops sum is NULL and she qualifies; Xia and Yash have no Ops project at all, so theirs is NULL too. Vik (250) and Wen (400) have real Ops sums and are removed. COUNT counts only the rows where the CASE gives 1: Uma has 900, Xia has 650, and Yash's only budget is NULL, so his count is 0 - COUNT never returns NULL. Leaving Uma out confuses 'has an Ops project' with 'has a non-NULL Ops total'.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-106","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhich pids does this query return?\n```sql\nSELECT pid FROM (\n  SELECT pid, budget,\n         AVG(budget) OVER (PARTITION BY lead) AS a\n  FROM Proj) t\nWHERE budget > a;\n```","options":["pids 2 and 4","pids 1, 2 and 4","pids 1 and 5","pids 1, 2, 4 and 5"],"answer":0,"explanation":"AVG ignores NULLs. Uma: budgets 900 and NULL, average 900, and 900 > 900 is false. Vik: 400 and 250, average 325, so pid 2 qualifies. Wen: 400 and 100, average 250, so pid 4 qualifies. Xia has one project (650 is not above its own average) and Yash's only budget is NULL. Result: pids 2 and 4. Pid 1 appears only if the NULL is wrongly counted as 0 (average 450); pids 1 and 5 are the rows above the overall average, which ignores the PARTITION BY.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-107","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nAfter this statement runs, which rows remain in Proj?\n```sql\nDELETE FROM Proj\nWHERE budget < (SELECT AVG(budget) FROM Proj);\n```","options":["2 rows: pids 1, 5","4 rows: pids 1, 3, 5, 7","6 rows: every pid except 6 and 8","5 rows: pids 1, 2, 3, 5, 7"],"answer":1,"explanation":"The subquery is evaluated once on the table as it was before the delete: AVG ignores the two NULLs, giving (900 + 400 + 400 + 650 + 250 + 100)/6 = 450. Rows with budget below 450 are deleted: pids 2, 4, 6 and 8. For pids 3 and 7 the test NULL < 450 is unknown, so they are not deleted. Remaining: 1, 3, 5, 7. Counting the NULLs as 0 would give an average of 337.5 and delete only pids 6 and 8; assuming NULL rows are also removed leaves only pids 1 and 5.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-108","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nSELECT COUNT(*)\nFROM Proj a JOIN Proj b ON a.budget = b.budget;\n```","options":["12","6","8","10"],"answer":2,"explanation":"Each row joins with every row that has an equal budget, including itself. Budgets 900, 650, 250 and 100 occur once, giving 1 pair each. Budget 400 occurs twice (pids 2 and 4), giving 2 x 2 = 4 pairs. The two NULL budgets match nothing, not even themselves, because NULL = NULL is unknown. Total 4 + 4 = 8. The answer 6 counts each non-NULL row once; 12 lets the two NULL rows pair up with each other (another 4 pairs).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-109","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nTable Team(lead, city) rows: ('Uma', 'Pune'), ('Vik', 'Goa'), ('Wen', NULL), ('Zed', 'Pune').\nBoth queries try to list the leads who have no R&D project. What do they return?\n```sql\n-- Q1\nSELECT t.lead FROM Team t\nLEFT JOIN Proj p ON p.lead = t.lead AND p.dept = 'R&D'\nWHERE p.pid IS NULL;\n-- Q2\nSELECT DISTINCT t.lead FROM Team t\nLEFT JOIN Proj p ON p.lead = t.lead\nWHERE p.dept <> 'R&D' OR p.pid IS NULL;\n```","options":["Q1: Wen, Zed. Q2: Zed","Q1: Wen, Zed. Q2: Wen, Zed","Q1: Zed. Q2: Uma, Vik, Wen, Zed","Q1: Wen, Zed. Q2: Uma, Vik, Wen, Zed"],"answer":3,"explanation":"Q1 joins each lead only to their R&D projects; a lead with none gets a NULL-padded row, which the IS NULL test keeps. Uma and Vik each lead an R&D project, so Q1 returns Wen and Zed - the correct anti-join. Q2 joins to all projects and then keeps any row whose dept differs from 'R&D'. Uma and Vik each also lead an Ops project, so they pass that row-level test and are listed even though they do have R&D work. Wen appears through the Ops project (pid 4); Wen's NULL-dept project fails the <> test but that does not matter. Q2 therefore returns all four leads.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-110","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return under standard SQL semantics?\n```sql\nSELECT COUNT(*) FROM Proj\nWHERE budget > ALL (SELECT budget FROM Proj WHERE dept = 'HR');\n```","options":["8","6","0","The query fails with an error"],"answer":0,"explanation":"No project belongs to 'HR', so the subquery returns an empty set. A comparison with ALL over an empty set is TRUE for every row - there is no value that could make it fail - and this holds even for the two rows whose budget is NULL, because no comparison is ever carried out. All 8 rows are counted. The answer 6 assumes the NULL budgets drop out; 0 would be the result of > ANY, which is FALSE over an empty set.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-111","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nSELECT COUNT(DISTINCT dept), COUNT(*)\nFROM (SELECT dept FROM Proj GROUP BY dept) g;\n```","options":["(3, 3)","(2, 3)","(2, 2)","(2, 8)"],"answer":1,"explanation":"GROUP BY treats all NULL depts as one group, so the inner query returns three rows: 'R&D', 'Ops' and NULL. COUNT(*) counts rows and gives 3. COUNT(DISTINCT dept) ignores NULL and gives 2. So NULLs are 'equal' for grouping but invisible to COUNT(column) - both rules apply in the same query.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-112","question":"R(A, B, C, D, E, F) has functional dependencies AB → C, C → A, C → D, D → B and E → F. How many candidate keys does R have, and what is its highest normal form?","options":["2 candidate keys; 1NF","3 candidate keys; 2NF","3 candidate keys; 1NF","1 candidate key; 3NF"],"answer":2,"explanation":"E appears on no right-hand side, so every key contains E, and E alone gives only {E, F}. CE: C gives A and D, D gives B, E gives F - a key. ABE: AB gives C, then D, and E gives F - a key. ADE: D gives B, then AB gives C - a key. No other minimal set works (BE, DE and AE do not reach C), so there are 3 keys: CE, ABE, ADE. F is the only non-prime attribute and E → F makes it depend on a proper part of every key, a partial dependency. So R is not in 2NF and its highest normal form is 1NF.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-113","question":"R(A, B, C, D, E) has functional dependencies AB → C, C → D, D → E and E → A. Which statement is correct?","options":["4 candidate keys; R is in 3NF but not BCNF, and only one of the given FDs violates BCNF","4 candidate keys; R is in BCNF","1 candidate key (AB); R is in 2NF but not 3NF","4 candidate keys; R is in 3NF but not BCNF, and three of the given FDs violate BCNF"],"answer":3,"explanation":"B is on no right-hand side, so every key contains B. AB gives C, D, E: a key. BC gives D, E, A: a key. BD gives E, A, C: a key. BE gives A, C, D: a key. With keys AB, BC, BD and BE every attribute is prime, so no FD can break 3NF. For BCNF every determinant must be a superkey: AB is, but C, D and E alone are not, so C → D, D → E and E → A all violate BCNF. Stopping at the first key AB makes C → D look like a transitive dependency of a non-prime attribute, which is the trap behind the 2NF answer.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-114","question":"The set F = { A → B, BC → D, AC → D, D → E, CE → A } holds on R(A, B, C, D, E). Which of the following dependencies is redundant, i.e. can be removed from F without changing its closure?","options":["AC → D","BC → D","D → E","CE → A"],"answer":0,"explanation":"An FD X → Y is redundant if Y is in the closure of X computed from the other FDs. Without AC → D: {A, C}+ gains B (A → B) and then D (BC → D), so AC → D is still implied and can be dropped. Without BC → D: {B, C}+ = {B, C} only. Without D → E: {D}+ = {D}. Without CE → A: {C, E}+ = {C, E}. So only AC → D is redundant; the others each carry information nothing else supplies.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-115","question":"R(A, B, C, D) with functional dependencies A → B, B → C and C → D is decomposed into R1(A, B), R2(B, C) and R3(A, D). Which statement about this decomposition is correct?","options":["It is lossless and dependency preserving","It is lossless but not dependency preserving","It is lossy but dependency preserving","It is lossy and not dependency preserving"],"answer":1,"explanation":"Lossless: R1 and R3 share A, and A is a key of both, so joining them gives (A, B, D) without spurious tuples; that result shares B with R2, and B → C makes B a key of R2, so the second join is lossless too. Dependency preservation: A → B is in R1 and B → C in R2, but C and D never appear together. R3 only carries A → D, and from A → B, B → C and A → D one cannot derive C → D (the closure of C is just {C}). So C → D can be checked only by joining, and the decomposition is not dependency preserving.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-116","question":"R(A, B, C, D, E) has functional dependencies A → B, BC → D, D → AE and E → C. How many of the following dependencies are logically implied?\n1. AC → E\n2. B → C\n3. BE → A\n4. D → B","options":["4","2","3","1"],"answer":2,"explanation":"Use attribute closures. {A, C}+: A gives B, BC gives D, D gives A and E - so AC → E holds. {B}+ = {B}: nothing fires, so B → C does not hold. {B, E}+: E gives C, BC gives D, D gives A - so BE → A holds. {D}+: D gives A and E, A gives B - so D → B holds. Three of the four are implied; only statement 2 fails.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-117","question":"A relation r(A, B, C, D) currently holds exactly these five tuples:\n(1, 2, 3, 4)\n(1, 2, 5, 6)\n(2, 2, 3, 4)\n(3, 4, 5, 4)\n(3, 4, 3, 6)\nHow many of the dependencies A → B, B → C, AC → D, BD → A, CD → B and D → C are satisfied by this instance?","options":["5","2","4","3"],"answer":3,"explanation":"An FD X → Y is violated when two tuples agree on X but differ on Y. A → B holds (1 → 2, 2 → 2, 3 → 4). B → C fails: B = 2 goes with C = 3 and C = 5. AC → D holds: the pairs (1,3), (1,5), (2,3), (3,5), (3,3) are all different. BD → A fails: tuples 1 and 3 share (B, D) = (2, 4) but have A = 1 and A = 2. CD → B holds: (3,4) → 2 twice, and (5,6), (5,4), (3,6) occur once each. D → C fails: D = 4 goes with C = 3 and C = 5. So A → B, AC → D and CD → B are satisfied: 3.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-118","question":"Consider the schedule R2(A); R3(B); W1(A); R2(C); W1(C); W2(B); R4(A); W4(C). Which statement is correct?","options":["It is conflict serializable, and the only equivalent serial order is T3, T2, T1, T4","It is conflict serializable, and the only equivalent serial order is T2, T3, T1, T4","It is conflict serializable, and both T3, T2, T1, T4 and T2, T3, T1, T4 are equivalent serial orders","It is not conflict serializable"],"answer":0,"explanation":"Precedence edges: R2(A) before W1(A) gives T2 → T1. R3(B) before W2(B) gives T3 → T2. R2(C) before W1(C) gives T2 → T1 again. W1(A) before R4(A) gives T1 → T4, and R2(C), W1(C) before W4(C) give T2 → T4 and T1 → T4. The graph T3 → T2 → T1 → T4 (plus T2 → T4) has no cycle, so the schedule is conflict serializable, and its only topological order is T3, T2, T1, T4. T2 cannot come before T3 because T3 read B before T2 overwrote it.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-119","question":"Consider the schedule R1(A); W2(A); W2(B); W1(A); W1(B); W3(A); W3(B). Which statement is correct?","options":["It is conflict serializable, equivalent to the serial order T1, T2, T3","It is not conflict serializable, but it is view serializable, equivalent only to the serial order T1, T2, T3","It is not conflict serializable, but it is view serializable, equivalent to both T1, T2, T3 and T2, T1, T3","It is neither conflict serializable nor view serializable"],"answer":1,"explanation":"R1(A) before W2(A) gives T1 → T2, while W2(A) before W1(A) gives T2 → T1: a cycle, so the schedule is not conflict serializable. For view equivalence only three things matter: T1's read of A must see the initial value, and the final writes of A and B must both come from T3. The serial order T1, T2, T3 satisfies all three. In T2, T1, T3 the read R1(A) would see T2's value instead of the initial one, so that order is not view equivalent, and any order with T3 not last changes the final writes. The writes of T2 and T1 are overwritten by T3's blind writes, which is what makes view serializability possible here.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-120","question":"T1 executes R1(A); W1(A); R1(B) and T2 executes R2(B); W2(B); R2(A). Of the 20 possible interleavings of these two transactions (including the two serial ones), how many are conflict serializable?","options":["10","2","8","12"],"answer":2,"explanation":"The only conflicting pairs are W1(A) with R2(A) and R1(B) with W2(B). The schedule is equivalent to T1, T2 only if W1(A) precedes R2(A) and R1(B) precedes W2(B). The second condition forces all of T1 before W2(B), so only R2(B) is free to sit in any of 4 positions among T1's three operations: 4 schedules. By symmetry, equivalence to T2, T1 needs W2(B) before R1(B) and R2(A) before W1(A), leaving only R1(A) free: 4 more. Every other interleaving has edges in both directions. Total 8, not just the 2 serial schedules.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-121","question":"No transaction has committed yet in the schedule W1(A); R2(A); W2(B); R3(B); W4(B); R5(B). T1 now aborts. Besides T1, which transactions must be rolled back?","options":["T2, T3 and T5","T2 only","T2, T3, T4 and T5","T2 and T3"],"answer":3,"explanation":"A transaction must be rolled back if it read a value written by a transaction that is being rolled back. T2 read A from T1, so T2 goes. T3 read B from T2, so T3 goes as well - a cascade. T4 only wrote B without reading anything, so it depends on no one, and T5 read B after T4's write, so it saw T4's value, not T2's. T4 and T5 survive. Rolling back T5 confuses 'read the item B' with 'read T2's version of B'.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-122","question":"A lock manager grants a request whenever it is compatible with the locks currently held; otherwise the requester waits. The requests arrive in this order: T1 exclusive on A (granted); T2 exclusive on B (granted); T3 shared on C (granted); T1 shared on B; T2 exclusive on C; T4 shared on C; T3 exclusive on A; T4 shared on A. Which statement about the resulting wait-for graph is correct?","options":["It has two cycles; aborting T3 alone does not clear the deadlock, but aborting T2 alone does","It has one cycle, T1 → T2 → T3 → T1; aborting any one of these three clears the deadlock","It has two cycles; aborting T4 alone clears the deadlock","It has no cycle, because T4's shared lock on C is compatible with T3's"],"answer":0,"explanation":"T1 waits for T2 (B). T2's exclusive request on C conflicts with T3's shared lock, so T2 waits for T3. T4's shared request on C is compatible with the lock actually held (T3's shared lock), so it is granted - and now T2 waits for T4 as well. T3 waits for T1 (A) and T4 waits for T1 (A). Edges: T1 → T2, T2 → T3, T2 → T4, T3 → T1, T4 → T1, giving the cycles T1 → T2 → T3 → T1 and T1 → T2 → T4 → T1. Aborting T3 or T4 breaks only one cycle; aborting T1 or T2, which lie on both, clears the deadlock.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-123","question":"Transactions T1, T2 and T3 have timestamps 1, 2 and 3. All read and write timestamps of items A and C are initially 0, and the operations arrive in this order: R3(A); W2(C); W1(C); W2(A). Which transactions are rolled back under basic timestamp ordering, and which under timestamp ordering with Thomas's write rule?","options":["Basic: T1 and T2. With Thomas's write rule: T1 and T2","Basic: T1 and T2. With Thomas's write rule: T2 only","Basic: T1 only. With Thomas's write rule: none","Basic: T2 only. With Thomas's write rule: T2 only"],"answer":1,"explanation":"R3(A) sets read-TS(A) = 3. W2(C) sets write-TS(C) = 2. W1(C): T1's timestamp 1 is below write-TS(C) = 2 while read-TS(C) = 0, so it is an obsolete write - basic timestamp ordering rolls T1 back, but Thomas's write rule simply ignores the write and lets T1 continue. W2(A): T2's timestamp 2 is below read-TS(A) = 3, meaning a younger transaction has already read A; this write must be rejected and T2 rolled back under both schemes. Thomas's rule only forgives writes that are too late relative to another write, never relative to a read.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-124","question":"A B+ tree uses 4096-byte blocks, 12-byte search keys, 8-byte block pointers and 10-byte record pointers. An internal node with p child pointers stores p - 1 keys; a leaf stores n (key, record pointer) pairs plus one block pointer to the next leaf. What are the largest possible p and n?","options":["p = 205, n = 186","p = 204, n = 186","p = 205, n = 185","p = 341, n = 185"],"answer":2,"explanation":"Internal node: 8p + 12(p - 1) ≤ 4096 gives 20p ≤ 4108, so p = 205 (205 pointers and 204 keys use 4088 bytes). Leaf: 22n + 8 ≤ 4096 gives n ≤ 185.8, so n = 185 (4078 bytes); 186 pairs would need 4100 bytes once the next-leaf pointer is included. Forgetting that pointer gives n = 186, forgetting the '- 1' on the keys gives p = 204, and p = 341 counts only the 12-byte keys.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-125","question":"A B+ tree holds 10,000 keys in its leaves. A leaf holds at most 20 and at least 10 keys; an internal node has at most 30 and at least 15 children; the root, when it is not a leaf, has at least 2 children. What are the minimum and the maximum possible number of levels (counting the root level and the leaf level)?","options":["Minimum 3, maximum 5","Minimum 3, maximum 3","Minimum 4, maximum 4","Minimum 3, maximum 4"],"answer":3,"explanation":"Fewest levels: pack every node. 10,000/20 = 500 leaves, 500/30 → 17 internal nodes, and one root over those 17: 3 levels (two levels could hold only 30 x 20 = 600 keys). Most levels: fill every node as little as allowed. A tree with h levels needs at least 2 x 15^(h-2) x 10 keys: h = 4 needs 2 x 225 x 10 = 4,500, which 10,000 keys can supply (for example 1,000 leaves, 66 nodes, 4 nodes, root), but h = 5 needs 67,500. So between 3 and 4 levels.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-126","question":"A file has 200,000 fixed-length records of 200 bytes stored unspanned in 1024-byte blocks. A secondary index is built on a non-ordering key field: each index entry is a 12-byte key plus an 8-byte pointer, and the index is made multilevel until the top level fits in one block. How many index levels are there, and how many block accesses does it take to fetch a record by this key?","options":["4 levels; 5 block accesses","3 levels; 4 block accesses","4 levels; 4 block accesses","1 level; 13 block accesses"],"answer":0,"explanation":"A secondary index on a non-ordering field must be dense: one entry per record, 200,000 entries. Each block holds floor(1024/20) = 51 entries. Level 1: ceil(200,000/51) = 3,922 blocks. Level 2: ceil(3,922/51) = 77 blocks. Level 3: ceil(77/51) = 2 blocks. Level 4: 1 block. A search reads one block per level and then the data block: 4 + 1 = 5 accesses. The 3-level answer builds a sparse index with one entry per data block (40,000 entries), which is possible only on the ordering field. Binary search on level 1 alone would cost ceil(log2 3,922) + 1 = 13 accesses.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-127","question":"Relations R (1000 blocks) and S (200 blocks) are joined with a block nested-loop join using M = 52 buffer blocks: M - 2 blocks hold a chunk of the outer relation, one block scans the inner relation and one collects output. The cost in block reads is b(outer) + ceil(b(outer)/(M - 2)) x b(inner). What is the cheapest cost obtainable by choosing the outer relation well?","options":["5000 block reads","4200 block reads","200,200 block reads","1200 block reads"],"answer":1,"explanation":"With S as the outer relation: 200 + ceil(200/50) x 1000 = 200 + 4 x 1000 = 4200. With R as the outer relation: 1000 + ceil(1000/50) x 200 = 1000 + 20 x 200 = 5000. The smaller relation should be the outer one because it needs fewer passes over the inner relation. 200,200 is the cost with only one buffer block for the outer relation (200 + 200 x 1000); 1200 would need the whole of S to fit in memory at once.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-128","question":"Table Product(pid, cat, price) rows: (1, 'X', 10), (2, 'X', 20), (3, 'Y', 20), (4, NULL, 30), (5, 'Y', NULL), (6, 'Z', 5).\nHow many rows does this query return?\n```sql\nSELECT cat, COUNT(*)\nFROM Product\nGROUP BY cat\nHAVING AVG(price) > 12;\n```","options":["3","2","1","4"],"answer":0,"explanation":"Groups: X avg 15, Y avg 20 (NULL ignored), NULL-category group avg 30, Z avg 5. Three groups pass, including the NULL group.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-129","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nHow many rows does this query return?\n```sql\nSELECT dept, MAX(pay) - MIN(pay)\nFROM Staff\nGROUP BY dept\nHAVING COUNT(pay) = COUNT(*);\n```","options":["3","2","0","1"],"answer":1,"explanation":"GROUP BY makes three groups: Ops, Tech and NULL (Esha). Tech fails HAVING because Dev's pay is NULL (COUNT(pay) = 2 ≠ 3). Ops and the NULL group both pass, so 2 rows.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-130","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT COUNT(*), SUM(pay), MAX(pay)\nFROM Staff\nWHERE pay > 100;\n```","options":["0, 0, NULL","No rows (empty result)","0, NULL, NULL","0, 0, 0"],"answer":2,"explanation":"No row has pay > 100. COUNT of an empty set is 0, but SUM and MAX of an empty set are NULL, not 0; the single summary row is still returned.","difficulty":"moderate","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-131","question":"Consider the schedule W2(A), R1(A), R2(A), W3(A), R3(A), R1(C). Which statement is correct?","options":["It is not conflict serializable","Conflict serializable, equivalent only to T1 → T2 → T3","Conflict serializable, equivalent only to T1 → T3 → T2","Conflict serializable, equivalent only to T2 → T1 → T3"],"answer":3,"explanation":"Conflict edges: T1→T3, T2→T1, T2→T3. The graph is acyclic and its only topological order is T2 → T1 → T3.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-132","question":"TS(T1) = 25, TS(T2) = 5, TS(T3) = 30; all read/write timestamps start at 0. Under basic timestamp ordering (no Thomas write rule), which operation of the schedule W2(A), R3(B), W1(A), W3(A), W3(B), W2(B), R2(A), R1(A) is the first to make its transaction roll back?","options":["W2(B) (operation 6)","W2(A) (operation 1)","No operation is rejected","W1(A) (operation 3)"],"answer":0,"explanation":"Track read-TS and write-TS of each item. W2(B) (operation 6) is the first operation that violates the protocol (a read of a value with a newer write-TS, or a write after a newer read or write).","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-133","question":"R(A, B, C, D, E) has functional dependencies DE → B, C → E, D → AC. What is the highest normal form R satisfies?","options":["BCNF","2NF but not 3NF","1NF but not 2NF","3NF but not BCNF"],"answer":1,"explanation":"Candidate keys: {D}. No partial dependency exists, but C → E has a non-superkey left side and a non-prime right side (prime attributes: D), so 3NF fails.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-134","question":"R(A, B, C, D, E, F) has functional dependencies C → B, F → C, DF → B, B → F, A → F. What is the closure {AE}⁺?","options":["{ABCDEF}","{ABCE}","{ABCEF}","{AEF}"],"answer":2,"explanation":"Keep applying any FD whose left side is already inside the set until nothing changes; one pass in listed order is not enough. The result is {ABCEF}.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-135","question":"R(A, B, C, D, E) with functional dependencies B → E, CE → B, C → E, E → C is decomposed into R1(A, C, E), R2(A, B, D), R3(B, C). Which statement is correct?","options":["Lossless join but not dependency preserving","Dependency preserving but not lossless join","Neither lossless join nor dependency preserving","Lossless join and dependency preserving"],"answer":3,"explanation":"The chase (tableau) test produces an all-distinguished row, so the join is lossless. Every FD of F follows from the FDs projected onto the parts, so dependencies are preserved.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-136","question":"Classify the schedule W1(B), R3(A), W2(B), R2(B), W1(A), C2, C1, W3(B), C3 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Cascadeless but not strict","Recoverable but not cascadeless","Strict","Not recoverable"],"answer":0,"explanation":"Every read is of committed data (cascadeless), but some transaction overwrites an item whose earlier writer has not committed yet, which strictness forbids.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-137","question":"Table Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat does this query return?\n```sql\nSELECT AVG(c) FROM (SELECT COUNT(*) AS c FROM Takes GROUP BY sid);\n```","options":["1.2","1.5","1.25","2"],"answer":1,"explanation":"Courses per sid: 1 → 2, 2 → 1, 3 → 2, 5 → 1. The average of these four counts is 6/4 = 1.5.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-138","question":"R(A, B, C, D, E, F) has FDs A → BCE, C → ABD, DF → BE. Each option is a relation schema obtained by projecting R, with the dependencies implied on its attributes. Which one is NOT in BCNF?","options":["(B, E, F)","(B, D, F)","(B, C, F)","(B, D, E)"],"answer":2,"explanation":"Project the closure of the given FDs onto each schema. On (B, C, F), C → B holds but C is not a key of the projection, so BCNF fails; on the other three every projected FD has a key on the left (or none is non-trivial).","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-139","question":"For the schedule W4(B), R1(B), R2(A), R1(C), R3(B), R4(A), R3(C), W2(C), how many serial schedules of T1–T4 are conflict-equivalent to it?","options":["4","1","3","2"],"answer":3,"explanation":"Precedence edges: T1→T2, T3→T2, T4→T1, T4→T3. Counting the topological orders of this DAG gives 2.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-140","question":"For the schedule R1(B), W1(B), R2(C), W3(C), R3(B), R4(B), R2(B), R4(A), how many serial schedules of T1–T4 are conflict-equivalent to it?","options":["3","4","6","2"],"answer":0,"explanation":"Precedence edges: T1→T2, T1→T3, T1→T4, T2→T3. Counting the topological orders of this DAG gives 3.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-141","question":"Assertion (A): A schedule produced under the basic timestamp-ordering protocol with Thomas's write rule is always conflict serializable.\nReason (R): Thomas's write rule ignores an obsolete write instead of rolling back its transaction.","options":["Both A and R are true, and R is the correct explanation of A","A is false, but R is true","A is true, but R is false","Both A and R are true, but R is not the correct explanation of A"],"answer":1,"explanation":"Ignoring obsolete writes can admit schedules that are view serializable but not conflict serializable (blind writes), so A is false. R correctly describes the rule.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-142","question":"Table Stu(sid, sname) rows: (1, 'Om'), (2, 'Pia'), (3, 'Raj'), (4, 'Sia').\nTable Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat counts do Query 1 and Query 2 return?\n```sql\n-- Query 1\nSELECT COUNT(*) FROM Stu s LEFT JOIN Takes t\n  ON s.sid = t.sid WHERE t.marks >= 70;\n-- Query 2\nSELECT COUNT(*) FROM Stu s LEFT JOIN Takes t\n  ON s.sid = t.sid AND t.marks >= 70;\n```","options":["3 and 3","5 and 3","3 and 5","5 and 5"],"answer":2,"explanation":"In Query 1 the WHERE runs after the outer join and drops every row whose marks are NULL or < 70, leaving 3. In Query 2 the condition is part of ON: Om matches 1 row, Raj 2, and Pia and Sia each keep one NULL-padded row, so 5.","difficulty":"very-hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-143","question":"Keys 7, 53, 17, 43, 38, 5, 27, 50, 47, 10 are inserted in this order into an empty B+ tree where a node holds at most 3 keys; an overflowing leaf with 4 keys keeps the first 2 and moves the rest to a new right leaf, copying the new leaf's first key up; an overflowing internal node with 4 keys keeps the first 2, moves the next key up and puts the rest in a new right node. After all insertions, how many leaf nodes are there and what is the height (number of levels)?","options":["5 leaves, height 2","3 leaves, height 2","4 leaves, height 3","4 leaves, height 2"],"answer":3,"explanation":"Simulating the splits gives leaves 5,7,10 | 17,27,38 | 43,47 | 50,53 and root keys [17, 43, 50], so 4 leaves at height 2.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-144","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT COUNT(DISTINCT rep)\nFROM Sale\nWHERE region = 'N'\n  AND rep IN (SELECT rep FROM Sale WHERE region = 'S');\n```","options":["2","3","1","4"],"answer":0,"explanation":"N reps: Ira, Kim, Jai, Ira; of these, Ira and Jai also appear in S. DISTINCT counts them once each: 2.","difficulty":"moderate","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-145","question":"R(A, B) has 8 tuples. What is the number of tuples in R ⋈ R (natural join of R with itself), and in R × ρ_{S(C, D)}(R)?","options":["64 and 64","8 and 64","8 and 8","16 and 64"],"answer":1,"explanation":"Joining R with itself on all attributes matches each tuple only with itself, giving R back (8). Renaming the attributes leaves no common attribute, so the join becomes a Cartesian product: 64.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-146","question":"R(A, B, C, D, E, F) has FDs B → AC, E → F, EF → BD, F → E. Each option is a relation schema obtained by projecting R, with the dependencies implied on its attributes. Which one is NOT in BCNF?","options":["(A, D, E)","(A, C, F)","(A, B, E)","(A, D, F)"],"answer":2,"explanation":"Project the closure of the given FDs onto each schema. On (A, B, E), B → A holds but B is not a key of the projection, so BCNF fails; on the other three every projected FD has a key on the left (or none is non-trivial).","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-147","question":"On R(A, B, C, D, E), F = {D → A, B → AE} and G = {BE → A, D → A, B → E}. Which statement is correct? (\"F covers G\" means every FD of G is in F⁺.)","options":["G covers F, but F does not cover G","Neither covers the other","F covers G, but G does not cover F","F and G are equivalent"],"answer":3,"explanation":"Check each FD of one set by its LHS closure under the other set. F covers G: yes; G covers F: yes.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-148","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT region, AVG(amt), COUNT(amt), COUNT(*)\nFROM Sale\nWHERE region = 'S'\nGROUP BY region;\n```","options":["S, 250, 1, 2","S, 250, 2, 2","S, 125, 2, 2","S, 125, 1, 2"],"answer":0,"explanation":"The S group has two rows, one with NULL amt. AVG and COUNT(amt) ignore the NULL (250 and 1); COUNT(*) still counts both rows.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-149","question":"A multilevel index is built over a first level of 250,000 index entries; every index block holds 68 entries (fan-out 68), and levels are added until the top level fits in one block. How many index levels are there in total, and how many block accesses does a lookup take including one data-block read?","options":["3 levels, 3 accesses","3 levels, 4 accesses","4 levels, 5 accesses","2 levels, 3 accesses"],"answer":1,"explanation":"Blocks per level: 3677 → 55 → 1; the levels shrink by a factor 68 until one block remains, giving 3 levels. A lookup reads one block per level plus the data block: 4.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-150","question":"TS(T1) = 10, TS(T2) = 25, TS(T3) = 20; all read/write timestamps start at 0. Under basic timestamp ordering (no Thomas write rule), which operation of the schedule W3(B), R3(B), W2(A), W1(B), W2(B), R1(B), R2(A), R1(A) is the first to make its transaction roll back?","options":["No operation is rejected","R1(B) (operation 6)","W1(B) (operation 4)","W2(A) (operation 3)"],"answer":2,"explanation":"Track read-TS and write-TS of each item. W1(B) (operation 4) is the first operation that violates the protocol (a read of a value with a newer write-TS, or a write after a newer read or write).","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-151","question":"Classify the schedule R3(B), R3(A), W3(A), W1(A), R2(B), W1(B), W2(A), R1(B).","options":["Conflict serializable but not view serializable","View serializable but not conflict serializable","Conflict serializable (hence also view serializable)","Neither conflict nor view serializable"],"answer":3,"explanation":"The precedence graph has a cycle, and no serial order reproduces the same reads-from pairs and final writes, so it is not even view serializable.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-152","question":"Table Stu(sid, sname) rows: (1, 'Om'), (2, 'Pia'), (3, 'Raj'), (4, 'Sia').\nTable Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Takes t\nWHERE t.sid NOT IN (SELECT sid FROM Stu)\n   OR t.marks IS NULL;\n```","options":["2","0","3","1"],"answer":0,"explanation":"Stu.sid has no NULLs, so NOT IN works normally: only sid 5 (an orphan row) is missing. Om's C2 row has NULL marks. Two rows.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-153","question":"Table P(x) rows: (1), (2), (2), (3), (NULL).\nTable Q(x) rows: (2), (3), (3), (NULL), (4).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM P\nWHERE NOT EXISTS (SELECT * FROM Q WHERE Q.x = P.x);\n```","options":["3","2","1","0"],"answer":1,"explanation":"NOT EXISTS is two-valued: P's 1 has no match and P's NULL matches nothing (NULL = anything is unknown), so both rows qualify: 2. Contrast with NOT IN, which returns 0 here.","difficulty":"hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-154","question":"R(A, B, C, D, E) has the set of functional dependencies Σ = {E → BD, AE → C, C → AD}. Which of the following FDs is NOT in Σ⁺ (not implied by Σ)?","options":["BC → D","DE → B","C → B","BE → D"],"answer":2,"explanation":"{C}⁺ = {ACD} does not contain B, so C → B is not implied; each of the other three follows by computing its LHS closure (augmentation and transitivity).","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-155","question":"In a B+ tree every internal node can have at most 50 children and every leaf can hold at most 40 keys. With exactly 3 levels (root at level 1, leaves at level 3), what is the maximum number of keys the tree can index?","options":["97,500","96,040","125,000","100,000"],"answer":3,"explanation":"Fully packed: 2 internal levels give 50^2 = 2,500 leaves, each with 40 keys, so 100,000 keys.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-156","question":"TS(T1) = 15, TS(T2) = 30, TS(T3) = 25; all read/write timestamps start at 0. Under basic timestamp ordering with Thomas's write rule, which operation of the schedule W2(B), W3(A), W1(B), W2(A), R3(A), R2(A), R1(A), W1(A) is the first to make its transaction roll back?","options":["R3(A) (operation 5)","No operation is rejected","W1(A) (operation 8)","R1(A) (operation 7)"],"answer":0,"explanation":"Track read-TS and write-TS of each item. R3(A) (operation 5) is the first operation that violates the protocol (a read of a value with a newer write-TS, or a write after a newer read or write). Earlier, W1(B) (operation 3) was an obsolete write and is simply ignored under Thomas's rule instead of causing a rollback.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-157","question":"R(A, B, C, D, E) with functional dependencies B → AD, AC → B, A → B is decomposed into R1(A, B), R2(B, D), R3(B, C, E). Which statement is correct?","options":["Dependency preserving but not lossless join","Lossless join and dependency preserving","Neither lossless join nor dependency preserving","Lossless join but not dependency preserving"],"answer":1,"explanation":"The chase (tableau) test produces an all-distinguished row, so the join is lossless. Every FD of F follows from the FDs projected onto the parts, so dependencies are preserved.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-158","question":"R(A, B, C, D, E, F) has functional dependencies A → CD, CF → A, E → B, D → A. Which of these attribute sets is NOT a superkey of R?","options":["DEF","BCEF","BCDF","ABEF"],"answer":2,"explanation":"{BCDF}⁺ = {ABCDF}, which misses E, so it is not a superkey. Each other option's closure is all of R (each contains one of the candidate keys AEF, CEF, DEF).","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-159","question":"Table Product(pid, cat, price) rows: (1, 'X', 10), (2, 'X', 20), (3, 'Y', 20), (4, NULL, 30), (5, 'Y', NULL), (6, 'Z', 5).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Product p\nWHERE NOT EXISTS (SELECT * FROM Product q\n                  WHERE q.cat = p.cat AND q.price > p.price);\n```","options":["3","6","4","5"],"answer":3,"explanation":"Only pid 1 is excluded (pid 2 is pricier in X). pid 2, 3 and 6 are the top of their categories; pid 5's NULL price makes q.price > NULL unknown, and pid 4's NULL category matches no row, so NOT EXISTS is TRUE for both: 5.","difficulty":"very-hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-160","question":"Consider the schedule R3(A), R2(A), R3(B), W3(B), R2(B), W1(B), W1(A), R1(A). Which statement is correct?","options":["Conflict serializable, equivalent only to T3 → T2 → T1","Conflict serializable, equivalent only to T3 → T1 → T2","Conflict serializable, equivalent only to T2 → T1 → T3","It is not conflict serializable"],"answer":0,"explanation":"Conflict edges: T2→T1, T3→T1, T3→T2. The graph is acyclic and its only topological order is T3 → T2 → T1.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-161","question":"T1: R1(A), R1(B) and T2: W2(A), W2(B). Of all 6 interleavings that keep each transaction's own order, how many are conflict serializable?","options":["2","4","6","3"],"answer":1,"explanation":"Enumerate the C(4, 2) = 6 interleavings and draw the precedence graph of each; exactly 4 have no cycle (all edges between T1 and T2 point the same way). The two serial schedules are always among them.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-162","question":"Σ = {CD → A, AC → B, B → E, D → B, C → D} on R(A, B, C, D, E). Exactly one FD in Σ is redundant (it can be derived from the others). Which one?","options":["C → D","D → B","AC → B","CD → A"],"answer":2,"explanation":"Remove AC → B and compute {AC}⁺ under the remaining FDs: it still contains B, so that FD is redundant. Removing any other FD loses information.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-163","question":"R(A, B) has 400 tuples and S(B, C) has 80 tuples, where B is the primary key of S, and R.B may contain values absent from S (no foreign key). What are the minimum and maximum possible numbers of tuples in R ⋈ S?","options":["min 400, max 400","min 0, max 80","min 0, max 32000","min 0, max 400"],"answer":3,"explanation":"Each R tuple matches at most one S tuple because B is S's key, but without a foreign key it may match none: 0 to 400.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-164","question":"Table Acct(no, branch, bal) rows: (101, 'Agra', 500), (102, 'Agra', 1500), (103, 'Bhopal', 700), (104, 'Bhopal', 700), (105, 'Cuttack', 2000), (106, 'Agra', NULL).\nWhat does this query return?\n```sql\nSELECT COUNT(DISTINCT bal), COUNT(bal), SUM(DISTINCT bal)\nFROM Acct;\n```","options":["4, 5, 4700","4, 5, 5400","4, 6, 4700","5, 5, 5400"],"answer":0,"explanation":"Non-NULL balances: 500, 1500, 700, 700, 2000. COUNT(bal) = 5; DISTINCT values are 500, 700, 1500, 2000 (4) summing to 4700; the plain sum would be 5400.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-165","question":"R(A, B) = {(2, 4), (3, 1), (4, 1), (4, 3), (4, 4)} and S(B, C) = {(1, 5), (2, 7), (4, 6), (4, 7)}. How many tuples are in R ⟕ S (left outer join) and in R ⟗ S (full outer join)?","options":["7 and 9","7 and 8","6 and 7","5 and 9"],"answer":1,"explanation":"R ⋈ S has 6 tuples; 1 R tuple(s) find no partner and are padded with NULL, giving 7. The full outer join also keeps 1 unmatched S tuple(s): 8.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-166","question":"R(A, B, C, D, E) has functional dependencies B → C, A → BE, C → ABE, E → C. Which of the following is the complete set of candidate keys of R?","options":["{AD, BD, BE, CD, DE}","{AD, BD, CD}","{AD, BD, CD, DE}","{AD, BD, CD, BDE}"],"answer":2,"explanation":"Attributes never on a right side (D) must be in every key; extending them and testing closures gives exactly the minimal superkeys {AD, BD, CD, DE}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-167","question":"T1: W1(A), R1(A), W1(B) and T2: W2(A), R2(B). Of all 10 interleavings that keep each transaction's own order, how many are conflict serializable?","options":["10","4","2","5"],"answer":3,"explanation":"Enumerate the C(5, 3) = 10 interleavings and draw the precedence graph of each; exactly 5 have no cycle (all edges between T1 and T2 point the same way). The two serial schedules are always among them.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-168","question":"Table Product(pid, cat, price) rows: (1, 'X', 10), (2, 'X', 20), (3, 'Y', 20), (4, NULL, 30), (5, 'Y', NULL), (6, 'Z', 5).\nWhat does this query return?\n```sql\nSELECT cat, MAX(price)\nFROM Product\nWHERE cat IS NOT NULL\nGROUP BY cat\nHAVING MIN(price) >= 10\nORDER BY cat;\n```","options":["(X, 20), (Y, 20)","(X, 20)","(Y, 20)","(X, 20), (Y, 20), (Z, 5)"],"answer":0,"explanation":"X: min 10 passes. Y: prices 20 and NULL, MIN ignores NULL so min = 20, passes. Z: min 5 fails.","difficulty":"moderate","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-169","question":"R(A, B) = {(1, 1), (1, 2), (1, 4), (2, 2), (4, 2), (4, 4)} and S(B, C) = {(1, 5), (3, 5), (3, 6), (4, 7)}. What is π_A(R) − π_A(R ⋈ S)?","options":["∅","{2}","{1, 4}","{1, 2, 4}"],"answer":1,"explanation":"This keeps A values ALL of whose tuples fail to join. An A value with at least one joining B is removed entirely, so the answer is {2}, not merely the A values of non-joining tuples.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-170","question":"R(A, B) = {(1, 4), (2, 1), (2, 4), (3, 2), (3, 3), (4, 4)} and S(B, C) = {(1, 6), (1, 7), (2, 5), (2, 6)}. What is π_A(R) − π_A(R ⋈ S)?","options":["∅","{1, 2, 3, 4}","{1, 4}","{2, 3}"],"answer":2,"explanation":"This keeps A values ALL of whose tuples fail to join. An A value with at least one joining B is removed entirely, so the answer is {1, 4}, not merely the A values of non-joining tuples.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-171","question":"Which view is generally updatable in standard SQL (an UPDATE through it maps to exactly one base row)?","options":["CREATE VIEW v AS SELECT dept, AVG(salary) FROM Emp GROUP BY dept","CREATE VIEW v AS SELECT e.id, d.city FROM Emp e, Dept d WHERE e.dept = d.name","CREATE VIEW v AS SELECT DISTINCT dept FROM Emp","CREATE VIEW v AS SELECT id, name FROM Emp WHERE dept = 'IT'"],"answer":3,"explanation":"A view over one table with no DISTINCT, aggregation or grouping lets each view row map to a unique base row. Aggregates and DISTINCT collapse rows, and join views are generally not updatable.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-172","question":"A B+ tree has at most 7 children per internal node and at most 6 keys per leaf. A non-root internal node must have at least ⌈7/2⌉ children, a leaf at least ⌈6/2⌉ keys, and the root (if internal) at least 2 children. What is the MINIMUM number of keys in such a tree with exactly 4 levels?","options":["96","384","95","192"],"answer":0,"explanation":"Minimum: root has 2 children, each lower internal level multiplies by 4, so there are 2·4^2 = 32 leaves, each with 3 keys: 96. Forgetting that the root needs only 2 children gives 192.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-173","question":"Consider the schedule W2(A), W2(B), R3(A), R3(B), W1(A), R1(B). Which statement is correct?","options":["Conflict serializable, equivalent only to T1 → T3 → T2","Conflict serializable, equivalent only to T2 → T3 → T1","Conflict serializable, equivalent only to T3 → T2 → T1","It is not conflict serializable"],"answer":1,"explanation":"Conflict edges: T2→T1, T2→T3, T3→T1. The graph is acyclic and its only topological order is T2 → T3 → T1.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-174","question":"R(A, B, C, D) has functional dependencies AC → D, A → D, CD → A, C → A, AB → CD. What is the highest normal form R satisfies?","options":["3NF but not BCNF","2NF but not 3NF","1NF but not 2NF","BCNF"],"answer":2,"explanation":"Candidate keys: {AB, BC}. A → D is a partial dependency: A is a proper subset of key AB and D is non-prime, so 2NF fails.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-175","question":"Extendible hashing uses the LOWEST-order bits of a key's binary value, bucket capacity 2, and starts with global depth 0 and one empty bucket. A full bucket splits on its next bit; the directory doubles only when the splitting bucket's local depth equals the global depth (repeat splits if needed). After inserting 48, 15, 43, 47, 26, 45, 13 in this order, what are the global depth and the number of distinct buckets?","options":["Global depth 3, 8 buckets","Global depth 2, 4 buckets","Global depth 4, 4 buckets","Global depth 3, 4 buckets"],"answer":3,"explanation":"Tracing the low-order bits: the directory grows to 2^3 = 8 entries, but buckets that never split stay shared by several entries, so only 4 distinct buckets exist.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-176","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT SUM(CASE WHEN pay >= 55 THEN 1 ELSE 0 END),\n       SUM(CASE WHEN pay < 55 THEN 1 ELSE 0 END)\nFROM Staff;\n```","options":["3, 2","3, 3","3, 2, 1","4, 2"],"answer":0,"explanation":"Bala, Chitra, Farid have pay ≥ 55; Anu and Esha are below. Dev's NULL makes both conditions UNKNOWN, so both CASEs fall to ELSE 0 — his row is counted in neither.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-177","question":"R(A, B, C, D, E) with functional dependencies AB → C, BD → CE, A → B is decomposed into R1(C, D), R2(A, B, E). Which statement is correct?","options":["Lossless join and dependency preserving","Neither lossless join nor dependency preserving","Lossless join but not dependency preserving","Dependency preserving but not lossless join"],"answer":1,"explanation":"The chase (tableau) test never produces an all-distinguished row, so the join is lossy. AB → C cannot be derived from the projected FDs, so a dependency is lost.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-178","question":"A fuzzy checkpoint differs from a simple (quiescent) checkpoint because it:","options":["Requires stopping all transactions until every dirty page is written","Writes no checkpoint record to the log","Lets transactions keep running while dirty pages are flushed in the background, so recovery must start from an earlier log point","Makes the redo pass unnecessary"],"answer":2,"explanation":"A simple checkpoint stops updates and flushes all dirty pages; a fuzzy one records the active transactions and dirty pages and continues work, so redo starts at the oldest recLSN among dirty pages.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-179","question":"Table Dept(did PRIMARY KEY) rows: (10), (20), (30).\nTable Emp(eid PRIMARY KEY, did REFERENCES Dept(did) ON DELETE CASCADE, mentor REFERENCES Emp(eid) ON DELETE SET NULL) rows: (1, 10, NULL), (2, 10, 1), (3, 20, 1), (4, 20, 3), (5, 30, 2), (6, 30, 4).\nWhat does this query return?\n```sql\nDELETE FROM Dept WHERE did = 10;\nSELECT COUNT(*), COUNT(mentor) FROM Emp;\n```","options":["6, 4","4, 3","4, 4","4, 2"],"answer":3,"explanation":"Deleting department 10 cascades to employees 1 and 2. Their deletion triggers ON DELETE SET NULL on mentor for employees 3 (mentor 1) and 5 (mentor 2). Remaining: 3, 4, 5, 6; only 4 and 6 still have mentors.","difficulty":"very-hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-180","question":"Classify the schedule W3(A), R1(A), R2(B), R2(A), R3(B), C2, W1(B), R1(B), C1, C3 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Not recoverable","Recoverable but not cascadeless","Cascadeless but not strict","Strict"],"answer":0,"explanation":"A transaction reads a value written by another transaction and commits before that writer commits; if the writer then aborted, the committed reader could not be undone.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-181","question":"R(A, B) has 120 tuples and S(B, C) has 40 tuples, where B is a key of neither relation. What are the minimum and maximum possible numbers of tuples in R ⋈ S?","options":["min 40, max 120","min 0, max 4800","min 0, max 40","min 120, max 120"],"answer":1,"explanation":"With no keys, all tuples might share one B value, giving 120 × 40 = 4800; or no values match, giving 0.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-182","question":"R(A, B, C, D, E) has functional dependencies D → A, AB → CD, BE → C, BC → E. What is the closure {BC}⁺?","options":["{BC}","{ABCE}","{BCE}","{ABCDE}"],"answer":2,"explanation":"Keep applying any FD whose left side is already inside the set until nothing changes; one pass in listed order is not enough. The result is {BCE}.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-183","question":"A file of 5000 blocks is sorted by external merge sort with M = 21 buffer blocks (sorted runs of M blocks are created in pass 0, then (M − 1)-way merges). How many passes in total are needed, and how many block transfers if each pass reads and writes every block once?","options":["3 passes, 15,000 transfers","4 passes, 40,000 transfers","2 passes, 20,000 transfers","3 passes, 30,000 transfers"],"answer":3,"explanation":"Pass 0 makes ⌈5000/21⌉ = 239 runs; each merge pass divides the run count by 20, needing 2 merge pass(es). Total 3 passes × 2 × 5000 = 30,000 transfers.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-184","question":"Table Route(src, dst, cost) rows: ('A', 'B', 5), ('B', 'C', 4), ('A', 'C', 12), ('C', 'D', 3), ('B', 'D', 9), ('D', 'A', 2).\nWhat does this query return?\n```sql\nWITH RECURSIVE reach(node, hops) AS (\n  SELECT 'A', 0\n  UNION\n  SELECT r.dst, hops + 1 FROM reach JOIN Route r ON r.src = reach.node\n  WHERE hops < 2)\nSELECT COUNT(*) FROM reach;\n```","options":["5","4","3","6"],"answer":0,"explanation":"Rows: (A,0); hop 1: (B,1), (C,1); hop 2: from B → (C,2), (D,2) and from C → (D,2) again. UNION drops the duplicate (D,2) but keeps (C,1) and (C,2) as different rows, so 5 (UNION ALL would give 6, distinct nodes only 4).","difficulty":"very-hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-185","question":"Table Acct(no, branch, bal) rows: (101, 'Agra', 500), (102, 'Agra', 1500), (103, 'Bhopal', 700), (104, 'Bhopal', 700), (105, 'Cuttack', 2000), (106, 'Agra', NULL).\nWhat does this query return?\n```sql\nUPDATE Acct\nSET bal = CASE WHEN bal < 1000 THEN bal * 2 ELSE bal - 500 END;\nSELECT SUM(bal) FROM Acct;\n```","options":["6800","6300","5900","NULL"],"answer":1,"explanation":"500 → 1000, 1500 → 1000, 700 → 1400 twice, 2000 → 1500; the NULL balance fails the WHEN test, goes to ELSE and NULL − 500 stays NULL, which SUM ignores: 6300.","difficulty":"hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-186","question":"Which statement about snapshot isolation (SI) is correct?","options":["It allows dirty reads but prevents non-repeatable reads","It is equivalent to serializable isolation","It prevents lost updates through first-committer-wins but can still allow write skew","It prevents write skew but allows lost updates"],"answer":2,"explanation":"Each transaction reads a consistent snapshot, and concurrent writes to the same item abort one writer (no lost update). Two transactions that read overlapping data but write different items (write skew) can both commit, so SI is not serializable.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-187","question":"R(A, B) has 300 tuples and S(B, C) has 50 tuples, where S.B is the primary key of S and R.B is a foreign key referencing it (NOT NULL). What are the minimum and maximum possible numbers of tuples in R ⋈ S?","options":["min 50, max 300","min 0, max 50","min 0, max 15000","min 300, max 300"],"answer":3,"explanation":"Every R tuple must match exactly one S tuple (the FK guarantees existence, the key uniqueness), so the join has exactly 300 tuples.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-188","question":"Table P(x) rows: (1), (2), (2), (3), (NULL).\nTable Q(x) rows: (2), (3), (3), (NULL), (4).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM P JOIN Q ON P.x = Q.x;\n```","options":["4","5","3","2"],"answer":0,"explanation":"Join pairs: P's two 2s each match Q's single 2 (2 pairs); P's 3 matches Q's two 3s (2 pairs). NULLs never satisfy '=', so 4.","difficulty":"moderate","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-189","question":"R has 500 tuples in 50 blocks and S has 4000 tuples in 200 blocks. With only enough memory for one block of each relation, how many block transfers does the TUPLE-at-a-time nested-loop join with R as outer need, and how many does the block nested-loop join with R as outer need?","options":["200,200 and 10,200","100,050 and 10,050","2,000,050 and 10,050","100,050 and 100,000"],"answer":1,"explanation":"Tuple NL reads S once per R tuple: 500·200 + 50. Block NL reads S once per R block: 50·200 + 50.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-190","question":"Under BOTH wait-die and wound-wait deadlock prevention, which transaction can be rolled back when a lock conflict occurs?","options":["Always the requesting transaction","Always the transaction holding the lock","Only the younger transaction (larger timestamp)","Only the older transaction"],"answer":2,"explanation":"Wait-die: a younger requester dies. Wound-wait: an older requester wounds (aborts) the younger holder. Either way the victim is the younger one, and restarting with the original timestamp prevents starvation.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-191","question":"Table Acct(no, branch, bal) rows: (101, 'Agra', 500), (102, 'Agra', 1500), (103, 'Bhopal', 700), (104, 'Bhopal', 700), (105, 'Cuttack', 2000), (106, 'Agra', NULL).\nWhat does this query return?\n```sql\nSELECT branch FROM Acct\nGROUP BY branch\nHAVING COUNT(DISTINCT bal) = COUNT(bal)\nORDER BY branch;\n```","options":["Bhopal","Cuttack","Agra, Bhopal, Cuttack","Agra, Cuttack"],"answer":3,"explanation":"Bhopal has two equal balances (700, 700), so its distinct count 1 ≠ 2. Agra's non-NULL balances 500 and 1500 are distinct (the NULL is ignored by both counts), and Cuttack has one.","difficulty":"hard","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-192","question":"R(A, B, C, D, E, F) with functional dependencies E → B, F → A, B → A, C → E is decomposed into R1(A, B, F), R2(B, D, E), R3(C, E). Which statement is correct?","options":["Dependency preserving but not lossless join","Lossless join and dependency preserving","Lossless join but not dependency preserving","Neither lossless join nor dependency preserving"],"answer":0,"explanation":"The chase (tableau) test never produces an all-distinguished row, so the join is lossy. Every FD of F follows from the FDs projected onto the parts, so dependencies are preserved.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-193","question":"On R(A, B, C, D, E), F = {AB → C, DE → C, B → C} and G = {B → DE, E → AC, D → A}. Which statement is correct? (\"F covers G\" means every FD of G is in F⁺.)","options":["F covers G, but G does not cover F","G covers F, but F does not cover G","Neither covers the other","F and G are equivalent"],"answer":1,"explanation":"Check each FD of one set by its LHS closure under the other set. F covers G: no; G covers F: yes.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-194","question":"R(A, B, C, D, E, F) has FDs E → AB, C → A, DE → AB, B → EF. Each option is a relation schema obtained by projecting R, with the dependencies implied on its attributes. Which one is NOT in BCNF?","options":["(A, B, E)","(A, E, F)","(A, C, E)","(C, D, F)"],"answer":2,"explanation":"Project the closure of the given FDs onto each schema. On (A, C, E), C → A holds but C is not a key of the projection, so BCNF fails; on the other three every projected FD has a key on the left (or none is non-trivial).","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-195","question":"Classify the schedule W3(B), R1(A), W1(B), C1, W2(A), W3(A), R2(A), W2(B), C3, C2 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Cascadeless but not strict","Not recoverable","Strict","Recoverable but not cascadeless"],"answer":3,"explanation":"Some transaction reads a value written by an uncommitted transaction (not cascadeless), but each such reader commits after the writer, so the schedule is recoverable.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-196","question":"A B+ tree has at most 10 children per internal node and at most 8 keys per leaf. A non-root internal node must have at least ⌈10/2⌉ children, a leaf at least ⌈8/2⌉ keys, and the root (if internal) at least 2 children. What is the MINIMUM number of keys in such a tree with exactly 3 levels?","options":["40","100","200","80"],"answer":0,"explanation":"Minimum: root has 2 children, each lower internal level multiplies by 5, so there are 2·5^1 = 10 leaves, each with 4 keys: 40. Forgetting that the root needs only 2 children gives 100.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-197","question":"Which tuple relational calculus expression is UNSAFE (may produce an infinite result)?","options":["{ t | Emp(t) ∧ ¬ ∃ m (Emp(m) ∧ m.boss = t.id) }","{ t | ¬ Emp(t) }","{ t | Emp(t) ∧ t.salary > 50000 }","{ t.name | Emp(t) ∧ ∃ d (Dept(d) ∧ d.id = t.dept) }"],"answer":1,"explanation":"{ t | ¬ Emp(t) } asks for every possible tuple not in Emp, which is infinite. The others draw t from Emp, so their results are finite.","difficulty":"moderate","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-198","question":"On R(A, B, C, D, E), F = {BE → CD, D → B, AC → D} and G = {B → C, AC → B, E → A}. Which statement is correct? (\"F covers G\" means every FD of G is in F⁺.)","options":["G covers F, but F does not cover G","F and G are equivalent","Neither covers the other","F covers G, but G does not cover F"],"answer":2,"explanation":"Check each FD of one set by its LHS closure under the other set. F covers G: no; G covers F: no.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-199","question":"R(A, B, C, D) has FDs A → B, B → C, C → D and D → A. Every attribute is a candidate key. A designer still decomposes R into R1(A, B) and R2(B, C, D). Which statement is correct?","options":["Dependency preserving but lossy","Lossless but not dependency preserving, because D → A crosses the parts","Lossy, because A → B is lost","Lossless and dependency preserving, and both parts are in BCNF"],"answer":3,"explanation":"R1 ∩ R2 = B is a key, so the join is lossless. A → B lies in R1 and B → C, C → D in R2; D → A follows from D → B (projected on R2) and B → A (projected on R1), so nothing is lost. Every attribute is a key of each part, so both are in BCNF.","difficulty":"very-hard","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-200","question":"Optimistic (validation-based) concurrency control runs each transaction in three phases. In which order, and when are its writes applied to the database?","options":["Read, validation, write — writes go to the database only after validation succeeds","Validation, read, write — writes are applied during the read phase","Read, write, validation — writes are undone if validation fails","Write, read, validation — validation checks the log"],"answer":0,"explanation":"A transaction works on private copies in the read phase, is checked against overlapping transactions at validation, and installs its updates only in the write phase, so a failed validation needs no undo.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-201","question":"R(A, B, C, D, E) has functional dependencies DE → B, AC → E, AD → E, BD → CE, C → A. How many prime attributes does R have?","options":["4","5","2","1"],"answer":1,"explanation":"The candidate keys are {AD, BD, CD, DE}, so the prime attributes (those in at least one candidate key) are ABCDE, giving 5. Counting only one key's attributes undercounts.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-202","question":"A file has 50,000 records of 200 bytes stored unspanned in 2048-byte blocks, NOT ordered on attribute X. A dense secondary index on X (a candidate key) has one entry per record: a 12-byte key and a 8-byte record pointer. Searching by binary search on the index plus one data-block read needs how many block accesses in the worst case?","options":["9","7","10","2500"],"answer":2,"explanation":"Dense index: 50,000 entries, ⌊2048/20⌋ = 102 per block, so 491 index blocks; ⌈log₂ 491⌉ = 9, +1 data block = 10. (A linear scan of the file would average about 2,500 blocks.)","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-203","question":"A table Teach(course, teacher, book) records that each course is taught by several teachers and uses several books, independently of each other, so every teacher–book combination is stored for a course. No FDs hold except trivial ones. What is the highest normal form of Teach?","options":["1NF only, because of the redundancy","3NF but not BCNF","4NF","BCNF but not 4NF"],"answer":3,"explanation":"With no non-trivial FDs the only key is all three attributes, so it is in BCNF. But course ↠ teacher is a non-trivial MVD whose left side is not a superkey, so 4NF fails; split into (course, teacher) and (course, book).","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-204","question":"How many of these statements are correct?\n1. A BCNF decomposition obtained by the standard algorithm is always lossless.\n2. A BCNF decomposition that preserves all dependencies always exists.\n3. The 3NF synthesis algorithm always gives a lossless, dependency-preserving decomposition.\n4. Every relation in 3NF is also in 2NF.","options":["3","1","4","2"],"answer":0,"explanation":"1, 3 and 4 are true. Statement 2 fails: for R(A, B, C) with AB → C and C → B, every BCNF decomposition loses AB → C.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-205","question":"R(A, B, C, D, E, F) has functional dependencies AD → BF, BD → F, F → A. How many superkeys does R have?","options":["4","7","12","6"],"answer":1,"explanation":"Candidate keys are {ACDE, BCDE, CDEF}. Count supersets of each key and apply inclusion–exclusion (a set may contain two keys): the total is 7, not the naive sum 12.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-206","question":"R(A, B, C, D, E) with functional dependencies A → E, D → C, C → DE is decomposed into R1(C, D, E), R2(A, B, C). Which statement is correct?","options":["Neither lossless join nor dependency preserving","Dependency preserving but not lossless join","Lossless join but not dependency preserving","Lossless join and dependency preserving"],"answer":2,"explanation":"The chase (tableau) test produces an all-distinguished row, so the join is lossless. A → E cannot be derived from the projected FDs, so a dependency is lost.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-207","question":"Which statement about linear hashing is correct?","options":["It never uses overflow pages","It uses a directory that doubles like extendible hashing","It splits exactly the bucket that overflows, immediately","Buckets are split in a fixed round-robin order, so the bucket that is split is not necessarily the one that overflowed"],"answer":3,"explanation":"Linear hashing has no directory; a split pointer moves through the buckets in order, so an overflowing bucket may keep an overflow chain until its turn comes.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-208","question":"R(A, B, C, D, E, F) has functional dependencies AC → BE, D → E, C → A, AB → F. What is the closure {BC}⁺?","options":["{ABCEF}","{ABCE}","{ABCF}","{ABCDEF}"],"answer":0,"explanation":"Keep applying any FD whose left side is already inside the set until nothing changes; one pass in listed order is not enough. The result is {ABCEF}.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-209","question":"Σ = {B → A, D → B, AD → C, A → D}. Consider the FD AD → C while computing a canonical cover. Which statement about extraneous attributes on its left side is correct?","options":["Neither A nor D is extraneous","Either A or D (but not both) can be dropped","Only A is extraneous","Only D is extraneous"],"answer":1,"explanation":"Test each attribute: A is extraneous iff {D}⁺ (under Σ) contains C; {D}⁺ = {ABCD} and {A}⁺ = {ABCD}.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-210","question":"Table Acct(no, branch, bal) rows: (101, 'Agra', 500), (102, 'Agra', 1500), (103, 'Bhopal', 700), (104, 'Bhopal', 700), (105, 'Cuttack', 2000), (106, 'Agra', NULL).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Acct a\nWHERE 1 >= (SELECT COUNT(*) FROM Acct b WHERE b.bal > a.bal);\n```","options":["4","1","3","2"],"answer":2,"explanation":"2000 has no larger balance and 1500 has one, so both qualify; each 700 has two larger. The trap is account 106: b.bal > NULL is never TRUE, so its inner COUNT is 0 and it qualifies too, giving 3, not 2.","difficulty":"very-hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-211","question":"R(A, B, C, D, E, F) has FDs BF → A, BD → EF, E → CD, CF → B. Each option is a relation schema obtained by projecting R, with the dependencies implied on its attributes. Which one is NOT in BCNF?","options":["(B, D, F)","(C, D, E)","(A, C, F)","(A, D, E)"],"answer":3,"explanation":"Project the closure of the given FDs onto each schema. On (A, D, E), E → D holds but E is not a key of the projection, so BCNF fails; on the other three every projected FD has a key on the left (or none is non-trivial).","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-212","question":"R(A, B, C, D, E, F) has functional dependencies BF → DE, C → E, F → E, DF → B. Which of the following is the complete set of candidate keys of R?","options":["{ABCF, ACDF}","{ABCF, ACDF, BCDE}","{ABCF, ACDEF}","{ABCF}"],"answer":0,"explanation":"Attributes never on a right side (ACF) must be in every key; extending them and testing closures gives exactly the minimal superkeys {ABCF, ACDF}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-213","question":"R(A, B, C, D, E) has functional dependencies E → CD, C → A, D → AC. Which decomposition of R is lossless-join?","options":["(A, D, E), (B, C)","(A, C), (A, D, E), (B, C, E)","(A, B), (A, C), (D, E)","(A, B, E), (B, C, D)"],"answer":1,"explanation":"Run the chase (or, for two parts, check whether the common attributes determine one whole part). Only (A, C), (A, D, E), (B, C, E) produces an all-distinguished row; in each other option some join step has common attributes that are not a key of either side.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-214","question":"Classify the schedule R2(B), W2(B), W1(A), R1(A), W1(B), C1, C2 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Not recoverable","Strict","Cascadeless but not strict","Recoverable but not cascadeless"],"answer":2,"explanation":"Every read is of committed data (cascadeless), but some transaction overwrites an item whose earlier writer has not committed yet, which strictness forbids.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-215","question":"Which statement about the basic timestamp-ordering protocol is correct?","options":["It allows non-conflict-serializable schedules","It can deadlock because transactions wait for locks","It guarantees recoverable schedules without any extra rule","It is deadlock-free but may produce cascading rollbacks unless reads of uncommitted data are delayed"],"answer":3,"explanation":"No transaction ever waits, so deadlock is impossible; conflicting operations are ordered by timestamps, so schedules are conflict serializable. But a transaction may read uncommitted data and then cascade if the writer aborts.","difficulty":"hard","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-216","question":"A file has 20,000 records of 80 bytes stored unspanned in 512-byte blocks, NOT ordered on attribute X. A dense secondary index on X (a candidate key) has one entry per record: a 10-byte key and a 6-byte record pointer. Searching by binary search on the index plus one data-block read needs how many block accesses in the worst case?","options":["11","8","1667","10"],"answer":0,"explanation":"Dense index: 20,000 entries, ⌊512/16⌋ = 32 per block, so 625 index blocks; ⌈log₂ 625⌉ = 10, +1 data block = 11. (A linear scan of the file would average about 1,667 blocks.)","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-217","question":"R(A, B) has 250 tuples and S(B, C) has 60 tuples, where B is the primary key of R and also the primary key of S. What are the minimum and maximum possible numbers of tuples in R ⋈ S?","options":["min 60, max 250","min 0, max 60","min 0, max 15000","min 250, max 250"],"answer":1,"explanation":"B is unique on both sides, so each tuple matches at most one partner; the join is at most min(250, 60) = 60 and can be 0.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-218","question":"R(A, B, C, D, E, F) has functional dependencies C → F, D → AC, A → B, F → D. Which of these attribute sets is NOT a superkey of R?","options":["DE","BCE","CD","ABCE"],"answer":2,"explanation":"{CD}⁺ = {ABCDF}, which misses E, so it is not a superkey. Each other option's closure is all of R (each contains one of the candidate keys CE, DE, EF).","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-219","question":"Table Score(name, pts) rows: ('a', 90), ('b', 85), ('c', 90), ('d', 70), ('e', 85), ('f', 60).\nIn this query's output, what are (r, dr) for d and for f?\n```sql\nSELECT name, RANK() OVER (ORDER BY pts DESC) AS r,\n       DENSE_RANK() OVER (ORDER BY pts DESC) AS dr\nFROM Score\nORDER BY pts DESC, name;\n```","options":["d: (5, 5), f: (6, 6)","d: (4, 3), f: (5, 4)","d: (3, 3), f: (4, 4)","d: (5, 3), f: (6, 4)"],"answer":3,"explanation":"Scores in order: 90, 90, 85, 85, 70, 60. RANK leaves gaps after ties (1, 1, 3, 3, 5, 6); DENSE_RANK does not (1, 1, 2, 2, 3, 4). So d = (5, 3) and f = (6, 4).","difficulty":"hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-220","question":"R(A, B, C, D, E, F) has the set of functional dependencies Σ = {A → D, E → C, AE → CD, F → B, B → F}. Which of the following FDs is NOT in Σ⁺ (not implied by Σ)?","options":["AE → B","AB → F","BE → F","BD → F"],"answer":0,"explanation":"{AE}⁺ = {ACDE} does not contain B, so AE → B is not implied; each of the other three follows by computing its LHS closure (augmentation and transitivity).","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-221","question":"R(A, B, C, D) has functional dependencies D → AB, A → BC. What is the highest normal form R satisfies?","options":["3NF but not BCNF","2NF but not 3NF","BCNF","1NF but not 2NF"],"answer":1,"explanation":"Candidate keys: {D}. No partial dependency exists, but A → B has a non-superkey left side and a non-prime right side (prime attributes: D), so 3NF fails.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-222","question":"A B+ tree index uses 512-byte blocks, 8-byte search keys, 4-byte block pointers and 6-byte record (data) pointers. Each leaf also keeps one block pointer to the next leaf. What is the maximum number of keys a LEAF node can hold?","options":["42","43","36","35"],"answer":2,"explanation":"A leaf holds q (key, record-pointer) pairs plus one next-leaf pointer: 14·q + 4 ≤ 512 gives q = ⌊(512 − 4)/14⌋ = 36. Using the block-pointer size or forgetting the sibling pointer gives the traps.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-223","question":"R(A, B) = {(1, 3), (3, 2), (3, 4), (4, 2)} and S(B, C) = {(2, 5), (2, 7), (3, 6), (3, 7), (4, 5)}. How many tuples does σ_{R.B ≠ S.B}(R × S) have?","options":["20","7","14","13"],"answer":3,"explanation":"R × S has 4 × 5 = 20 tuples; 7 of them have R.B = S.B (exactly the natural-join pairs), so 13 remain.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-224","question":"A query optimizer rewrites σ_{city='Pune'}(Customer ⋈ Orders) as σ_{city='Pune'}(Customer) ⋈ Orders, where city is an attribute of Customer only. Why is this rewrite valid and usually beneficial?","options":["Selection commutes with join when it uses only one input's attributes, and filtering early shrinks the join input","It is valid only for outer joins","It changes the result but is faster","It is valid only if city is a key"],"answer":0,"explanation":"Pushing a selection below a join is an equivalence whenever the predicate mentions attributes of one operand only; it reduces the number of tuples the join must process.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-225","question":"Which change is an example of PHYSICAL data independence in the three-schema architecture?","options":["Changing an application's external view","Adding a B+ tree index on a column without changing any table definition or query","Adding a new column to a table without changing existing views","Splitting a table into two and defining a view to rebuild the original"],"answer":1,"explanation":"Physical independence means the conceptual schema is unaffected by storage changes such as indexes or file organisation. Changes to tables (conceptual schema) that leave views intact are logical independence.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-226","question":"Teach(course, teacher, book) satisfies course ↠ teacher | book, and the course DBMS has 3 teachers and 4 books. How many tuples must Teach store for DBMS, and how many tuples do the 4NF tables (course, teacher) and (course, book) store for it in total?","options":["12 and 12","7 and 7","12 and 7","7 and 12"],"answer":2,"explanation":"The MVD forces every teacher–book pair: 3 × 4 = 12 tuples. After decomposition: 3 + 4 = 7 tuples, which is the redundancy 4NF removes.","difficulty":"hard","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-227","question":"For the schedule R1(B), R1(C), W3(A), W1(C), R2(A), W2(C), R3(B), how many distinct serial schedules are conflict-equivalent to it?","options":["6","3","1","2"],"answer":3,"explanation":"Conflict edges: T1→T2, T3→T2. The equivalent serial schedules are the topological orders of this graph: T1 → T3 → T2; T3 → T1 → T2.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-228","question":"For the schedule R1(B), W3(A), W1(B), W2(B), R2(A), W3(C), R3(C), R2(C), how many distinct serial schedules are conflict-equivalent to it?","options":["2","6","3","1"],"answer":0,"explanation":"Conflict edges: T1→T2, T3→T2. The equivalent serial schedules are the topological orders of this graph: T1 → T3 → T2; T3 → T1 → T2.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-229","question":"R(A, B, C, D, E, F) has functional dependencies F → E, E → BC, CE → F, C → F. Which of the following is the complete set of candidate keys of R?","options":["{ACD, ADE}","{ACD, ADE, ADF}","{ACD, ADE, ABCD}","{ACD, ADE, ADF, CEF}"],"answer":1,"explanation":"Attributes never on a right side (AD) must be in every key; extending them and testing closures gives exactly the minimal superkeys {ACD, ADE, ADF}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-230","question":"R(A, B) = {(2, 1), (2, 2), (3, 3), (3, 4)} and S(B, C) = {(1, 5), (2, 5), (3, 5), (3, 6), (3, 7)}. How many tuples does σ_{R.B ≠ S.B}(R × S) have?","options":["20","16","15","5"],"answer":2,"explanation":"R × S has 4 × 5 = 20 tuples; 5 of them have R.B = S.B (exactly the natural-join pairs), so 15 remain.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-231","question":"Table Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Takes a JOIN Takes b\n  ON a.cid = b.cid AND a.sid < b.sid;\n```","options":["5","8","3","4"],"answer":3,"explanation":"C1 is taken by sids 1, 2, 5 → 3 pairs; C2 by 1 and 3 → 1 pair; C3 by one student. a.sid < b.sid counts each unordered pair once: 4.","difficulty":"moderate","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-232","question":"Table Stu(sid, sname) rows: (1, 'Om'), (2, 'Pia'), (3, 'Raj'), (4, 'Sia').\nTable Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat does this query return?\n```sql\nSELECT s.sname, COUNT(*), COUNT(t.cid)\nFROM Stu s LEFT JOIN Takes t ON s.sid = t.sid\nWHERE s.sname = 'Sia'\nGROUP BY s.sname;\n```","options":["Sia, 1, 0","No rows (empty result)","Sia, 1, 1","Sia, 0, 0"],"answer":0,"explanation":"Sia has no Takes rows, so the LEFT JOIN keeps one row padded with NULLs. COUNT(*) counts that row (1); COUNT(t.cid) skips the NULL (0).","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-233","question":"Which set of relational algebra operators is a complete (minimal) basis from which the others can be expressed?","options":["Projection, natural join, set difference and division","Selection, projection, union, set difference, Cartesian product and rename","Selection, projection, union, intersection and Cartesian product","Selection, projection, natural join, intersection and division"],"answer":1,"explanation":"Selection, projection, union, set difference, Cartesian product and rename are fundamental; ∩ = R − (R − S), ⋈ is σ over ×, and ÷ is built from π, × and −.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-234","question":"A B-tree (not B+ tree) stores a record pointer with every key in every node. With 1024-byte blocks, 9-byte keys, 6-byte tree pointers and 7-byte record pointers, what is the maximum number of child pointers (the order p) of a node?","options":["48","68","47","46"],"answer":2,"explanation":"A B-tree node with p children has p tree pointers and p − 1 (key, record-pointer) pairs: 6·p + 16·(p − 1) ≤ 1024, so p = ⌊1040/22⌋ = 47. Ignoring the record pointers gives the B+ internal order instead.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-235","question":"Two transactions each read X = 100. T1 sets X = X − 30 and commits; then T2 sets X = X + 50 and commits. The final value is 150. Which anomaly occurred and which isolation property was violated?","options":["Unrepeatable read; durability","Dirty read; atomicity","Phantom read; consistency","Lost update; isolation"],"answer":3,"explanation":"T2 overwrote T1's committed change using a stale read, so T1's update is lost (the serial result would be 120). This is an isolation failure — the interleaving is not serializable.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-236","question":"Classify the schedule R2(B), W1(A), W2(A), W3(A), R1(B), W1(B), R3(A), R3(B).","options":["View serializable but not conflict serializable","Conflict serializable (hence also view serializable)","Conflict serializable but not view serializable","Neither conflict nor view serializable"],"answer":0,"explanation":"The precedence graph has a cycle, but blind writes let the serial order T2 → T1 → T3 match every reads-from relation and every final write, so it is view serializable only.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-237","question":"Under basic two-phase locking, a conflict-serializable schedule is equivalent to the serial schedule that orders transactions by their:","options":["Timestamps assigned at start","Lock points (the moment each acquires its last lock)","Start times","Commit times, always"],"answer":1,"explanation":"Under 2PL, if Ti → Tj in the precedence graph, Ti's lock point precedes Tj's, so ordering by lock points gives an equivalent serial order. Commit order works only for strict/rigorous variants.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-238","question":"A weak entity set Dependent (partial key dname) is owned by Employee (key eid) through the identifying relationship HasDep. Which table design is correct?","options":["Dependent(dname, …) with key dname and a separate HasDep(eid, dname) table","Dependent(eid, dname, …) with key dname","Dependent(eid, dname, …) with key (eid, dname) and eid referencing Employee ON DELETE CASCADE","Employee stores a multivalued attribute dname and no Dependent table"],"answer":2,"explanation":"A weak entity's key is its partial key plus the owner's key, and it cannot exist without its owner, so the FK is part of the key and usually cascades on delete. The identifying relationship needs no separate table.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-239","question":"R(A, B, C, D, E, F) has functional dependencies B → C, AF → E, AC → E, CE → A. How many prime attributes does R have?","options":["4","3","6","5"],"answer":3,"explanation":"The candidate keys are {ABDF, BDEF}, so the prime attributes (those in at least one candidate key) are ABDEF, giving 5. Counting only one key's attributes undercounts.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-240","question":"R(A, B, C, D, E) has functional dependencies E → AB, A → D, D → BE. Which decomposition of R is lossless-join?","options":["(A, B, E), (C, D, E)","(A, C, D), (B, C, E)","(A, B, C), (B, D, E)","(A, B), (C, D, E)"],"answer":0,"explanation":"Run the chase (or, for two parts, check whether the common attributes determine one whole part). Only (A, B, E), (C, D, E) produces an all-distinguished row; in each other option some join step has common attributes that are not a key of either side.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-241","question":"TS(T1) = 30, TS(T2) = 20, TS(T3) = 10; all read/write timestamps start at 0. Under basic timestamp ordering (no Thomas write rule), which operation of the schedule W1(A), R1(B), R2(B), R3(A), W3(B), R2(A), W2(B) is the first to make its transaction roll back?","options":["No operation is rejected","R3(A) (operation 4)","R2(A) (operation 6)","W1(A) (operation 1)"],"answer":1,"explanation":"Track read-TS and write-TS of each item. R3(A) (operation 4) is the first operation that violates the protocol (a read of a value with a newer write-TS, or a write after a newer read or write).","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-242","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT rep FROM Sale s\nWHERE region IS NOT NULL\nGROUP BY rep\nHAVING COUNT(DISTINCT region) =\n       (SELECT COUNT(DISTINCT region) FROM Sale)\nORDER BY rep;\n```","options":["Jai","Ira, Jai, Kim","Ira, Jai","No rows (empty result)"],"answer":2,"explanation":"COUNT(DISTINCT region) over the table ignores NULL, so it is 2 (N and S). Ira and Jai have sold in both regions; Kim only in N. This is division with GROUP BY/HAVING.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-243","question":"R(A, B) = {(a1, b2), (a1, b3), (a2, b2), (a2, b3), (a3, b1), (a3, b3), (a4, b1), (a4, b2), (a4, b3)} and S(B) = {b1, b2}. What is R ÷ S?","options":["{a1, a2, a3, a4}","∅","{a1, a2, a3}","{a4}"],"answer":3,"explanation":"R ÷ S returns the A values paired with EVERY B in S (b1, b2). The answer is {a4}; values paired with just some of them belong to the 'any' (semi-join) answer.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-244","question":"Classify the schedule R3(A), R3(B), W1(A), R1(A), C3, R2(A), C1, W2(B), W2(A), C2 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Recoverable but not cascadeless","Strict","Not recoverable","Cascadeless but not strict"],"answer":0,"explanation":"Some transaction reads a value written by an uncommitted transaction (not cascadeless), but each such reader commits after the writer, so the schedule is recoverable.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-245","question":"Consider the schedule W1(A), R1(B), W2(A), R1(A), R3(B), W3(A), R2(A). Which statement is correct?","options":["Conflict serializable, equivalent to T1 → T3 → T2","It is not conflict serializable","Conflict serializable, equivalent to T3 → T2 → T1","Conflict serializable, equivalent to T2 → T1 → T3"],"answer":1,"explanation":"The precedence graph has both T1 → T2 and T2 → T1 (a cycle), so no serial order exists.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-246","question":"In multiple-granularity locking, transaction T1 holds an SIX lock on a table. Which lock request by another transaction on the same table can be granted?","options":["IX","SIX","IS","S"],"answer":2,"explanation":"SIX = S + IX. It is compatible only with IS: IX conflicts with its S part, S conflicts with its IX part, and SIX conflicts with SIX.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-247","question":"On R(A, B, C, D, E), F = {D → C, C → AB, E → BC} and G = {BE → AC, CD → B, BD → C}. Which statement is correct? (\"F covers G\" means every FD of G is in F⁺.)","options":["G covers F, but F does not cover G","F and G are equivalent","Neither covers the other","F covers G, but G does not cover F"],"answer":3,"explanation":"Check each FD of one set by its LHS closure under the other set. F covers G: yes; G covers F: no.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-248","question":"Keys 7, 31, 43, 34, 16, 26, 39, 38, 29, 44 are inserted in this order into an empty B+ tree where a node holds at most 3 keys; an overflowing leaf with 4 keys keeps the first 2 and moves the rest to a new right leaf, copying the new leaf's first key up; an overflowing internal node with 4 keys keeps the first 2, moves the next key up and puts the rest in a new right node. After all insertions, how many leaf nodes are there and what is the height (number of levels)?","options":["4 leaves, height 2","4 leaves, height 3","3 leaves, height 2","5 leaves, height 2"],"answer":0,"explanation":"Simulating the splits gives leaves 7,16 | 26,29,31 | 34,38 | 39,43,44 and root keys [26, 34, 39], so 4 leaves at height 2.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-249","question":"Table Acct(no, branch, bal) rows: (101, 'Agra', 500), (102, 'Agra', 1500), (103, 'Bhopal', 700), (104, 'Bhopal', 700), (105, 'Cuttack', 2000), (106, 'Agra', NULL).\nWhat does this query return?\n```sql\nDELETE FROM Acct\nWHERE bal < (SELECT AVG(bal) FROM Acct a2 WHERE a2.branch = Acct.branch);\nSELECT COUNT(*) FROM Acct;\n```","options":["6","5","3","4"],"answer":1,"explanation":"Branch averages (NULL ignored): Agra 1000, Bhopal 700, Cuttack 2000. Only account 101 (500 < 1000) is deleted. The NULL-balance account is not deleted because NULL < 1000 is unknown. 5 rows remain.","difficulty":"hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-250","question":"Which ACID property is primarily the responsibility of the application programmer (together with declared integrity constraints), rather than the recovery or concurrency-control subsystem?","options":["Isolation","Atomicity","Consistency","Durability"],"answer":2,"explanation":"The DBMS guarantees atomicity and durability (recovery) and isolation (concurrency control); whether a transaction preserves the business rules depends on how it is written.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-251","question":"R(A, B, C, D, E) has functional dependencies DE → B, CE → A, AC → BE. How many superkeys does R have?","options":["2","8","3","6"],"answer":3,"explanation":"C and D never appear on a right side, so every key contains CD; the candidate keys are ACD and CDE. Supersets: 4 + 4 − 2 (ACDE is counted twice) = 6. 8 is the naive sum without inclusion–exclusion; 2 counts only the candidate keys, and 3 adds just R itself.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-252","question":"Σ = {C → A, AB → D, BC → D, A → B, D → B} on R(A, B, C, D, E). Exactly one FD in Σ is redundant (it can be derived from the others). Which one?","options":["BC → D","C → A","AB → D","D → B"],"answer":0,"explanation":"Remove BC → D and compute {BC}⁺ under the remaining FDs: it still contains D, so that FD is redundant. Removing any other FD loses information.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-253","question":"R(A, B, C, D, E, F) has functional dependencies B → ACDF, A → B. How many superkeys does R have?","options":["16","24","23","32"],"answer":1,"explanation":"Candidate keys are {AE, BE}. Count supersets of each key and apply inclusion–exclusion (a set may contain two keys): the total is 24, not the naive sum 32.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-254","question":"R(A, B) = {(2, 1), (3, 1), (3, 3), (3, 4), (4, 4)} and S(B, C) = {(1, 5), (2, 5), (2, 7), (3, 7)}. How many tuples are in R ⟕ S (left outer join) and in R ⟗ S (full outer join)?","options":["3 and 5","5 and 9","5 and 7","5 and 8"],"answer":2,"explanation":"R ⋈ S has 3 tuples; 2 R tuple(s) find no partner and are padded with NULL, giving 5. The full outer join also keeps 2 unmatched S tuple(s): 7.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-255","question":"A relation has 100,000 tuples and a selection σ_{city='Pune'} with an estimated selectivity of 2%. Each block holds 50 tuples and the relation is clustered (sorted) on city. Using a clustering B+ tree index of height 3 (excluding the data level), about how many block accesses are needed?","options":["5 (3 + 2 data blocks)","2,000 (full scan)","2,003 (3 + one per matching tuple)","43 (3 index + 40 data blocks)"],"answer":3,"explanation":"2% of 100,000 = 2,000 matching tuples, stored contiguously in 2,000/50 = 40 blocks. Traversing the index costs 3, so about 43. A non-clustering index could need one block per tuple.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-256","question":"Classify the schedule W1(A), R2(A), R1(B), R1(A), C1, R2(B), W2(A), C2 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Recoverable but not cascadeless","Not recoverable","Cascadeless but not strict","Strict"],"answer":0,"explanation":"Some transaction reads a value written by an uncommitted transaction (not cascadeless), but each such reader commits after the writer, so the schedule is recoverable.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-257","question":"R(A, B, C, D, E, F) has the set of functional dependencies Σ = {CE → B, A → F, BE → D, AF → B}. Which of the following FDs is NOT in Σ⁺ (not implied by Σ)?","options":["AE → D","AC → D","AC → B","CE → D"],"answer":1,"explanation":"{AC}⁺ = {ABCF} does not contain D, so AC → D is not implied; each of the other three follows by computing its LHS closure (augmentation and transitivity).","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-258","question":"For the schedule W4(C), W1(A), R4(B), R2(A), R3(C), W3(A), R2(B), R1(B), how many serial schedules of T1–T4 are conflict-equivalent to it?","options":["2","6","3","4"],"answer":2,"explanation":"Precedence edges: T1→T2, T1→T3, T2→T3, T4→T3. Counting the topological orders of this DAG gives 3.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-259","question":"Extendible hashing uses the LOWEST-order bits of a key's binary value, bucket capacity 2, and starts with global depth 0 and one empty bucket. A full bucket splits on its next bit; the directory doubles only when the splitting bucket's local depth equals the global depth (repeat splits if needed). After inserting 21, 39, 55, 10, 8, 25, 56 in this order, what are the global depth and the number of distinct buckets?","options":["Global depth 3, 4 buckets","Global depth 2, 5 buckets","Global depth 1, 4 buckets","Global depth 2, 4 buckets"],"answer":3,"explanation":"Tracing the low-order bits: the directory grows to 2^2 = 4 entries, but buckets that never split stay shared by several entries, so only 4 distinct buckets exist.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-260","question":"Which statement about shadow paging is correct?","options":["It needs no undo log, but committing scatters pages and old pages must be garbage-collected","It supports concurrent transactions more easily than logging","It updates pages in place and keeps a before-image copy","It needs both undo and redo logs"],"answer":0,"explanation":"Updates go to new page copies and commit is an atomic switch of the page-table pointer, so aborting just discards the shadow; the costs are lost data clustering and garbage collection.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-261","question":"A bitmap index is built on an attribute with 4 distinct values over a table of 1,000,000 rows (uncompressed, one bit per row per value). What is the total size of the bitmaps?","options":["125,000 bytes (1,000,000 bits)","500,000 bytes (4,000,000 bits)","4,000,000 bytes","250,000 bytes (2,000,000 bits)"],"answer":1,"explanation":"There is one bitmap per distinct value, each with one bit per row: 4 × 1,000,000 = 4,000,000 bits = 500,000 bytes. Using 2 bits per row (log₂ 4) is an encoded index, not a bitmap index.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-262","question":"Classify the schedule R2(A), W2(B), C2, W1(B), R1(A), C1 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Recoverable but not cascadeless","Not recoverable","Strict","Cascadeless but not strict"],"answer":2,"explanation":"No transaction reads or overwrites an item last written by a transaction that has not yet committed, so the schedule is strict (hence cascadeless and recoverable).","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-263","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT id, SUM(amt) OVER (PARTITION BY rep ORDER BY id) AS run\nFROM Sale\nWHERE rep = 'Ira'\nORDER BY id;\n```","options":["(1, 300), (3, 300), (6, 300)","(1, 100), (3, NULL), (6, 300)","(1, 100), (3, NULL), (6, NULL)","(1, 100), (3, 100), (6, 300)"],"answer":3,"explanation":"A running SUM skips NULLs rather than becoming NULL: after id 3 the total is still 100, and id 6 adds 200 to make 300.","difficulty":"hard","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-264","question":"A file has 120,000 records of 150 bytes, stored unspanned in 4096-byte blocks and ordered on key K. A primary (sparse) index on K has one entry per data block, each entry being a 16-byte key plus a 8-byte block pointer. How many block accesses does a binary search on the INDEX plus one data-block read need, in the worst case?","options":["6","5","11","13"],"answer":0,"explanation":"bfr = ⌊4096/150⌋ = 27, so 4,445 data blocks. Index bfr = ⌊4096/24⌋ = 170, so ⌈4445/170⌉ = 27 index blocks; binary search takes ⌈log₂ 27⌉ = 5 accesses, +1 for the data block = 6.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-265","question":"Employee(eid, name) has a recursive one-to-many relationship 'manages' (a manager manages many employees; each employee has at most one manager). What is the minimum number of tables for this design?","options":["0 — recursive relationships cannot be mapped","1","3","2"],"answer":1,"explanation":"Add a nullable foreign key mgr_eid in Employee referring to Employee itself; no separate table is needed for a 1:N recursive relationship.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-266","question":"In logical query processing order, which clause of a SELECT statement is evaluated LAST?","options":["GROUP BY","HAVING","ORDER BY","SELECT"],"answer":2,"explanation":"The logical order is FROM → WHERE → GROUP BY → HAVING → SELECT → (DISTINCT) → ORDER BY (then LIMIT/OFFSET). That is why ORDER BY may use SELECT aliases but WHERE cannot.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-267","question":"R(A, B, C, D, E, F) has FDs C → AD, EF → C, B → A, AD → E. Each option is a relation schema obtained by projecting R, with the dependencies implied on its attributes. Which one is NOT in BCNF?","options":["(A, E, F)","(A, C, E)","(A, C, D)","(C, E, F)"],"answer":3,"explanation":"Project the closure of the given FDs onto each schema. On (C, E, F), C → E holds but C is not a key of the projection, so BCNF fails; on the other three every projected FD has a key on the left (or none is non-trivial).","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-268","question":"Table Product(pid, cat, price) rows: (1, 'X', 10), (2, 'X', 20), (3, 'Y', 20), (4, NULL, 30), (5, 'Y', NULL), (6, 'Z', 5).\nWhat does this query return?\n```sql\nSELECT pid FROM Product\nWHERE price IS NOT NULL\nORDER BY price DESC, pid\nLIMIT 2 OFFSET 1;\n```","options":["2, 3","2, 1","3, 1","4, 2"],"answer":0,"explanation":"Sorted by price desc then pid: 4 (30), 2 (20), 3 (20), 1 (10), 6 (5). Skip one row and take two: 2, 3.","difficulty":"moderate","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-269","question":"A B+ tree has at most 21 children per internal node and at most 20 keys per leaf. A non-root internal node must have at least ⌈21/2⌉ children, a leaf at least ⌈20/2⌉ keys, and the root (if internal) at least 2 children. What is the MINIMUM number of keys in such a tree with exactly 3 levels?","options":["1210","220","2420","440"],"answer":1,"explanation":"Minimum: root has 2 children, each lower internal level multiplies by 11, so there are 2·11^1 = 22 leaves, each with 10 keys: 220. Forgetting that the root needs only 2 children gives 1210.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-270","question":"R(A, B, C, D, E) with functional dependencies B → A, E → D, D → C is decomposed into R1(A, B), R2(A, C), R3(C, D, E). Which statement is correct?","options":["Neither lossless join nor dependency preserving","Lossless join and dependency preserving","Dependency preserving but not lossless join","Lossless join but not dependency preserving"],"answer":2,"explanation":"The chase (tableau) test never produces an all-distinguished row, so the join is lossy. Every FD of F follows from the FDs projected onto the parts, so dependencies are preserved.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-271","question":"Classify the schedule R3(A), W1(B), R1(A), R3(B), W2(B), R2(A), R2(B), W3(B).","options":["Conflict serializable but not view serializable","Neither conflict nor view serializable","Conflict serializable (hence also view serializable)","View serializable but not conflict serializable"],"answer":3,"explanation":"The precedence graph has a cycle, but blind writes let the serial order T2 → T1 → T3 match every reads-from relation and every final write, so it is view serializable only.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-272","question":"R(A, B, C, D, E, F) has functional dependencies F → AB, D → C, C → F, CE → D. How many superkeys does R have?","options":["24","16","32","23"],"answer":0,"explanation":"Candidate keys are {CE, DE}. Count supersets of each key and apply inclusion–exclusion (a set may contain two keys): the total is 24, not the naive sum 32.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-273","question":"R(A, B, C, D, E) has the set of functional dependencies Σ = {E → AC, C → B, AE → B, A → D}. Which of the following FDs is NOT in Σ⁺ (not implied by Σ)?","options":["AC → D","AC → E","AE → C","E → B"],"answer":1,"explanation":"{AC}⁺ = {ABCD} does not contain E, so AC → E is not implied; each of the other three follows by computing its LHS closure (augmentation and transitivity).","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-274","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM (SELECT DISTINCT rep, region FROM Sale);\n```","options":["5","3","6","2"],"answer":2,"explanation":"DISTINCT applies to the (rep, region) pair: (Ira, N), (Jai, S), (Ira, S), (Kim, N), (Jai, N), (Lal, NULL). Only Ira's two N sales collapse: 7 − 1 = 6. DISTINCT keeps the NULL pair (5 would be COUNT(DISTINCT rep, region), which skips it); 3 and 2 come from looking at region alone.","difficulty":"moderate","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-275","question":"Keys 47, 46, 27, 42, 22, 7, 58, 45, 48, 51 are inserted in this order into an empty B+ tree where a node holds at most 3 keys; an overflowing leaf with 4 keys keeps the first 2 and moves the rest to a new right leaf, copying the new leaf's first key up; an overflowing internal node with 4 keys keeps the first 2, moves the next key up and puts the rest in a new right node. After all insertions, how many leaf nodes are there and what is the height (number of levels)?","options":["3 leaves, height 2","4 leaves, height 3","5 leaves, height 2","4 leaves, height 2"],"answer":3,"explanation":"Simulating the splits gives leaves 7,22 | 27,42,45 | 46,47 | 48,51,58 and root keys [27, 46, 48], so 4 leaves at height 2.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-276","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT rep FROM Sale s\nWHERE amt = (SELECT MAX(amt) FROM Sale t\n             WHERE t.region = s.region)\nORDER BY rep;\n```","options":["Jai, Kim","Ira, Jai, Kim","Jai, Kim, Lal","Kim"],"answer":0,"explanation":"Per region: N's maximum is Kim's 300, S's maximum is Jai's 250 (NULL ignored). Lal's region is NULL, so t.region = NULL matches nothing, MAX is NULL and the comparison is unknown.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-277","question":"R(A, B) = {(5, 2), (8, 1), (8, 2), (11, 1), (14, 2)}. What does π_A(R) − π_{R1.A}(σ_{R1.A < R2.A}(ρ_{R1}(R) × ρ_{R2}(R))) return?","options":["{5}","{14}","{5, 8, 11}","{8, 11, 14}"],"answer":1,"explanation":"The subtracted part collects every A value that is smaller than some other A value; what remains is the value with no larger value, i.e. the maximum, 14.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-278","question":"Assertion (A): A schedule can be conflict serializable and still not be recoverable.\nReason (R): Serializability concerns the order of conflicting operations, while recoverability concerns the order of commits relative to reads-from.","options":["A is false, but R is true","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is true, but R is false"],"answer":2,"explanation":"For example W1(A), R2(A), C2, C1 is serializable (T1 → T2) but not recoverable because T2 commits before the T1 it read from. The two properties are independent, as R says.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-279","question":"How many of these statements about two-phase locking are correct?\n1. Basic 2PL guarantees conflict serializability.\n2. Basic 2PL prevents deadlocks.\n3. Strict 2PL avoids cascading rollbacks.\n4. Conservative (static) 2PL is deadlock-free.\n5. Under rigorous 2PL, transactions can be serialized in their commit order.","options":["2","5","3","4"],"answer":3,"explanation":"All except statement 2 are true. 2PL itself does not prevent deadlocks — two transactions can each hold a lock the other wants. Conservative 2PL avoids deadlock by taking all locks up front.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-280","question":"Table Route(src, dst, cost) rows: ('A', 'B', 5), ('B', 'C', 4), ('A', 'C', 12), ('C', 'D', 3), ('B', 'D', 9), ('D', 'A', 2).\nWhat does this query return?\n```sql\nSELECT MIN(r1.cost + r2.cost)\nFROM Route r1 JOIN Route r2 ON r1.dst = r2.src\nWHERE r1.src = 'A' AND r2.dst = 'D';\n```","options":["14","15","9","12"],"answer":0,"explanation":"Two-leg paths A→?→D: A→B→D costs 5 + 9 = 14 and A→C→D costs 12 + 3 = 15. The cheaper overall route A→B→C→D (12) has three legs and is not produced by this query.","difficulty":"hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-281","question":"A file of 1000 blocks is sorted by external merge sort with M = 11 buffer blocks (sorted runs of M blocks are created in pass 0, then (M − 1)-way merges). How many passes in total are needed, and how many block transfers if each pass reads and writes every block once?","options":["4 passes, 8,000 transfers","3 passes, 6,000 transfers","3 passes, 3,000 transfers","2 passes, 4,000 transfers"],"answer":1,"explanation":"Pass 0 makes ⌈1000/11⌉ = 91 runs; each merge pass divides the run count by 10, needing 2 merge pass(es). Total 3 passes × 2 × 1000 = 6,000 transfers.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-282","question":"The system crashes after the last record of this log (immediate database modification; <Ti, X> denotes an update with old and new values; the checkpoint lists the transactions active at that moment and all dirty pages were flushed when it was taken):\n<T2 start>, <T4 start>, <T2, A>, <T3 start>, <T1 start>, <T4, B>, <T1, C>, <T3, D>, <T5 start>, <T3 commit>, <T5, E>, <checkpoint {T1, T2, T4, T5}>, <T5, F>, <T4, G>, <T1, H>, <T5 commit>, <T2, I>, <T1 commit>\nWhich transactions must be undone and which redone?","options":["Undo {T1, T5}; redo {T2, T4}","Undo {T2, T4}; redo {T1, T3, T5}","Undo {T2, T4}; redo {T1, T5}","Undo {T2, T4}; redo {T1}"],"answer":2,"explanation":"Transactions that committed before the checkpoint (T3) are already on disk and need nothing. Those that committed after it (T1, T5) are redone, whether they started before or after it. Those with no commit record (T2, T4) are undone, including any that were active at the checkpoint.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-283","question":"T1 has 3 operations, T2 has 2 and T3 has 2. How many concurrent schedules (interleavings that keep each transaction's own order) exist, and how many of them are non-serial?","options":["210 and 207","5040 and 5034","35 and 29","210 and 204"],"answer":3,"explanation":"Interleavings = 7!/(3!·2!·2!) = 210. Exactly 3! = 6 of them are serial, so 204 are non-serial.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-284","question":"A query must list departments whose average salary exceeds 50000, considering only employees hired after 2020. Which clause placement is correct?","options":["Hiring filter in WHERE, average test in HAVING","Both conditions in HAVING with no WHERE","Both conditions in WHERE","Average test in WHERE, hiring filter in HAVING"],"answer":0,"explanation":"WHERE filters rows before grouping and cannot contain aggregates; HAVING filters groups and is where AVG(salary) > 50000 belongs. Putting a per-row filter in HAVING is invalid unless it is grouped.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-285","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT MAX(pay) FROM Staff\nWHERE pay < (SELECT MAX(pay) FROM Staff);\n```","options":["70","55","NULL","40"],"answer":1,"explanation":"The inner MAX is 70 (two people earn it). The largest pay strictly below 70 is 55 — the second-highest DISTINCT pay.","difficulty":"moderate","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-286","question":"R(A, B, C, D, E) has functional dependencies CE → A, A → CE, BE → A, BC → E, E → BC. What is the highest normal form R satisfies?","options":["1NF but not 2NF","BCNF","3NF but not BCNF","2NF but not 3NF"],"answer":2,"explanation":"Candidate keys: {AD, DE, BCD}. Every non-trivial FD has a superkey LHS or a prime RHS, so it is in 3NF; but A → B has a non-superkey LHS (B is prime), so BCNF fails.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-287","question":"A transaction has executed its final statement, but its commit record is not yet on stable storage. Which state is it in?","options":["Failed","Committed","Active","Partially committed"],"answer":3,"explanation":"After the last operation the transaction is partially committed; it becomes committed only once the commit record is durable. A crash at this point means it must be rolled back.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-288","question":"R(A, B, C, D, E, F) has functional dependencies EF → D, B → C, D → BF, A → E. How many superkeys does R have?","options":["24","16","32","23"],"answer":0,"explanation":"Candidate keys are {AD, AF}. Count supersets of each key and apply inclusion–exclusion (a set may contain two keys): the total is 24, not the naive sum 32.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-289","question":"Table Product(pid, cat, price) rows: (1, 'X', 10), (2, 'X', 20), (3, 'Y', 20), (4, NULL, 30), (5, 'Y', NULL), (6, 'Z', 5).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Product p\nWHERE price > (SELECT AVG(price) FROM Product q\n               WHERE q.cat = p.cat);\n```","options":["2","1","3","0"],"answer":1,"explanation":"X average is 15, so pid 2 (20) qualifies. Y's average is 20 and 20 > 20 is false; Z has one row; the NULL-cat row's subquery matches nothing. Only 1 row.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-290","question":"R(A, B, C, D, E) with functional dependencies E → BC, D → B is decomposed into R1(A, B, D), R2(C, D), R3(B, C, E). Which statement is correct?","options":["Neither lossless join nor dependency preserving","Lossless join and dependency preserving","Dependency preserving but not lossless join","Lossless join but not dependency preserving"],"answer":2,"explanation":"The chase (tableau) test never produces an all-distinguished row, so the join is lossy. Every FD of F follows from the FDs projected onto the parts, so dependencies are preserved.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-291","question":"A B+ tree index uses 1024-byte blocks, 12-byte search keys, 10-byte block pointers and 6-byte record (data) pointers. Each leaf also keeps one block pointer to the next leaf. What is the maximum number of keys a LEAF node can hold?","options":["55","46","47","56"],"answer":3,"explanation":"A leaf holds q (key, record-pointer) pairs plus one next-leaf pointer: 18·q + 10 ≤ 1024 gives q = ⌊(1024 − 10)/18⌋ = 56. Using the block-pointer size or forgetting the sibling pointer gives the traps.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-292","question":"Which statement about a UNIQUE constraint versus a PRIMARY KEY in standard SQL is correct?","options":["A table may have several UNIQUE constraints, and UNIQUE columns may hold NULLs; there is only one PRIMARY KEY and it cannot be NULL","A table may have several PRIMARY KEYs but only one UNIQUE constraint","UNIQUE columns cannot be NULL","A foreign key can reference only a PRIMARY KEY, never a UNIQUE column"],"answer":0,"explanation":"PRIMARY KEY = UNIQUE + NOT NULL, one per table. Any number of UNIQUE constraints are allowed, and NULLs in them are not treated as duplicates in the standard.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-293","question":"Consider the schedule R1(B), W3(B), W3(A), R2(B), W2(A), R1(A), W1(A). Which statement is correct?","options":["Conflict serializable, equivalent to T3 → T2 → T1","It is not conflict serializable","Conflict serializable, equivalent to T2 → T1 → T3","Conflict serializable, equivalent to T1 → T3 → T2"],"answer":1,"explanation":"The precedence graph has both T3 → T1 and T1 → T3 (a cycle), so no serial order exists.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-294","question":"Extendible hashing uses the LOWEST-order bits of a key's binary value, bucket capacity 2, and starts with global depth 0 and one empty bucket. A full bucket splits on its next bit; the directory doubles only when the splitting bucket's local depth equals the global depth (repeat splits if needed). After inserting 59, 44, 33, 53, 58, 17, 15 in this order, what are the global depth and the number of distinct buckets?","options":["Global depth 2, 4 buckets","Global depth 3, 8 buckets","Global depth 3, 4 buckets","Global depth 4, 4 buckets"],"answer":2,"explanation":"Tracing the low-order bits: the directory grows to 2^3 = 8 entries, but buckets that never split stay shared by several entries, so only 4 distinct buckets exist.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-295","question":"Table Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat does this query return?\n```sql\nSELECT cid, AVG(marks), COUNT(*)\nFROM Takes\nGROUP BY cid\nORDER BY cid;\n```","options":["(C1, 65, 3), (C2, 45, 2), (C3, 75, 1)","(C1, 72.5, 2), (C2, 90, 2), (C3, 75, 1)","(C1, 65, 3), (C2, 90, 1), (C3, 75, 1)","(C1, 65, 3), (C2, 90, 2), (C3, 75, 1)"],"answer":3,"explanation":"C1: (80 + 65 + 50)/3 = 65 (sid 5 counts, Takes has no FK check here). C2: AVG skips the NULL so it is 90, while COUNT(*) still counts 2 rows.","difficulty":"hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-296","question":"R(A, B, C, D, E, F) has functional dependencies BD → E, D → AF, E → AB, BC → D. Which of the following is the complete set of candidate keys of R?","options":["{BC, CE}","{BC, BCE}","{BC, BE, CE}","{BC}"],"answer":0,"explanation":"Attributes never on a right side (C) must be in every key; extending them and testing closures gives exactly the minimal superkeys {BC, CE}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-297","question":"T1: W1(B), R1(B), R1(A) and T2: W2(A), R2(B), R2(A). Of all 20 interleavings that keep each transaction's own order, how many are conflict serializable?","options":["20","5","2","4"],"answer":1,"explanation":"Enumerate the C(6, 3) = 20 interleavings and draw the precedence graph of each; exactly 5 have no cycle (all edges between T1 and T2 point the same way). The two serial schedules are always among them.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-298","question":"Σ = {B → C, C → B, AE → D, F → B, DF → C} on R(A, B, C, D, E, F). Exactly one FD in Σ is redundant (it can be derived from the others). Which one?","options":["B → C","AE → D","DF → C","F → B"],"answer":2,"explanation":"Remove DF → C and compute {DF}⁺ under the remaining FDs: it still contains C, so that FD is redundant. Removing any other FD loses information.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-299","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT rep FROM Sale WHERE region = 'N'\nEXCEPT\nSELECT rep FROM Sale WHERE region = 'S';\n```","options":["Ira, Jai, Kim","Kim, Lal","Ira, Kim","Kim"],"answer":3,"explanation":"N reps are {Ira, Jai, Kim}; S reps are {Jai, Ira}. EXCEPT is a set difference with duplicates removed, leaving only Kim.","difficulty":"moderate","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-300","question":"R(A, B) = {(1, 1), (1, 3), (3, 2), (4, 1), (4, 2), (4, 4)} and S(B, C) = {(1, 5), (1, 7), (3, 7), (4, 5)}. What is π_A(R) − π_A(R ⋈ S)?","options":["{3}","{1, 4}","{3, 4}","∅"],"answer":0,"explanation":"This keeps A values ALL of whose tuples fail to join. An A value with at least one joining B is removed entirely, so the answer is {3}, not merely the A values of non-joining tuples.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-301","question":"R(A, B, C, D, E) has functional dependencies AD → C, B → AE, D → B, AB → D. What is the highest normal form R satisfies?","options":["1NF but not 2NF","BCNF","2NF but not 3NF","3NF but not BCNF"],"answer":1,"explanation":"Candidate keys: {B, D}. The left side of every non-trivial dependency in F+ is a superkey, so R is in BCNF.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-302","question":"R(A, B) = {(1, 2), (1, 4), (2, 4), (4, 1), (4, 2)} and S(B, C) = {(1, 6), (3, 5), (3, 7), (4, 6), (4, 7)}. How many tuples are in π_A(R ⋈ S) and in R ⋈ S respectively (set semantics)?","options":["5 and 5","3 and 25","3 and 5","3 and 6"],"answer":2,"explanation":"R ⋈ S pairs each R tuple with every S tuple having the same B: 5 tuples. Projecting on A removes duplicates, leaving {1, 2, 4}.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-303","question":"Consider the schedule R1(A), W2(B), W3(B), R2(B), W1(A), R2(A), W1(B), W3(A). Which statement is correct?","options":["Conflict serializable, equivalent to T2 → T3 → T1","Conflict serializable, equivalent to T1 → T2 → T3","Conflict serializable, equivalent to T3 → T1 → T2","It is not conflict serializable"],"answer":3,"explanation":"The precedence graph has both T1 → T2 and T2 → T1 (a cycle), so no serial order exists.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-304","question":"Σ = {C → B, B → F, F → E, CD → F, DE → B} on R(A, B, C, D, E, F). Exactly one FD in Σ is redundant (it can be derived from the others). Which one?","options":["CD → F","DE → B","B → F","C → B"],"answer":0,"explanation":"Remove CD → F and compute {CD}⁺ under the remaining FDs: it still contains F, so that FD is redundant. Removing any other FD loses information.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-305","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT s.name\nFROM Staff s JOIN (SELECT dept, MAX(pay) AS m FROM Staff GROUP BY dept) t\n  ON s.dept = t.dept AND s.pay = t.m\nORDER BY s.name;\n```","options":["Bala, Chitra, Esha, Farid","Bala, Chitra, Farid","Bala, Chitra","Chitra, Farid"],"answer":1,"explanation":"Group maxima: Ops 55, Tech 70, NULL-dept group 35. Joining back on s.dept = t.dept fails for Esha because NULL = NULL is unknown, so the result is Bala, Chitra and Farid (both 70s tie).","difficulty":"very-hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-306","question":"R has 2000 tuples in 100 blocks and S has 10000 tuples in 400 blocks. With only enough memory for one block of each relation, how many block transfers does the TUPLE-at-a-time nested-loop join with R as outer need, and how many does the block nested-loop join with R as outer need?","options":["800,100 and 800,000","1,000,400 and 40,400","800,100 and 40,100","20,000,100 and 40,100"],"answer":2,"explanation":"Tuple NL reads S once per R tuple: 2000·400 + 100. Block NL reads S once per R block: 100·400 + 100.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-307","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Staff WHERE dept <> 'Ops';\n```","options":["2","4","6","3"],"answer":3,"explanation":"Chitra, Dev and Farid are in Tech. Esha's dept is NULL, and NULL <> 'Ops' is UNKNOWN, so her row is filtered out: 3, not 4.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-308","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Sale\nWHERE NOT (region = 'N');\n```","options":["2","3","4","7"],"answer":0,"explanation":"Only rows where region = 'N' is FALSE survive: the two 'S' rows. For Lal, region is NULL, so the condition is UNKNOWN and NOT UNKNOWN is still UNKNOWN.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-309","question":"Consider the schedule R2(B), R3(A), W3(A), R2(A), W2(B), R1(B), R1(A). Which statement is correct?","options":["Conflict serializable, equivalent only to T3 → T1 → T2","Conflict serializable, equivalent only to T3 → T2 → T1","Conflict serializable, equivalent only to T2 → T1 → T3","It is not conflict serializable"],"answer":1,"explanation":"Conflict edges: T2→T1, T3→T1, T3→T2. The graph is acyclic and its only topological order is T3 → T2 → T1.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-310","question":"The system crashes after the last record of this log (immediate database modification; <Ti, X> denotes an update with old and new values; the checkpoint lists the transactions active at that moment and all dirty pages were flushed when it was taken):\n<T4 start>, <T1 start>, <T4, A>, <T4 commit>, <T1, B>, <checkpoint {T1}>, <T5 start>, <T3 start>, <T3, C>, <T2 start>, <T5, D>, <T1, E>, <T2, F>, <T2 commit>, <T1 commit>, <T3 commit>\nWhich transactions must be undone and which redone?","options":["Undo {T1, T2, T3}; redo {T5}","Undo {T5}; redo {T2, T3}","Undo {T5}; redo {T1, T2, T3}","Undo {T5}; redo {T1, T2, T3, T4}"],"answer":2,"explanation":"Transactions that committed before the checkpoint (T4) are already on disk and need nothing. Those that committed after it (T1, T2, T3) are redone, whether they started before or after it. Those with no commit record (T5) are undone, including any that were active at the checkpoint.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-311","question":"R(A, B, C, D, E) has functional dependencies CE → A, B → AC, BE → CD, DE → B. How many superkeys does R have?","options":["16","11","8","12"],"answer":3,"explanation":"Candidate keys are {BE, DE}. Count supersets of each key and apply inclusion–exclusion (a set may contain two keys): the total is 12, not the naive sum 16.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-312","question":"Classify the schedule W1(B), W2(A), R2(B), C2, W1(A), C1 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Not recoverable","Cascadeless but not strict","Strict","Recoverable but not cascadeless"],"answer":0,"explanation":"A transaction reads a value written by another transaction and commits before that writer commits; if the writer then aborted, the committed reader could not be undone.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-313","question":"R(A, B, C, D, E) has functional dependencies CE → A, A → D, AC → DE, B → D. How many superkeys does R have?","options":["3","6","2","8"],"answer":1,"explanation":"B and C never appear on a right side, so every key contains BC; the candidate keys are ABC and BCE. Supersets: 4 + 4 − 2 (ABCE is counted twice) = 6. 8 is the naive sum without inclusion–exclusion; 2 counts only the candidate keys, and 3 adds just R itself.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-314","question":"R(A, B) = {(1, 1), (1, 3), (3, 1), (3, 2), (3, 3)} and S(B, C) = {(1, 5), (2, 5), (2, 6), (2, 7), (4, 6)}. How many tuples are in π_A(R ⋈ S) and in R ⋈ S respectively (set semantics)?","options":["2 and 25","2 and 6","2 and 5","5 and 5"],"answer":2,"explanation":"R ⋈ S pairs each R tuple with every S tuple having the same B: 5 tuples. Projecting on A removes duplicates, leaving {1, 3}.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-315","question":"R(A, B, C, D, E, F) has functional dependencies AE → F, A → BCD, F → B. What is the closure {AC}⁺?","options":["{ABCDE}","{ABC}","{ABCDEF}","{ABCD}"],"answer":3,"explanation":"Keep applying any FD whose left side is already inside the set until nothing changes; one pass in listed order is not enough. The result is {ABCD}.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-316","question":"Assertion (A): For every relation schema there is a decomposition into 3NF relations that is lossless and dependency preserving.\nReason (R): A 3NF relation can never contain redundancy caused by functional dependencies.","options":["A is true, but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is false, but R is true"],"answer":0,"explanation":"A is the guarantee of 3NF synthesis. R is false: 3NF still allows FDs X → A with A prime and X not a superkey, which causes redundancy — that is why BCNF exists.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-317","question":"Σ = {A → D, AB → E, B → C, C → BE}. Consider the FD AB → E while computing a canonical cover. Which statement about extraneous attributes on its left side is correct?","options":["Neither A nor B is extraneous","Only A is extraneous","Either A or B (but not both) can be dropped","Only B is extraneous"],"answer":1,"explanation":"Test each attribute: A is extraneous iff {B}⁺ (under Σ) contains E; {B}⁺ = {BCE} and {A}⁺ = {AD}.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-318","question":"The system crashes after the last record of this log (immediate database modification; <Ti, X> denotes an update with old and new values; the checkpoint lists the transactions active at that moment and all dirty pages were flushed when it was taken):\n<T1 start>, <T1, A>, <T2 start>, <T2, B>, <T2 commit>, <checkpoint {T1}>, <T5 start>, <T1, C>, <T3 start>, <T5, D>, <T4 start>, <T4, E>, <T3, F>, <T1 commit>, <T3 commit>\nWhich transactions must be undone and which redone?","options":["Undo {T4}; redo {T1, T3}","Undo {T4, T5}; redo {T1, T2, T3}","Undo {T4, T5}; redo {T1, T3}","Undo {T1, T3}; redo {T4, T5}"],"answer":2,"explanation":"Transactions that committed before the checkpoint (T2) are already on disk and need nothing. Those that committed after it (T1, T3) are redone, whether they started before or after it. Those with no commit record (T4, T5) are undone, including any that were active at the checkpoint.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-319","question":"R(A, B, C, D, E) has functional dependencies A → DE, C → AD, AD → C, E → AC. Which of the following is the complete set of candidate keys of R?","options":["{AB, AC, BC, BE}","{AB, BC, BCE}","{AB, BC}","{AB, BC, BE}"],"answer":3,"explanation":"Attributes never on a right side (B) must be in every key; extending them and testing closures gives exactly the minimal superkeys {AB, BC, BE}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-320","question":"Keys 4, 38, 33, 56, 40, 14, 54 are inserted in this order into an empty B+ tree where a node holds at most 2 keys; an overflowing leaf with 3 keys keeps the first 2 and moves the rest to a new right leaf, copying the new leaf's first key up; an overflowing internal node with 3 keys keeps the first 1, moves the next key up and puts the rest in a new right node. After all insertions, how many leaf nodes are there and what is the height (number of levels)?","options":["5 leaves, height 3","4 leaves, height 3","6 leaves, height 3","5 leaves, height 2"],"answer":0,"explanation":"Simulating the splits gives leaves 4,14 | 33 | 38,40 | 54 | 56 and root keys [38], so 5 leaves at height 3.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-321","question":"Σ = {AE → D, BC → D, C → A, A → E, D → B} on R(A, B, C, D, E). Exactly one FD in Σ is redundant (it can be derived from the others). Which one?","options":["C → A","BC → D","AE → D","D → B"],"answer":1,"explanation":"Remove BC → D and compute {BC}⁺ under the remaining FDs: it still contains D, so that FD is redundant. Removing any other FD loses information.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-322","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT COUNT(*), COUNT(dept), COUNT(DISTINCT dept), COUNT(pay)\nFROM Staff;\n```","options":["6, 5, 3, 5","6, 6, 3, 6","6, 5, 2, 5","5, 5, 2, 5"],"answer":2,"explanation":"COUNT(*) counts rows (6); COUNT(col) skips NULLs (dept 5, pay 5); COUNT(DISTINCT dept) also ignores NULL, leaving Ops and Tech = 2.","difficulty":"moderate","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-323","question":"R(A, B, C, D, E) has functional dependencies B → ACD, BC → AD, C → A. What is the closure {B}⁺?","options":["{BCD}","{ABCDE}","{ABC}","{ABCD}"],"answer":3,"explanation":"Keep applying any FD whose left side is already inside the set until nothing changes; one pass in listed order is not enough. The result is {ABCD}.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-324","question":"Which statement about the multivalued dependency X ↠ Y on R is correct?","options":["It is trivial if Y ⊆ X or X ∪ Y = R","It is trivial only if Y ⊆ X","Every MVD X ↠ Y implies the FD X → Y","X ↠ Y holds only if X ↠ R − X − Y fails"],"answer":0,"explanation":"An MVD is trivial when Y ⊆ X or X ∪ Y covers all attributes. FDs imply MVDs (X → Y gives X ↠ Y), not the other way round, and by complementation X ↠ Y always brings X ↠ R − X − Y with it.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-325","question":"R(A, B, C, D, E) has the set of functional dependencies Σ = {AD → BE, D → AE, CE → D, A → B}. Which of the following FDs is NOT in Σ⁺ (not implied by Σ)?","options":["CD → A","BD → C","BD → E","AE → B"],"answer":1,"explanation":"{BD}⁺ = {ABDE} does not contain C, so BD → C is not implied; each of the other three follows by computing its LHS closure (augmentation and transitivity).","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-326","question":"A file of 2400 blocks is sorted by external merge sort with M = 6 buffer blocks (sorted runs of M blocks are created in pass 0, then (M − 1)-way merges). How many passes in total are needed, and how many block transfers if each pass reads and writes every block once?","options":["6 passes, 28,800 transfers","4 passes, 19,200 transfers","5 passes, 24,000 transfers","5 passes, 12,000 transfers"],"answer":2,"explanation":"Pass 0 makes ⌈2400/6⌉ = 400 runs; each merge pass divides the run count by 5, needing 4 merge pass(es). Total 5 passes × 2 × 2400 = 24,000 transfers.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-327","question":"R(A1, A2, …, A8) has the FDs A1 → A2, A2 → A3, …, A7 → A8 and A8 → A1. How many candidate keys does R have, and what is its highest normal form?","options":["1 candidate key; 3NF","8 candidate keys; 3NF but not BCNF","1 candidate key; 2NF","8 candidate keys; BCNF"],"answer":3,"explanation":"The FDs form a cycle, so every single attribute determines all the others: A1, …, A8 are all candidate keys. Every FD then has a key on its left, so R is in BCNF.","difficulty":"hard","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-328","question":"Assertion (A): Every relation schema with exactly two attributes is in BCNF.\nReason (R): For R(X, Y), any non-trivial FD has a single attribute on its left side, and that attribute then determines the whole relation.","options":["Both A and R are true, and R is the correct explanation of A","A is false, but R is true","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false"],"answer":0,"explanation":"With two attributes the only non-trivial FDs are X → Y and Y → X; whichever holds makes its LHS a superkey of R(X, Y), so BCNF can never be violated. R gives exactly that reason.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-329","question":"R(A, B, C, D, E) has functional dependencies CE → BD, DE → A, BD → E. Which of the following is the complete set of candidate keys of R?","options":["{CE}","{CE, BCD}","{CE, ABCE}","{AD, CE, BCD}"],"answer":1,"explanation":"Attributes never on a right side (C) must be in every key; extending them and testing closures gives exactly the minimal superkeys {CE, BCD}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-330","question":"Table Node(id, parent) rows: (1, NULL), (2, 1), (3, 1), (4, 2), (5, 2), (6, 4), (7, 3).\nWhat does this query return?\n```sql\nWITH RECURSIVE sub(id, depth) AS (\n  SELECT id, 0 FROM Node WHERE id = 2\n  UNION ALL\n  SELECT n.id, s.depth + 1\n  FROM Node n JOIN sub s ON n.parent = s.id)\nSELECT COUNT(*), MAX(depth) FROM sub;\n```","options":["3, 2","4, 3","4, 2","7, 3"],"answer":2,"explanation":"Starting at 2 and walking downwards: 2 (depth 0), its children 4 and 5 (depth 1), and 4's child 6 (depth 2). The anchor row is included, so 4 rows.","difficulty":"hard","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-331","question":"R(A, B, C, D, E) has functional dependencies AC → BD, A → CD, C → D, D → A. Which of the following is the complete set of candidate keys of R?","options":["{AE, CE}","{AE, CE, BCE}","{AD, AE, CE, DE}","{AE, CE, DE}"],"answer":3,"explanation":"Attributes never on a right side (E) must be in every key; extending them and testing closures gives exactly the minimal superkeys {AE, CE, DE}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-332","question":"Σ = {C → AE, E → B, AE → C, D → C}. Consider the FD AE → C while computing a canonical cover. Which statement about extraneous attributes on its left side is correct?","options":["Neither A nor E is extraneous","Only E is extraneous","Either A or E (but not both) can be dropped","Only A is extraneous"],"answer":0,"explanation":"Test each attribute: A is extraneous iff {E}⁺ (under Σ) contains C; {E}⁺ = {BE} and {A}⁺ = {A}.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-333","question":"Which statement about a FOREIGN KEY constraint in standard SQL is correct?","options":["It must reference the primary key only","It may reference any UNIQUE (candidate key) column set, and its own columns may be NULL","Its columns must also be the primary key of the referencing table","Its columns can never be NULL"],"answer":1,"explanation":"A foreign key must point at a key of the referenced table (primary or UNIQUE). A NULL foreign key value is allowed and simply means 'no reference'.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-334","question":"Table Score(name, pts) rows: ('a', 90), ('b', 85), ('c', 90), ('d', 70), ('e', 85), ('f', 60).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Score a JOIN Score b ON a.pts < b.pts;\n```","options":["15","10","13","12"],"answer":2,"explanation":"Scores: 90, 90, 85, 85, 70, 60. 60 is below 5 others, 70 below 4, each 85 below 2 (the 90s), and each 90 below none: 5 + 4 + 2 + 2 = 13. Equal scores form no pair.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-335","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat counts do Query 1 and Query 2 return?\n```sql\n-- Query 1\nSELECT COUNT(*) FROM (SELECT COUNT(*), SUM(pay) FROM Staff WHERE pay > 100);\n-- Query 2\nSELECT COUNT(*) FROM (SELECT dept, COUNT(*) FROM Staff WHERE pay > 100 GROUP BY dept);\n```","options":["0 and 1","0 and 0","1 and 1","1 and 0"],"answer":3,"explanation":"An aggregate without GROUP BY always returns exactly one row (COUNT 0, SUM NULL) even when no row qualifies. With GROUP BY there are no groups, so no rows.","difficulty":"hard","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-336","question":"R(A, B, C, D, E) with functional dependencies BE → A, C → AD, D → C is decomposed into R1(C, E), R2(A, D, E), R3(A, B, E). Which statement is correct?","options":["Neither lossless join nor dependency preserving","Dependency preserving but not lossless join","Lossless join but not dependency preserving","Lossless join and dependency preserving"],"answer":0,"explanation":"The chase (tableau) test never produces an all-distinguished row, so the join is lossy. C → AD cannot be derived from the projected FDs, so a dependency is lost.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-337","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT SUM(NULLIF(pay, 70)), COUNT(CASE WHEN pay > 50 THEN 1 END)\nFROM Staff;\n```","options":["200, 3","130, 3","130, 6","270, 3"],"answer":1,"explanation":"NULLIF turns both 70s into NULL, so SUM adds 40 + 55 + 35 = 130. A CASE with no ELSE yields NULL for non-matching rows, and COUNT skips NULLs: only Bala, Chitra and Farid count.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-338","question":"A B+ tree index uses 8192-byte blocks, 24-byte search keys, 10-byte block pointers and 16-byte record (data) pointers. Each leaf also keeps one block pointer to the next leaf. What is the maximum number of keys a LEAF node can hold?","options":["203","241","204","240"],"answer":2,"explanation":"A leaf holds q (key, record-pointer) pairs plus one next-leaf pointer: 40·q + 10 ≤ 8192 gives q = ⌊(8192 − 10)/40⌋ = 204. Using the block-pointer size or forgetting the sibling pointer gives the traps.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-339","question":"R has 1600 tuples in 80 blocks and S has 20000 tuples in 500 blocks. With only enough memory for one block of each relation, how many block transfers does the TUPLE-at-a-time nested-loop join with R as outer need, and how many does the block nested-loop join with R as outer need?","options":["800,080 and 800,000","1,600,500 and 40,500","32,000,080 and 40,080","800,080 and 40,080"],"answer":3,"explanation":"Tuple NL reads S once per R tuple: 1600·500 + 80. Block NL reads S once per R block: 80·500 + 80.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-340","question":"Classify the schedule R1(A), W2(B), W1(A), R2(B), W1(B), W2(A), R3(A), W3(B), W3(A).","options":["View serializable but not conflict serializable","Neither conflict nor view serializable","Conflict serializable but not view serializable","Conflict serializable (hence also view serializable)"],"answer":0,"explanation":"The precedence graph has a cycle, but blind writes let the serial order T1 → T2 → T3 match every reads-from relation and every final write, so it is view serializable only.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-341","question":"Classify the schedule W1(B), W1(A), W3(B), R1(B), R2(B), W3(A), W2(B), R2(A), R3(A).","options":["Conflict serializable (hence also view serializable)","Neither conflict nor view serializable","View serializable but not conflict serializable","Conflict serializable but not view serializable"],"answer":1,"explanation":"The precedence graph has a cycle, and no serial order reproduces the same reads-from pairs and final writes, so it is not even view serializable.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-342","question":"Consider the schedule W3(C), W2(A), W1(A), R1(C), R2(A), R2(C), W3(A). Which statement is correct?","options":["Conflict serializable, equivalent to T3 → T2 → T1","Conflict serializable, equivalent to T1 → T2 → T3","It is not conflict serializable","Conflict serializable, equivalent to T2 → T1 → T3"],"answer":2,"explanation":"The precedence graph has both T1 → T2 and T2 → T1 (a cycle), so no serial order exists.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-343","question":"A B+ tree index uses 1024-byte blocks, 10-byte search keys, 6-byte block (tree) pointers and 8-byte record pointers. What is the maximum number of CHILD pointers an internal node can hold?","options":["65","56","63","64"],"answer":3,"explanation":"An internal node with p children holds p block pointers and p − 1 keys: 6·p + 10·(p − 1) ≤ 1024 gives p = ⌊(1024 + 10)/(10 + 6)⌋ = 64.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-344","question":"R(A, B, C, D, E) has functional dependencies E → B, B → A, D → B, A → D. Which decomposition of R is lossless-join?","options":["(A, B, D), (A, C, E)","(A, D), (B, C, D), (D, E)","(A, C), (B, D, E)","(A, C, D), (B, D, E)"],"answer":0,"explanation":"Run the chase (or, for two parts, check whether the common attributes determine one whole part). Only (A, B, D), (A, C, E) produces an all-distinguished row; in each other option some join step has common attributes that are not a key of either side.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-345","question":"R(A, B, C, D, E) with functional dependencies B → C, D → CE, A → B, CE → A is decomposed into R1(A, B), R2(A, C, E), R3(C, D, E). Which statement is correct?","options":["Lossless join and dependency preserving","Lossless join but not dependency preserving","Dependency preserving but not lossless join","Neither lossless join nor dependency preserving"],"answer":1,"explanation":"The chase (tableau) test produces an all-distinguished row, so the join is lossless. B → C cannot be derived from the projected FDs, so a dependency is lost.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-346","question":"Which inference rule is NOT sound for functional dependencies?","options":["If A → BC holds, then A → B holds","If A → B and A → C hold, then A → BC holds","If AB → C holds, then A → C holds","If A → B and BC → D hold, then AC → D holds"],"answer":2,"explanation":"Removing an attribute from the left side is not valid: AB → C does not force A alone to determine C. The others are pseudotransitivity, decomposition and union, all derivable from Armstrong's axioms.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-347","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nUPDATE Staff SET pay = pay + 10\nWHERE pay < (SELECT AVG(pay) FROM Staff);\nSELECT SUM(pay) FROM Staff;\n```","options":["300","280","310","290"],"answer":3,"explanation":"The subquery is evaluated against the table before the update: average 54. Only Anu (40) and Esha (35) are below it, so the total rises from 270 to 290. Dev's NULL + 10 stays NULL.","difficulty":"very-hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-348","question":"Consider the schedule W1(B), W2(A), R2(A), W1(A), R3(A), W3(B). Which statement is correct?","options":["Conflict serializable, equivalent only to T2 → T1 → T3","It is not conflict serializable","Conflict serializable, equivalent only to T2 → T3 → T1","Conflict serializable, equivalent only to T1 → T3 → T2"],"answer":0,"explanation":"Conflict edges: T1→T3, T2→T1, T2→T3. The graph is acyclic and its only topological order is T2 → T1 → T3.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-349","question":"Classify the schedule W2(A), W1(B), W1(A), R1(B), C1, W2(B), R2(B), C2 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Not recoverable","Cascadeless but not strict","Recoverable but not cascadeless","Strict"],"answer":1,"explanation":"Every read is of committed data (cascadeless), but some transaction overwrites an item whose earlier writer has not committed yet, which strictness forbids.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-350","question":"A query runs WHERE a = 7 AND b > 100 ORDER BY b. Which single B+ tree index serves it best?","options":["An index on b alone","A hash index on (a, b)","A composite index on (a, b)","A composite index on (b, a)"],"answer":2,"explanation":"With (a, b), all entries with a = 7 are contiguous and already sorted by b, so the range b > 100 is one leaf scan in order. With (b, a), entries for a = 7 are scattered over the b range; a hash index cannot do ranges.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-351","question":"R(A, B, C, D) has functional dependencies AD → C, A → D, AC → D, D → A. What is the highest normal form R satisfies?","options":["BCNF","2NF but not 3NF","3NF but not BCNF","1NF but not 2NF"],"answer":3,"explanation":"Candidate keys: {AB, BD}. A → C is a partial dependency: A is a proper subset of key AB and C is non-prime, so 2NF fails.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-352","question":"R occupies 600 blocks and S occupies 400 blocks. Ignoring the cost of writing the result, what is the cost of a hash join (partitioning both relations once, no recursive partitioning, no overflow)?","options":["3,000 block transfers","240,000 block transfers","1,000 block transfers","2,000 block transfers"],"answer":0,"explanation":"Partitioning reads and writes both relations (2 × 1000) and the probe phase reads them once more (1000): 3(bR + bS) = 3000.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-353","question":"In a B+ tree every internal node can have at most 101 children and every leaf can hold at most 80 keys. With exactly 3 levels (root at level 1, leaves at level 3), what is the maximum number of keys the tree can index?","options":["805,879","816,080","1,030,301","800,000"],"answer":1,"explanation":"Fully packed: 2 internal levels give 101^2 = 10,201 leaves, each with 80 keys, so 816,080 keys.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-354","question":"R(A, B) = {(3, 2), (5, 2), (8, 1), (11, 1), (14, 2)}. What does π_A(R) − π_{R1.A}(σ_{R1.A > R2.A}(ρ_{R1}(R) × ρ_{R2}(R))) return?","options":["{14}","{3, 5, 8, 11}","{3}","{5, 8, 11, 14}"],"answer":2,"explanation":"The subtracted part collects every A value that is larger than some other A value; what remains is the value with no smaller value, i.e. the minimum, 3.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-355","question":"Table Score(name, pts) rows: ('a', 90), ('b', 85), ('c', 90), ('d', 70), ('e', 85), ('f', 60).\nWhat does this query return?\n```sql\nSELECT name FROM Score s\nWHERE 2 = (SELECT COUNT(DISTINCT pts) FROM Score t\n           WHERE t.pts > s.pts)\nORDER BY name;\n```","options":["a, c","f","b, e","d"],"answer":3,"explanation":"A row qualifies when exactly two DISTINCT scores are higher than it. Above 70 are only 90 and 85, so d (the third-highest distinct score) is returned. With COUNT(*) instead, b and e (two 90s above 85) would be returned.","difficulty":"very-hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-356","question":"The system crashes after the last record of this log (immediate database modification; <Ti, X> denotes an update with old and new values; the checkpoint lists the transactions active at that moment and all dirty pages were flushed when it was taken):\n<T3 start>, <T3, A>, <T3 commit>, <checkpoint {}>, <T5 start>, <T5, B>, <T4 start>, <T4, C>, <T5 commit>, <T1 start>, <T2 start>, <T2, D>, <T1, E>, <T2 commit>, <T1 commit>\nWhich transactions must be undone and which redone?","options":["Undo {T4}; redo {T1, T2, T5}","Undo {T4}; redo {T1, T2, T3, T5}","Undo {T1, T2, T5}; redo {T4}","Undo {T3, T4}; redo {T1, T2, T5}"],"answer":0,"explanation":"Transactions that committed before the checkpoint (T3) are already on disk and need nothing. Those that committed after it (T1, T2, T5) are redone, whether they started before or after it. Those with no commit record (T4) are undone, including any that were active at the checkpoint.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-357","question":"Classify the schedule R3(A), W2(A), W3(B), R2(B), W3(A), W1(A), R1(B), W1(B).","options":["Conflict serializable but not view serializable","View serializable but not conflict serializable","Neither conflict nor view serializable","Conflict serializable (hence also view serializable)"],"answer":1,"explanation":"The precedence graph has a cycle, but blind writes let the serial order T3 → T2 → T1 match every reads-from relation and every final write, so it is view serializable only.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-358","question":"A multilevel index is built over a first level of 40,000 index entries; every index block holds 34 entries (fan-out 34), and levels are added until the top level fits in one block. How many index levels are there in total, and how many block accesses does a lookup take including one data-block read?","options":["3 levels, 4 accesses","4 levels, 4 accesses","4 levels, 5 accesses","5 levels, 6 accesses"],"answer":2,"explanation":"Blocks per level: 1177 → 35 → 2 → 1; the levels shrink by a factor 34 until one block remains, giving 4 levels. A lookup reads one block per level plus the data block: 5.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-359","question":"Why does a B+ tree usually have a smaller height than a B-tree built on the same key with the same block size?","options":["It never needs to split the root","Its leaves are linked, which reduces the number of levels","It stores every key exactly once","Its internal nodes hold no record pointers, so more keys and child pointers fit per node (higher fan-out)"],"answer":3,"explanation":"In a B-tree every key in every node carries a record pointer, cutting fan-out. B+ internal nodes store only keys and child pointers. Leaf links help range scans but do not reduce height.","difficulty":"hard","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-360","question":"A multilevel index is built over a first level of 1,000,000 index entries; every index block holds 100 entries (fan-out 100), and levels are added until the top level fits in one block. How many index levels are there in total, and how many block accesses does a lookup take including one data-block read?","options":["3 levels, 4 accesses","4 levels, 5 accesses","2 levels, 3 accesses","3 levels, 3 accesses"],"answer":0,"explanation":"Blocks per level: 10000 → 100 → 1; the levels shrink by a factor 100 until one block remains, giving 3 levels. A lookup reads one block per level plus the data block: 4.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-361","question":"Table Acct(no, branch, bal) rows: (101, 'Agra', 500), (102, 'Agra', 1500), (103, 'Bhopal', 700), (104, 'Bhopal', 700), (105, 'Cuttack', 2000), (106, 'Agra', NULL).\nWhat does this query return?\n```sql\nSELECT branch, COUNT(*)\nFROM Acct\nGROUP BY branch\nHAVING SUM(bal) >= 1400\nORDER BY branch;\n```","options":["(Bhopal, 2), (Cuttack, 1)","(Agra, 3), (Bhopal, 2), (Cuttack, 1)","(Agra, 3), (Cuttack, 1)","(Agra, 2), (Bhopal, 2), (Cuttack, 1)"],"answer":1,"explanation":"Agra's SUM ignores the NULL: 2000; Bhopal 1400 (≥ is inclusive); Cuttack 2000. COUNT(*) counts all of Agra's 3 rows, including the NULL balance.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-362","question":"R(A, B) = {(1, 4), (3, 4), (4, 1), (4, 3), (4, 4)} and S(B, C) = {(2, 5), (2, 7), (3, 5), (4, 6)}. How many tuples are in R ⟕ S (left outer join) and in R ⟗ S (full outer join)?","options":["4 and 5","5 and 8","5 and 7","5 and 9"],"answer":2,"explanation":"R ⋈ S has 4 tuples; 1 R tuple(s) find no partner and are padded with NULL, giving 5. The full outer join also keeps 2 unmatched S tuple(s): 7.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-363","question":"Entity sets Doctor, Patient and Drug participate in a single ternary relationship Prescribes with no cardinality constraints. Each entity set has its own key. What is the minimum number of tables, and what is the key of the Prescribes table?","options":["6 tables; one per pair of entities","3 tables; Prescribes folded into Patient","4 tables; key = (doctor key, patient key)","4 tables; key = (doctor key, patient key, drug key)"],"answer":3,"explanation":"A many-many-many ternary relationship needs its own table whose key is the combination of all three participating keys; pairwise tables would not capture which drug was prescribed by which doctor to which patient.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-364","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Staff WHERE name LIKE '_a%';\n```","options":["2","3","1","4"],"answer":0,"explanation":"'_' matches exactly one character, then 'a', then anything: Bala and Farid have 'a' as the second letter.","difficulty":"moderate","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-365","question":"For the schedule W3(A), W3(C), R2(A), R1(A), W1(B), W4(A), R2(C), W4(B), how many serial schedules of T1–T4 are conflict-equivalent to it?","options":["4","2","1","3"],"answer":1,"explanation":"Precedence edges: T1→T4, T2→T4, T3→T1, T3→T2, T3→T4. Counting the topological orders of this DAG gives 2.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-366","question":"R(A, B, C, D, E, F) has functional dependencies EF → D, A → C, BE → F, F → A, DF → A. What is the highest normal form R satisfies?","options":["BCNF","1NF but not 2NF","2NF but not 3NF","3NF but not BCNF"],"answer":2,"explanation":"Candidate keys: {BE}. No partial dependency exists, but A → C has a non-superkey left side and a non-prime right side (prime attributes: BE), so 3NF fails.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-367","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT region, COUNT(*)\nFROM Sale\nWHERE amt > 120\nGROUP BY region\nORDER BY region;\n```","options":["(N, 4), (S, 1)","(N, 4), (S, 2)","(N, 3), (S, 2)","(N, 3), (S, 1)"],"answer":3,"explanation":"WHERE removes rows before grouping: N keeps 300, 150, 200 (100 fails); S keeps only 250 (NULL fails); Lal's 120 is not > 120.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-368","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nHow many rows of this query's result show a count of 0?\n```sql\nSELECT b.name, COUNT(*)\nFROM Staff b LEFT JOIN Staff e ON e.boss = b.id\nGROUP BY b.id, b.name;\n```","options":["0","6","1","3"],"answer":0,"explanation":"COUNT(*) counts rows in each group, and an employee with no subordinates still has one LEFT-JOIN row padded with NULLs, so the minimum count is 1. COUNT(e.id) would show 0 for Dev, Esha and Farid.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-369","question":"A file has 30,000 records of 120 bytes, stored unspanned in 1024-byte blocks and ordered on key K. A primary (sparse) index on K has one entry per data block, each entry being a 9-byte key plus a 7-byte block pointer. How many block accesses does a binary search on the INDEX plus one data-block read need, in the worst case?","options":["12","7","10","6"],"answer":1,"explanation":"bfr = ⌊1024/120⌋ = 8, so 3,750 data blocks. Index bfr = ⌊1024/16⌋ = 64, so ⌈3750/64⌉ = 59 index blocks; binary search takes ⌈log₂ 59⌉ = 6 accesses, +1 for the data block = 7.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-370","question":"Classify the schedule R3(B), W1(A), R3(A), W1(B), W2(B), R2(B), C2, W3(B), R1(A), C3, C1 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Recoverable but not cascadeless","Cascadeless but not strict","Not recoverable","Strict"],"answer":2,"explanation":"A transaction reads a value written by another transaction and commits before that writer commits; if the writer then aborted, the committed reader could not be undone.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-371","question":"An ER diagram has entity sets E1, E2, E3. R1 relates E1 and E2 many-to-many. R2 relates E2 and E3 one-to-many (each E3 entity relates to at most one E2). E3 has a multivalued attribute phone. What is the minimum number of relational tables needed?","options":["6","3","4","5"],"answer":3,"explanation":"E1, E2 and E3 need a table each; M:N R1 needs its own table; R2 folds into E3 as a foreign key; the multivalued phone needs a separate table: 5.","difficulty":"hard","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-372","question":"Table Att(emp, day, status) rows: ('u', 1, 'P'), ('u', 2, 'P'), ('u', 3, 'A'), ('u', 4, 'P'), ('u', 5, 'P'), ('u', 6, 'P'), ('v', 1, 'A'), ('v', 2, 'P'), ('v', 3, 'P'), ('v', 4, 'A'), ('v', 5, 'P').\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM (\n  SELECT status,\n         LAG(status) OVER (PARTITION BY emp ORDER BY day) AS prev\n  FROM Att) x\nWHERE status <> prev;\n```","options":["5","7","4","6"],"answer":0,"explanation":"u's sequence P P A P P P changes twice (day 3 and day 4); v's A P P A P changes three times (days 2, 4, 5). Each employee's first row has prev = NULL, so status <> NULL is unknown and not counted: 5.","difficulty":"very-hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-373","question":"Table Product(pid, cat, price) rows: (1, 'X', 10), (2, 'X', 20), (3, 'Y', 20), (4, NULL, 30), (5, 'Y', NULL), (6, 'Z', 5).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Product\nWHERE price BETWEEN 10 AND 20\n   OR cat IN ('Z', NULL);\n```","options":["5","4","3","6"],"answer":1,"explanation":"BETWEEN is inclusive: pids 1, 2, 3 match. cat IN ('Z', NULL) is TRUE for pid 6 (cat = 'Z'); for other rows it is FALSE or UNKNOWN. Total 4.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-374","question":"Classify the schedule W3(B), R2(A), R3(B), W2(A), W1(B), R1(B).","options":["View serializable but not conflict serializable","Neither conflict nor view serializable","Conflict serializable (hence also view serializable)","Conflict serializable but not view serializable"],"answer":2,"explanation":"The precedence graph is acyclic (order T2 → T3 → T1), and every conflict-serializable schedule is view serializable.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-375","question":"In a B+ tree every internal node can have at most 34 children and every leaf can hold at most 30 keys. With exactly 4 levels (root at level 1, leaves at level 4), what is the maximum number of keys the tree can index?","options":["1,078,110","1,336,336","1,139,816","1,179,120"],"answer":3,"explanation":"Fully packed: 3 internal levels give 34^3 = 39,304 leaves, each with 30 keys, so 1,179,120 keys.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-376","question":"Table Stu(sid, sname) rows: (1, 'Om'), (2, 'Pia'), (3, 'Raj'), (4, 'Sia').\nTable Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat does this query return?\n```sql\nSELECT sname FROM Stu s\nWHERE NOT EXISTS (\n  SELECT cid FROM Takes p\n  WHERE p.sid = 1\n    AND NOT EXISTS (SELECT * FROM Takes t\n                    WHERE t.sid = s.sid AND t.cid = p.cid))\nORDER BY sname;\n```","options":["Om","Om, Pia, Raj","Om, Raj","Om, Pia"],"answer":0,"explanation":"This is relational division: students who took every course that student 1 (Om) took, i.e. both C1 and C2. Pia lacks C2 and Raj lacks C1, so only Om remains.","difficulty":"very-hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-377","question":"Relations R (1000 blocks) and S (500 blocks) are joined with block nested-loop join using M = 22 buffer blocks (M − 2 for the outer relation, one for the inner, one for output). What is the minimum number of block transfers, choosing the better outer relation?","options":["500500","25500","26000","23500"],"answer":1,"explanation":"With the smaller relation (500 blocks) outer: 500 + ⌈500/20⌉·1000 = 25500. Making the larger relation outer costs 26000.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-378","question":"T1: W1(A), W1(B) and T2: R2(A), R2(B). Of all 6 interleavings that keep each transaction's own order, how many are conflict serializable?","options":["6","3","4","2"],"answer":2,"explanation":"Enumerate the C(4, 2) = 6 interleavings and draw the precedence graph of each; exactly 4 have no cycle (all edges between T1 and T2 point the same way). The two serial schedules are always among them.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-379","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT COUNT(*)\nFROM Staff e LEFT JOIN Staff b ON e.boss = b.id\nWHERE b.dept = 'Ops' OR b.id IS NULL;\n```","options":["1","6","3","4"],"answer":3,"explanation":"Bala and Chitra report to Anu (Ops) and Farid to Bala (Ops); Anu has no boss, so the outer join pads b with NULLs and b.id IS NULL keeps her. Dev and Esha report to Chitra (Tech). Total 4.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-380","question":"A buffer manager uses STEAL (uncommitted pages may be written to disk) and NO-FORCE (committed pages need not be written at commit). What must the recovery scheme support?","options":["Both UNDO and REDO","Neither UNDO nor REDO","Only REDO","Only UNDO"],"answer":0,"explanation":"STEAL means uncommitted changes may be on disk, so they must be undone; NO-FORCE means committed changes may be missing from disk, so they must be redone.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-381","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT SUM(amt) OVER (ORDER BY id) AS run\nFROM Sale\nWHERE id = 4;\n```","options":["650","300","350","NULL"],"answer":1,"explanation":"WHERE is applied before the window function, so the window sees only the single row id = 4 and its running sum is 300. Evaluating the window over the full table first (650) is the trap.","difficulty":"very-hard","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-382","question":"A file of 10,000 records is physically ordered on the non-key field dept, which has 500 distinct values. A clustering index on dept has one entry per distinct value pointing to the first block containing it. How many index entries does it have?","options":["1","20","500","10,000"],"answer":2,"explanation":"A clustering index is sparse with respect to values: one entry per distinct dept value (500), not per record (dense) and not per block.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-383","question":"Which expression is equivalent to R ÷ S, where R(A, B) and S(B)?","options":["π_A(R) − π_A(R − (π_A(R) × S))","π_A(R ⋈ S)","π_A(R × S) − π_A(R)","π_A(R) − π_A((π_A(R) × S) − R)"],"answer":3,"explanation":"π_A(R) × S lists every pair each A value would need; subtracting R leaves the missing pairs, and their A values are exactly those that fail; removing them from π_A(R) gives the quotient.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-384","question":"Which is a correct reason why testing a schedule for VIEW serializability is rarely done in practice?","options":["Testing view serializability is NP-complete","It cannot handle blind writes","View serializability allows non-recoverable schedules","View-serializable schedules are always conflict serializable"],"answer":0,"explanation":"Conflict serializability is tested in polynomial time with a precedence graph, but deciding view serializability is NP-complete; it differs only for schedules with blind writes.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-385","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Sale s1 JOIN Sale s2\n  ON s1.rep = s2.rep AND s1.id < s2.id;\n```","options":["8","4","3","5"],"answer":1,"explanation":"Pairs of different sales by the same rep: Ira has 3 sales → C(3,2) = 3 pairs, Jai has 2 → 1 pair, Kim and Lal have one each. Total 4.","difficulty":"moderate","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-386","question":"Which statement about ARIES recovery is correct?","options":["Redo applies only the updates of committed transactions","The undo pass runs forward from the last checkpoint","The redo pass repeats history, redoing updates of loser transactions too, before the undo pass rolls the losers back","Compensation log records (CLRs) are undone again if a crash happens during undo"],"answer":2,"explanation":"ARIES first analyses, then redoes ALL logged updates from the redo point (repeating history), then undoes losers backwards. CLRs are redo-only, so work is never undone twice.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-387","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Staff a, Staff b\nWHERE a.pay = b.pay AND a.id < b.id;\n```","options":["8","7","2","1"],"answer":3,"explanation":"Only Chitra and Farid share a pay (70), giving one pair with a.id < b.id. Dev's NULL never equals anything, not even itself.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-388","question":"R(A, B, C, D, E, F) has functional dependencies F → ABCD, BD → A. What is the highest normal form R satisfies?","options":["1NF but not 2NF","2NF but not 3NF","3NF but not BCNF","BCNF"],"answer":0,"explanation":"Candidate keys: {EF}. F → A is a partial dependency: F is a proper subset of key EF and A is non-prime, so 2NF fails.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-389","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nHow many rows does this query return?\n```sql\nSELECT dept, COUNT(*) FROM Staff GROUP BY dept\nUNION ALL\nSELECT dept, COUNT(*) FROM Staff WHERE pay > 50 GROUP BY dept;\n```","options":["3","5","6","4"],"answer":1,"explanation":"The first query gives 3 groups (Ops, Tech, NULL). The second keeps Bala, Chitra, Farid and gives 2 groups (Ops, Tech). UNION ALL keeps all 5 rows.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-390","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT name FROM Staff s\nWHERE pay > (SELECT AVG(pay) FROM Staff t\n             WHERE t.dept = s.dept);\n```","options":["Bala, Esha","Bala, Chitra, Farid","Bala","Chitra, Farid"],"answer":2,"explanation":"Ops average = 47.5, so Bala (55) qualifies. Tech average ignores Dev's NULL: (70 + 70)/2 = 70, and nobody exceeds it. For Esha, t.dept = NULL matches nothing, the average is NULL and the comparison is unknown.","difficulty":"very-hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-391","question":"TS(T1) = 20, TS(T2) = 5, TS(T3) = 25; all read/write timestamps start at 0. Under basic timestamp ordering with Thomas's write rule, which operation of the schedule R3(B), W3(A), W2(A), R1(B), W2(B), R1(A), W1(B) is the first to make its transaction roll back?","options":["No operation is rejected","R1(A) (operation 6)","W2(A) (operation 3)","W2(B) (operation 5)"],"answer":3,"explanation":"Track read-TS and write-TS of each item. W2(B) (operation 5) is the first operation that violates the protocol (a read of a value with a newer write-TS, or a write after a newer read or write). Earlier, W2(A) (operation 3) was an obsolete write and is simply ignored under Thomas's rule instead of causing a rollback.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-392","question":"R(A, B, C, D, E, F) has functional dependencies D → BF, AE → B, F → CD, DE → C. How many prime attributes does R have?","options":["4","2","3","5"],"answer":0,"explanation":"The candidate keys are {ADE, AEF}, so the prime attributes (those in at least one candidate key) are ADEF, giving 4. Counting only one key's attributes undercounts.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-393","question":"R(A, B, C, D, E) has the set of functional dependencies Σ = {CE → D, C → AD, AE → CD}. Which of the following FDs is NOT in Σ⁺ (not implied by Σ)?","options":["AC → D","AE → B","CE → A","BC → D"],"answer":1,"explanation":"{AE}⁺ = {ACDE} does not contain B, so AE → B is not implied; each of the other three follows by computing its LHS closure (augmentation and transitivity).","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-394","question":"R(A, B, C, D) has functional dependencies D → BC, B → C, C → BD. What is the highest normal form R satisfies?","options":["1NF but not 2NF","2NF but not 3NF","3NF but not BCNF","BCNF"],"answer":2,"explanation":"Candidate keys: {AB, AC, AD}. Every non-trivial FD has a superkey LHS or a prime RHS, so it is in 3NF; but B → C has a non-superkey LHS (C is prime), so BCNF fails.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-395","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT AVG(pay), AVG(COALESCE(pay, 0))\nFROM Staff;\n```","options":["45, 45","54, 54","45, 54","54, 45"],"answer":3,"explanation":"AVG ignores the NULL pay: 270/5 = 54. COALESCE turns it into 0, so the second average is 270/6 = 45.","difficulty":"moderate","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-396","question":"R(A, B, C, D, E, F) has functional dependencies AE → BC, B → F, E → C, BD → E, F → E. Which of the following is the complete set of candidate keys of R?","options":["{ABD, ADE, ADF}","{ABD, ADE, ADF, AEF}","{ABD, ADE}","{ABD, ADE, ADEF}"],"answer":0,"explanation":"Attributes never on a right side (AD) must be in every key; extending them and testing closures gives exactly the minimal superkeys {ABD, ADE, ADF}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-397","question":"R(A, B) = {(a1, b2), (a1, b3), (a2, b1), (a2, b2), (a2, b3), (a3, b1), (a4, b1), (a4, b2), (a4, b3)} and S(B) = {b1, b3}. What is R ÷ S?","options":["{a1, a2, a3, a4}","{a2, a4}","∅","{a2}"],"answer":1,"explanation":"R ÷ S returns the A values paired with EVERY B in S (b1, b3). The answer is {a2, a4}; values paired with just some of them belong to the 'any' (semi-join) answer.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-398","question":"The system crashes after the last record of this log (immediate database modification; <Ti, X> denotes an update with old and new values; the checkpoint lists the transactions active at that moment and all dirty pages were flushed when it was taken):\n<T3 start>, <T3, A>, <T5 start>, <T5, B>, <T3 commit>, <T4 start>, <T4, C>, <checkpoint {T4, T5}>, <T2 start>, <T2, D>, <T4, E>, <T2 commit>, <T5, F>, <T1 start>, <T1, G>, <T1 commit>\nWhich transactions must be undone and which redone?","options":["Undo {T3, T4, T5}; redo {T1, T2}","Undo {T1, T2}; redo {T4, T5}","Undo {T4, T5}; redo {T1, T2}","Undo {T4, T5}; redo {T1, T2, T3}"],"answer":2,"explanation":"Transactions that committed before the checkpoint (T3) are already on disk and need nothing. Those that committed after it (T1, T2) are redone, whether they started before or after it. Those with no commit record (T4, T5) are undone, including any that were active at the checkpoint.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-399","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT rep, SUM(amt)\nFROM Sale\nGROUP BY rep\nHAVING SUM(amt) > 250\nORDER BY rep;\n```","options":["(Jai, 400)","(Ira, 300), (Jai, 400), (Kim, 300), (Lal, 120)","(Jai, 400), (Kim, 300)","(Ira, 300), (Jai, 400), (Kim, 300)"],"answer":3,"explanation":"SUM ignores Ira's NULL sale, so Ira totals 100 + 200 = 300 (not NULL). Jai 400, Kim 300, Lal 120 — three groups exceed 250.","difficulty":"moderate","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-400","question":"R(A, B, C, D, E, F) has functional dependencies B → ACDEF. What is the highest normal form R satisfies?","options":["BCNF","1NF but not 2NF","3NF but not BCNF","2NF but not 3NF"],"answer":0,"explanation":"Candidate keys: {B}. The left side of every non-trivial dependency in F+ is a superkey, so R is in BCNF.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-401","question":"Which isolation anomaly is still possible at the SQL REPEATABLE READ level (as defined by the SQL standard)?","options":["Dirty reads","Phantom reads","Dirty writes (overwriting uncommitted data)","Non-repeatable reads"],"answer":1,"explanation":"REPEATABLE READ locks/guards the rows already read, so re-reading them returns the same values; but new rows matching a predicate can still appear (phantoms). Only SERIALIZABLE rules them out.","difficulty":"moderate","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-402","question":"A B-tree (not B+ tree) stores a record pointer with every key in every node. With 2048-byte blocks, 16-byte keys, 8-byte tree pointers and 8-byte record pointers, what is the maximum number of child pointers (the order p) of a node?","options":["63","86","64","66"],"answer":2,"explanation":"A B-tree node with p children has p tree pointers and p − 1 (key, record-pointer) pairs: 8·p + 24·(p − 1) ≤ 2048, so p = ⌊2072/32⌋ = 64. Ignoring the record pointers gives the B+ internal order instead.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-403","question":"Table P(x) rows: (1), (2), (2), (3), (NULL).\nTable Q(x) rows: (2), (3), (3), (NULL), (4).\nWhat does this query return?\n```sql\nSELECT (SELECT COUNT(*) FROM (SELECT x FROM P UNION SELECT x FROM Q)),\n       (SELECT COUNT(*) FROM (SELECT x FROM P INTERSECT SELECT x FROM Q)),\n       (SELECT COUNT(*) FROM (SELECT x FROM P EXCEPT SELECT x FROM Q));\n```","options":["4, 2, 1","5, 2, 2","10, 3, 1","5, 3, 1"],"answer":3,"explanation":"Set operations remove duplicates and treat NULLs as identical. UNION = {1, 2, 3, 4, NULL} (5); INTERSECT = {2, 3, NULL} (3); EXCEPT = {1} (1).","difficulty":"very-hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-404","question":"R(A, B) = {(1, 4), (2, 4), (3, 3), (4, 1), (4, 3)} and S(B, C) = {(1, 6), (2, 5), (2, 6), (3, 5), (4, 5)}. How many tuples are in π_A(R ⋈ S) and in R ⋈ S respectively (set semantics)?","options":["4 and 5","4 and 6","4 and 25","5 and 5"],"answer":0,"explanation":"R ⋈ S pairs each R tuple with every S tuple having the same B: 5 tuples. Projecting on A removes duplicates, leaving {1, 2, 3, 4}.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-405","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT e.name\nFROM Staff e JOIN Staff b ON e.boss = b.id\nWHERE e.pay > b.pay\nORDER BY e.name;\n```","options":["Chitra, Farid","Bala, Chitra, Farid","Bala, Chitra","Bala, Chitra, Dev, Farid"],"answer":1,"explanation":"Compare each employee with their boss: Bala 55 > Anu 40, Chitra 70 > 40, Farid 70 > Bala 55. Dev's pay is NULL (comparison unknown) and Esha 35 < Chitra 70.","difficulty":"hard","source":"GATE CS · SQL"},
  {"id":"cs-dbms-sql-406","question":"R(A, B, C, D, E) has functional dependencies B → AC, C → B, AC → B, A → B. How many prime attributes does R have?","options":["4","2","5","3"],"answer":2,"explanation":"The candidate keys are {ADE, BDE, CDE}, so the prime attributes (those in at least one candidate key) are ABCDE, giving 5. Counting only one key's attributes undercounts.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-407","question":"Table Stu(sid, sname) rows: (1, 'Om'), (2, 'Pia'), (3, 'Raj'), (4, 'Sia').\nTable Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nTable Course(cid, credits) rows: ('C1', 4), ('C2', 3), ('C3', 2), ('C4', 3).\nWhat does this query return?\n```sql\nSELECT s.sname, SUM(c.credits)\nFROM Stu s JOIN Takes t ON s.sid = t.sid\n          JOIN Course c ON c.cid = t.cid\nGROUP BY s.sid, s.sname\nORDER BY s.sid;\n```","options":["(Om, 7), (Pia, 4), (Raj, 3)","(Om, 7), (Pia, 4), (Raj, 5), (Sia, 0)","(Om, 4), (Pia, 4), (Raj, 5)","(Om, 7), (Pia, 4), (Raj, 5)"],"answer":3,"explanation":"Om took C1 (4) and C2 (3) = 7 — his NULL marks don't matter to credits; Pia C1 = 4; Raj C2 + C3 = 5. Sia has no Takes row and an inner join drops her.","difficulty":"hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-408","question":"A B+ tree index uses 4096-byte blocks, 20-byte search keys, 12-byte block (tree) pointers and 14-byte record pointers. What is the maximum number of CHILD pointers an internal node can hold?","options":["128","129","120","127"],"answer":0,"explanation":"An internal node with p children holds p block pointers and p − 1 keys: 12·p + 20·(p − 1) ≤ 4096 gives p = ⌊(4096 + 20)/(20 + 12)⌋ = 128.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-409","question":"For the schedule W1(C), W2(C), R2(B), R3(A), W4(C), R4(C), R3(B), R1(B), how many serial schedules of T1–T4 are conflict-equivalent to it?","options":["8","4","5","3"],"answer":1,"explanation":"Precedence edges: T1→T2, T1→T4, T2→T4. Counting the topological orders of this DAG gives 4.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-410","question":"Extendible hashing uses the LOWEST-order bits of a key's binary value, bucket capacity 2, and starts with global depth 0 and one empty bucket. A full bucket splits on its next bit; the directory doubles only when the splitting bucket's local depth equals the global depth (repeat splits if needed). After inserting 52, 3, 50, 35, 1, 32, 22 in this order, what are the global depth and the number of distinct buckets?","options":["Global depth 3, 4 buckets","Global depth 1, 4 buckets","Global depth 2, 4 buckets","Global depth 2, 5 buckets"],"answer":2,"explanation":"Tracing the low-order bits: the directory grows to 2^2 = 4 entries, but buckets that never split stay shared by several entries, so only 4 distinct buckets exist.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-411","question":"R(A, B, C, D, E) has functional dependencies C → E, AC → DE, E → D, BC → DE, AD → CE. How many prime attributes does R have?","options":["4","2","3","5"],"answer":3,"explanation":"The candidate keys are {ABC, ABD, ABE}, so the prime attributes (those in at least one candidate key) are ABCDE, giving 5. Counting only one key's attributes undercounts.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-412","question":"In a wait-for graph, T1 waits for T2, T2 waits for T3, T3 waits for T4 and T4 waits for T2. T5 waits for T1. Which transactions are deadlocked (part of a cycle)?","options":["T2, T3 and T4 only","None — a deadlock needs exactly two transactions","All five transactions","T1, T2, T3 and T4"],"answer":0,"explanation":"The only cycle is T2 → T3 → T4 → T2. T1 and T5 are blocked behind it but not in the cycle; aborting a cycle member (say T4) frees them.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-413","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nHow many rows does this query return?\n```sql\nSELECT name FROM Staff\nWHERE pay > 50 OR pay <= 50;\n```","options":["4","5","6","0"],"answer":1,"explanation":"For Dev both comparisons are UNKNOWN and UNKNOWN OR UNKNOWN is UNKNOWN, so his row is dropped even though the condition looks like a tautology: 5 rows.","difficulty":"moderate","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-414","question":"R(A, B) = {(a1, b1), (a1, b2), (a2, b1), (a2, b3), (a3, b1), (a3, b2), (a3, b3), (a4, b1), (a4, b2)} and S(B) = {b2, b3}. What is R ÷ S?","options":["∅","{a1, a2, a4}","{a3}","{a1, a2, a3, a4}"],"answer":2,"explanation":"R ÷ S returns the A values paired with EVERY B in S (b2, b3). The answer is {a3}; values paired with just some of them belong to the 'any' (semi-join) answer.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-415","question":"Σ = {DE → C, AB → CE, D → ABE}. Consider the FD DE → C while computing a canonical cover. Which statement about extraneous attributes on its left side is correct?","options":["Neither D nor E is extraneous","Only D is extraneous","Either D or E (but not both) can be dropped","Only E is extraneous"],"answer":3,"explanation":"Test each attribute: D is extraneous iff {E}⁺ (under Σ) contains C; {E}⁺ = {E} and {D}⁺ = {ABCDE}.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-416","question":"R(A, B, C, D, E) has functional dependencies A → D, CE → AB, AB → C, C → AB. How many prime attributes does R have?","options":["4","1","2","3"],"answer":0,"explanation":"The candidate keys are {CE, ABE}, so the prime attributes (those in at least one candidate key) are ABCE, giving 4. Counting only one key's attributes undercounts.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-417","question":"Classify the schedule W1(A), W3(A), R3(A), R3(B), R1(A), R2(A), R2(B).","options":["Conflict serializable (hence also view serializable)","Neither conflict nor view serializable","Conflict serializable but not view serializable","View serializable but not conflict serializable"],"answer":1,"explanation":"The precedence graph has a cycle, and no serial order reproduces the same reads-from pairs and final writes, so it is not even view serializable.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-418","question":"R(A, B, C, D, E) has functional dependencies BD → A, E → B, B → E, AD → B. Which of the following is the complete set of candidate keys of R?","options":["{ABD, ACD, BCD, CDE}","{ACD, BCD, ACDE}","{ACD, BCD, CDE}","{ACD, BCD}"],"answer":2,"explanation":"Attributes never on a right side (CD) must be in every key; extending them and testing closures gives exactly the minimal superkeys {ACD, BCD, CDE}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-419","question":"Relations R (600 blocks) and S (90 blocks) are joined with block nested-loop join using M = 32 buffer blocks (M − 2 for the outer relation, one for the inner, one for output). What is the minimum number of block transfers, choosing the better outer relation?","options":["54090","2400","54000","1890"],"answer":3,"explanation":"With the smaller relation (90 blocks) outer: 90 + ⌈90/30⌉·600 = 1890. Making the larger relation outer costs 2400.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-420","question":"Table Score(name, pts) rows: ('a', 90), ('b', 85), ('c', 90), ('d', 70), ('e', 85), ('f', 60).\nWhat does this query return?\n```sql\nSELECT RANK() OVER (ORDER BY pts DESC),\n       DENSE_RANK() OVER (ORDER BY pts DESC)\nFROM Score\nWHERE name = 'f';\n```","options":["1, 1","6, 5","5, 3","6, 4"],"answer":0,"explanation":"The window is computed after WHERE, so only f's row is left and both functions give 1. Without the WHERE, f would be RANK 6, DENSE_RANK 4.","difficulty":"very-hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-421","question":"How many of these statements are correct?\n1. A table can have at most one clustering index.\n2. A primary index on an ordering key field is usually sparse.\n3. A secondary index on a non-ordering key field must be dense.\n4. A hash index efficiently supports range queries like price BETWEEN 10 AND 20.","options":["2","3","1","4"],"answer":1,"explanation":"1–3 are true: data can be physically ordered only one way; a primary index needs one entry per block; a secondary index needs one entry per record because records are not ordered on it. Hashing scatters neighbouring keys, so 4 is false.","difficulty":"moderate","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-422","question":"R(A, B, C, D) has functional dependencies B → C, A → BD, AC → D, C → AB. What is the highest normal form R satisfies?","options":["2NF but not 3NF","1NF but not 2NF","BCNF","3NF but not BCNF"],"answer":2,"explanation":"Candidate keys: {A, B, C}. The left side of every non-trivial dependency in F+ is a superkey, so R is in BCNF.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft placement"},
  {"id":"cs-dbms-sql-423","question":"R(A, B, C, D, E, F) has functional dependencies CD → F, EF → D, F → D, AB → E. Which of the following is the complete set of candidate keys of R?","options":["{ABCD, ABCF, ACDF}","{ABCD}","{ABCD, ABCDE}","{ABCD, ABCF}"],"answer":3,"explanation":"Attributes never on a right side (ABC) must be in every key; extending them and testing closures gives exactly the minimal superkeys {ABCD, ABCF}. Each closure covers all of R and no proper subset does, so these are all the candidate keys.","difficulty":"very-hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-424","question":"Table P(x) rows: (1), (2), (2), (3), (NULL).\nTable Q(x) rows: (2), (3), (3), (NULL), (4).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM P\nWHERE x NOT IN (SELECT x FROM Q);\n```","options":["0","2","3","1"],"answer":0,"explanation":"Q contains a NULL, so for every P value x NOT IN Q is either FALSE (x found) or UNKNOWN (x compared with NULL). No row is TRUE, so the count is 0.","difficulty":"hard","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-425","question":"On R(A, B, C, D, E), F = {AE → D, A → CD, B → A} and G = {B → ACD, A → CD}. Which statement is correct? (\"F covers G\" means every FD of G is in F⁺.)","options":["F covers G, but G does not cover F","F and G are equivalent","G covers F, but F does not cover G","Neither covers the other"],"answer":1,"explanation":"Check each FD of one set by its LHS closure under the other set. F covers G: yes; G covers F: yes.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-426","question":"R(A, B, C, D, E, F) has functional dependencies BF → A, D → E, AC → F, BD → A, A → B. Which of these attribute sets is NOT a superkey of R?","options":["BCD","ACDF","BDF","ABCD"],"answer":2,"explanation":"{BDF}⁺ = {ABDEF}, which misses C, so it is not a superkey. Each other option's closure is all of R (each contains one of the candidate keys ACD, BCD).","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-427","question":"R(A, B, C, D, E) has functional dependencies A → BCE, C → AD, B → DE. What is the closure {B}⁺?","options":["{ABCDE}","{ABDE}","{BD}","{BDE}"],"answer":3,"explanation":"Keep applying any FD whose left side is already inside the set until nothing changes; one pass in listed order is not enough. The result is {BDE}.","difficulty":"moderate","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-428","question":"R(A, B) = {(a1, b1), (a1, b2), (a2, b2), (a2, b3), (a3, b1), (a3, b2), (a4, b1), (a4, b2), (a4, b3)} and S(B) = {b1, b3}. What is R ÷ S?","options":["{a4}","{a1, a2, a3}","{a1, a2, a3, a4}","∅"],"answer":0,"explanation":"R ÷ S returns the A values paired with EVERY B in S (b1, b3). The answer is {a4}; values paired with just some of them belong to the 'any' (semi-join) answer.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-429","question":"What is the maximum possible number of candidate keys a relation with 6 attributes can have (over all FD sets)?","options":["63","20","6","15"],"answer":1,"explanation":"Candidate keys form an antichain (no key contains another), and by Sperner's theorem the largest antichain of subsets of a 6-set has C(6, 3) = 20 sets — achieved when every 3-attribute set is a key.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-430","question":"R(A, B, C, D, E) with functional dependencies BC → A, D → B, A → D is decomposed into R1(A, C, E), R2(A, B, D). Which statement is correct?","options":["Lossless join and dependency preserving","Neither lossless join nor dependency preserving","Lossless join but not dependency preserving","Dependency preserving but not lossless join"],"answer":2,"explanation":"The chase (tableau) test produces an all-distinguished row, so the join is lossless. BC → A cannot be derived from the projected FDs, so a dependency is lost.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-431","question":"Relations R (400 blocks) and S (100 blocks) are joined with block nested-loop join using M = 12 buffer blocks (M − 2 for the outer relation, one for the inner, one for output). What is the minimum number of block transfers, choosing the better outer relation?","options":["4400","40100","3700","4100"],"answer":3,"explanation":"With the smaller relation (100 blocks) outer: 100 + ⌈100/10⌉·400 = 4100. Making the larger relation outer costs 4400.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-432","question":"Table Stu(sid, sname) rows: (1, 'Om'), (2, 'Pia'), (3, 'Raj'), (4, 'Sia').\nTable Takes(sid, cid, marks) rows: (1, 'C1', 80), (1, 'C2', NULL), (2, 'C1', 65), (3, 'C2', 90), (3, 'C3', 75), (5, 'C1', 50).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Stu NATURAL JOIN Takes;\n```","options":["5","6","4","24"],"answer":0,"explanation":"NATURAL JOIN matches on sid. Om has 2 rows, Pia 1, Raj 2, Sia 0; Takes' sid 5 has no student. Total 5.","difficulty":"moderate","source":"Amazon/Flipkart SQL round · GATE CS"},
  {"id":"cs-dbms-sql-433","question":"Table Sale(id, rep, region, amt) rows: (1, 'Ira', 'N', 100), (2, 'Jai', 'S', 250), (3, 'Ira', 'S', NULL), (4, 'Kim', 'N', 300), (5, 'Jai', 'N', 150), (6, 'Ira', 'N', 200), (7, 'Lal', NULL, 120).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Sale\nWHERE region NOT IN ('S', NULL);\n```","options":["5","0","6","4"],"answer":1,"explanation":"region NOT IN ('S', NULL) means region <> 'S' AND region <> NULL; the second comparison is always UNKNOWN, so no row can be TRUE.","difficulty":"hard","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-434","question":"TS(T1) = 15, TS(T2) = 30, TS(T3) = 25; all read/write timestamps start at 0. Under basic timestamp ordering with Thomas's write rule, which operation of the schedule W3(A), R1(B), W1(A), R3(A), R2(B), R1(A), W2(A) is the first to make its transaction roll back?","options":["R3(A) (operation 4)","W1(A) (operation 3)","R1(A) (operation 6)","No operation is rejected"],"answer":2,"explanation":"Track read-TS and write-TS of each item. R1(A) (operation 6) is the first operation that violates the protocol (a read of a value with a newer write-TS, or a write after a newer read or write). Earlier, W1(A) (operation 3) was an obsolete write and is simply ignored under Thomas's rule instead of causing a rollback.","difficulty":"very-hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-435","question":"Table Att(emp, day, status) rows: ('u', 1, 'P'), ('u', 2, 'P'), ('u', 3, 'A'), ('u', 4, 'P'), ('u', 5, 'P'), ('u', 6, 'P'), ('v', 1, 'A'), ('v', 2, 'P'), ('v', 3, 'P'), ('v', 4, 'A'), ('v', 5, 'P').\nWhat does this query return?\n```sql\nSELECT emp, COUNT(*)\nFROM Att a\nWHERE status = 'P'\n  AND NOT EXISTS (SELECT * FROM Att b\n                  WHERE b.emp = a.emp AND b.day = a.day - 1\n                    AND b.status = 'P')\nGROUP BY emp\nORDER BY emp;\n```","options":["(u, 5), (v, 3)","(u, 1), (v, 1)","(u, 2), (v, 1)","(u, 2), (v, 2)"],"answer":3,"explanation":"A present day with no present day immediately before it starts a streak. u: days 1 and 4 start streaks; v: days 2 and 5. So each has 2 streaks of presence.","difficulty":"very-hard","source":"TCS Digital · Infosys SP · GATE CS"},
  {"id":"cs-dbms-sql-436","question":"Which of the following is NOT one of the anomalies that normalisation into BCNF is meant to remove?","options":["Phantom reads during concurrent transactions","Deletion anomaly: deleting one fact loses another","Insertion anomaly: a fact cannot be stored without an unrelated fact","Update anomaly: one fact stored in many rows"],"answer":0,"explanation":"Normalisation removes redundancy-driven update, insertion and deletion anomalies. Phantom reads are a concurrency-control issue, solved by isolation levels or predicate locks.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-437","question":"Under the write-ahead logging (WAL) rule, which ordering must hold?","options":["Log records are written only at checkpoints","An update's log record reaches stable storage before the modified data page, and all of a transaction's log records reach it before its commit completes","Only the commit record must be flushed; update records may be written later","The data page must reach disk before its log record"],"answer":1,"explanation":"The first half guarantees undo information exists for any change on disk; the second guarantees redo information exists for every committed transaction.","difficulty":"moderate","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-438","question":"A B+ tree index uses 2048-byte blocks, 14-byte search keys, 8-byte block (tree) pointers and 10-byte record pointers. What is the maximum number of CHILD pointers an internal node can hold?","options":["94","92","93","85"],"answer":2,"explanation":"An internal node with p children holds p block pointers and p − 1 keys: 8·p + 14·(p − 1) ≤ 2048 gives p = ⌊(2048 + 14)/(14 + 8)⌋ = 93.","difficulty":"hard","source":"GATE CS · PSU (ISRO/BARC)"},
  {"id":"cs-dbms-sql-439","question":"Table Staff(id, name, dept, pay, boss) rows: (1, 'Anu', 'Ops', 40, NULL), (2, 'Bala', 'Ops', 55, 1), (3, 'Chitra', 'Tech', 70, 1), (4, 'Dev', 'Tech', NULL, 3), (5, 'Esha', NULL, 35, 3), (6, 'Farid', 'Tech', 70, 2).\nWhat does this query return?\n```sql\nSELECT name FROM Staff\nWHERE id NOT IN (SELECT boss FROM Staff);\n```","options":["Anu, Dev, Esha, Farid","Dev, Esha, Farid","Anu","No rows (empty result)"],"answer":3,"explanation":"The subquery returns a NULL (Anu has no boss). x NOT IN (..., NULL) is never TRUE — it is FALSE or UNKNOWN — so no row qualifies. NOT EXISTS would give Dev, Esha, Farid.","difficulty":"hard","source":"Product placement · SQL round"},
  {"id":"cs-dbms-sql-440","question":"R(A, B, C, D, E, F) has the set of functional dependencies Σ = {E → ABF, F → BE, C → F, B → C}. Which of the following FDs is NOT in Σ⁺ (not implied by Σ)?","options":["B → D","F → A","DF → A","AE → C"],"answer":0,"explanation":"{B}⁺ = {ABCEF} does not contain D, so B → D is not implied; each of the other three follows by computing its LHS closure (augmentation and transitivity).","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-441","question":"R(A, B, C, D, E, F) has functional dependencies C → AD, A → D, D → C. What is the highest normal form R satisfies?","options":["BCNF","3NF but not BCNF","2NF but not 3NF","1NF but not 2NF"],"answer":1,"explanation":"Candidate keys: {ABEF, BCEF, BDEF}. Every non-trivial FD has a superkey LHS or a prime RHS, so it is in 3NF; but A → C has a non-superkey LHS (C is prime), so BCNF fails.","difficulty":"very-hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-442","question":"Consider the schedule R2(B), R2(C), W3(A), W1(B), R1(C), W1(C), R3(B). Which statement is correct?","options":["It is not conflict serializable","Conflict serializable, equivalent only to T1 → T3 → T2","Conflict serializable, equivalent only to T2 → T1 → T3","Conflict serializable, equivalent only to T3 → T2 → T1"],"answer":2,"explanation":"Conflict edges: T1→T3, T2→T1. The graph is acyclic and its only topological order is T2 → T1 → T3.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-443","question":"A multilevel index is built over a first level of 90,000 index entries; every index block holds 45 entries (fan-out 45), and levels are added until the top level fits in one block. How many index levels are there in total, and how many block accesses does a lookup take including one data-block read?","options":["3 levels, 3 accesses","4 levels, 5 accesses","2 levels, 3 accesses","3 levels, 4 accesses"],"answer":3,"explanation":"Blocks per level: 2000 → 45 → 1; the levels shrink by a factor 45 until one block remains, giving 3 levels. A lookup reads one block per level plus the data block: 4.","difficulty":"hard","source":"GATE CS · DBMS"},
  {"id":"cs-dbms-sql-444","question":"Which statement about the expressive power of query languages is correct?","options":["Relational algebra, safe tuple calculus and safe domain calculus are equally expressive, while SQL with aggregation and recursion can express more","Relational algebra can compute the transitive closure of any relation","Domain calculus can express aggregates that algebra cannot","Relational algebra is strictly more expressive than safe tuple calculus"],"answer":0,"explanation":"Codd's theorem makes RA and safe relational calculus equivalent ('relationally complete'). Transitive closure and aggregates are beyond them, which is why SQL adds GROUP BY and WITH RECURSIVE.","difficulty":"hard","source":"GATE CS · Product placement"},
  {"id":"cs-dbms-sql-445","question":"R is decomposed into R1 and R2. Which condition guarantees the decomposition is lossless?","options":["R1 ∪ R2 = R and both are in BCNF","(R1 ∩ R2) → R1 or (R1 ∩ R2) → R2 is in F⁺","R1 ∩ R2 is non-empty","(R1 ∩ R2) → R1 and (R1 ∩ R2) → R2 are both in F⁺"],"answer":1,"explanation":"A binary decomposition is lossless exactly when the common attributes form a superkey of at least one side. A non-empty intersection is not enough, and requiring both sides is stronger than needed.","difficulty":"moderate","source":"Product placement · DBMS interview"},
  {"id":"cs-dbms-sql-446","question":"Table T(x) has rows (1), (2), (3) and table U(y) has rows (2), (NULL). What do these two queries return?\nQ1: SELECT COUNT(*) FROM T WHERE x NOT IN (SELECT y FROM U);\nQ2: SELECT COUNT(*) FROM T WHERE NOT EXISTS (SELECT 1 FROM U WHERE U.y = T.x);","options":["Q1 = 2, Q2 = 2","Q1 = 0, Q2 = 2","Q1 = 0, Q2 = 0","Q1 = 2, Q2 = 0"],"answer":1,"explanation":"x NOT IN (2, NULL) means x <> 2 AND x <> NULL; the second part is UNKNOWN, so no row qualifies and Q1 = 0. NOT EXISTS only asks whether a matching row exists, so 1 and 3 qualify and Q2 = 2.","difficulty":"hard","source":"GATE CS · Product-company placement"},
  {"id":"cs-dbms-sql-447","question":"Cust(cid, city) has rows (1, 'Pune'), (2, 'Delhi'), (3, NULL), (4, 'Pune'). Ord(oid, cid, amt) has rows (10, 1, 500), (11, 1, NULL), (12, 2, 300), (13, NULL, 200), (14, 5, 100). How many rows do these queries return?\nQ1: SELECT * FROM Cust c LEFT JOIN Ord o ON c.cid = o.cid AND o.amt > 250;\nQ2: SELECT * FROM Cust c LEFT JOIN Ord o ON c.cid = o.cid WHERE o.amt > 250;","options":["Q1 = 4, Q2 = 2","Q1 = 2, Q2 = 2","Q1 = 5, Q2 = 2","Q1 = 4, Q2 = 4"],"answer":0,"explanation":"In Q1 the amount test is part of the join, so every customer survives: 1 pairs with order 10, 2 with 12, and 3 and 4 get NULLs (4 rows). In Q2 the WHERE runs after the join and drops every row whose o.amt is NULL or small, leaving 2: a WHERE on the right table turns the outer join into an inner join.","difficulty":"hard","source":"Product-company placement · GATE CS"},
  {"id":"cs-dbms-sql-448","question":"Ord(oid, cid, amt) has rows (10, 1, 500), (11, 1, NULL), (12, 2, 300), (13, NULL, 200), (14, 5, 100). What does SELECT COUNT(*), COUNT(DISTINCT cid), AVG(amt) FROM Ord; return?","options":["5, 4, 275","4, 3, 275","5, 3, 220","5, 3, 275"],"answer":3,"explanation":"COUNT(*) counts all 5 rows. COUNT(DISTINCT cid) ignores the NULL, giving {1, 2, 5} = 3. AVG ignores the NULL amount: 1100 / 4 = 275, not 1100 / 5 = 220.","difficulty":"moderate","source":"TCS NQT · Infosys · Product-company placement"},
  {"id":"cs-dbms-sql-449","question":"Player(pid, team, runs) has rows (1, 'A', 50), (2, 'A', 70), (3, 'A', 70), (4, 'B', 40), (5, 'B', NULL), (6, 'B', 90), (7, 'C', NULL). For player 1, what are RANK() OVER (ORDER BY runs DESC NULLS LAST) and DENSE_RANK() OVER (ORDER BY runs DESC NULLS LAST)?","options":["3 and 3","4 and 4","4 and 3","3 and 2"],"answer":2,"explanation":"Ordered: 90, 70, 70, 50, 40, NULL, NULL. RANK leaves a gap after the tie (1, 2, 2, 4) so 50 gets 4; DENSE_RANK has no gaps (1, 2, 2, 3) so 50 gets 3. 3 and 2 counts the higher rows but forgets to add 1.","difficulty":"moderate","source":"Product-company placement"},
  {"id":"cs-dbms-sql-450","question":"Pay(d, amt) has rows (1, 10), (2, 20), (2, 30), (3, 40). For the row (2, 20), what value does SUM(amt) OVER (ORDER BY d) give?","options":["30","60","20","100"],"answer":1,"explanation":"With ORDER BY and no frame clause the default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, which includes all peers with the same d. Both d = 2 rows get 10 + 20 + 30 = 60; 30 is what a ROWS frame would give.","difficulty":"very-hard","source":"Product-company placement"},
  {"id":"cs-dbms-sql-451","question":"What does this query return?\nSELECT CASE NULL WHEN NULL THEN 'eq' ELSE 'ne' END, CASE WHEN NULL IS NULL THEN 'eq' ELSE 'ne' END;","options":["'eq', 'eq'","'ne', 'eq'","'ne', 'ne'","NULL, 'eq'"],"answer":1,"explanation":"A simple CASE compares with =, and NULL = NULL is UNKNOWN, so the ELSE branch gives 'ne'. The searched CASE uses IS NULL, which is TRUE, so it gives 'eq'. A CASE with an ELSE never returns NULL just because nothing matched.","difficulty":"hard","source":"Product-company placement"},
  {"id":"cs-dbms-sql-452","question":"Skill(emp, sk) has rows (r, sql), (r, py), (r, go), (s, sql), (s, py), (t, sql), (t, go), (t, py), (t, c). Req(sk) has rows (sql), (py), (go). Which employees does this query return?\nSELECT DISTINCT emp FROM Skill s WHERE NOT EXISTS (SELECT * FROM Req r WHERE NOT EXISTS (SELECT * FROM Skill s2 WHERE s2.emp = s.emp AND s2.sk = r.sk));","options":["r only","t only","r and t","r, s and t"],"answer":2,"explanation":"The double NOT EXISTS is relational division: keep an employee if no required skill is missing. r and t have all of sql, py and go (t's extra skill c does not matter); s lacks go.","difficulty":"hard","source":"GATE CS · Product-company placement"},
  {"id":"cs-dbms-sql-453","question":"Emp(eid, name, mgr, sal) has rows (1, Kiran, NULL, 100), (2, Lata, 1, 80), (3, Mohan, 1, 120), (4, Neha, 2, 90), (5, Om, 4, 60), (6, Pari, 3, 130). Which names does this return?\nSELECT e.name FROM Emp e WHERE e.sal > (SELECT m.sal FROM Emp m WHERE m.eid = e.mgr);","options":["Mohan and Pari","Kiran, Mohan, Neha and Pari","Mohan only","Mohan, Neha and Pari"],"answer":3,"explanation":"Mohan 120 > Kiran 100, Neha 90 > Lata 80 and Pari 130 > Mohan 120; Om 60 < Neha 90. For Kiran the subquery is empty, giving NULL, and 100 > NULL is UNKNOWN, so Kiran is not returned.","difficulty":"moderate","source":"TCS NQT · Product-company placement"},
  {"id":"cs-dbms-sql-454","question":"Using Emp(eid, name, mgr, sal) with rows (1, Kiran, NULL, 100), (2, Lata, 1, 80), (3, Mohan, 1, 120), (4, Neha, 2, 90), (5, Om, 4, 60), (6, Pari, 3, 130), what does this return?\nWITH RECURSIVE sub(eid, lvl) AS (SELECT eid, 0 FROM Emp WHERE eid = 1 UNION ALL SELECT e.eid, lvl + 1 FROM Emp e JOIN sub ON e.mgr = sub.eid) SELECT COUNT(*), SUM(lvl) FROM sub;","options":["6, 9","5, 9","3, 2","6, 7"],"answer":0,"explanation":"Levels: Kiran 0; Lata and Mohan 1; Neha and Pari 2; Om (Neha's report) 3. That is 6 rows and 0 + 1 + 1 + 2 + 2 + 3 = 9. The recursion repeats until no new rows appear, so it does not stop at one level (3, 2), and the anchor row is counted.","difficulty":"hard","source":"Product-company placement"},
  {"id":"cs-dbms-sql-455","question":"Fee(sid, fee) has rows (1, 500), (2, 700), (3, 700), (4, 400), (5, 900), (6, 400). What does this return?\nSELECT SUM(fee) FROM Fee f WHERE 3 > (SELECT COUNT(DISTINCT fee) FROM Fee f2 WHERE f2.fee > f.fee);","options":["2300","2100","2800","3600"],"answer":2,"explanation":"A row qualifies if fewer than 3 distinct fees are higher: 900 (0 higher), both 700s (1) and 500 (2) qualify, the 400s (3) do not. Sum = 900 + 700 + 700 + 500 = 2800. 2300 is what COUNT(*) instead of COUNT(DISTINCT) gives, and 2100 adds each distinct value once.","difficulty":"very-hard","source":"Product-company placement · GATE CS"},
  {"id":"cs-dbms-sql-456","question":"Player(pid, team, runs) has rows (1, 'A', 50), (2, 'A', 70), (3, 'A', 70), (4, 'B', 40), (5, 'B', NULL), (6, 'B', 90), (7, 'C', NULL). What does this return?\nSELECT team, MAX(runs) FROM Player GROUP BY team HAVING COUNT(runs) < COUNT(*);","options":["Two rows: (B, 90) and (C, NULL)","One row: (B, 90)","Two rows: (B, NULL) and (C, NULL)","No rows"],"answer":0,"explanation":"COUNT(runs) skips NULLs, so the condition picks teams with at least one NULL: B (2 < 3) and C (0 < 1). MAX ignores NULLs, giving 90 for B and NULL for C, whose only value is NULL.","difficulty":"hard","source":"Product-company placement"},
  {"id":"cs-dbms-sql-457","question":"Cust(cid, city) has rows (1, 'Pune'), (2, 'Delhi'), (3, NULL), (4, 'Pune'). What are the values of\nQ1: SELECT COUNT(*) FROM (SELECT city FROM Cust UNION SELECT city FROM Cust) t;\nQ2: SELECT COUNT(DISTINCT city) FROM Cust;","options":["Q1 = 2, Q2 = 2","Q1 = 4, Q2 = 2","Q1 = 3, Q2 = 3","Q1 = 3, Q2 = 2"],"answer":3,"explanation":"UNION removes duplicates and treats NULLs as duplicates of each other, leaving Pune, Delhi and NULL: 3 rows. COUNT(DISTINCT city) ignores NULL entirely, so it gives 2.","difficulty":"hard","source":"Product-company placement"},
  {"id":"cs-dbms-sql-458","question":"Ord(oid, cid, amt) has no row with cid = 99. What do these return?\nQ1: SELECT SUM(amt), COUNT(*) FROM Ord WHERE cid = 99;\nQ2: SELECT cid, COUNT(*) FROM Ord WHERE cid = 99 GROUP BY cid;","options":["Q1: one row (NULL, 0); Q2: no rows","Q1: one row (0, 0); Q2: one row (99, 0)","Q1: no rows; Q2: no rows","Q1: one row (NULL, 0); Q2: one row (99, 0)"],"answer":0,"explanation":"An aggregate without GROUP BY always yields exactly one row: SUM of nothing is NULL and COUNT(*) is 0. With GROUP BY, there are no groups at all, so Q2 returns no rows.","difficulty":"very-hard","source":"Product-company placement"},
  {"id":"cs-dbms-sql-459","question":"R(A, B, C, D, E, F) has functional dependencies AB → C, C → D, D → E, E → A and F → B. How many superkeys does R have?","options":["32","30","31","15"],"answer":1,"explanation":"F and B never appear on the right except F → B, so every key needs F (which gives B) plus one of A, C, D, E. A superkey is F, any subset of {A, C, D, E} that is non-empty, and B optional: 15 × 2 = 30. 31 wrongly counts BF, and 15 forgets B is free.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-460","question":"R(A, B, C, D, E, F) has functional dependencies A → BC, CD → E, E → A and B → F. It is decomposed into R1(A, B, C, F) and R2(A, C, D, E). Which statement is correct?","options":["It is lossy, because the common attributes A, C are not a key of R2","It is lossless and dependency-preserving; R1 is in 2NF but not 3NF, and R2 is in 3NF but not BCNF","It is lossless but not dependency-preserving, because B → F is lost","It is lossless and dependency-preserving, and both R1 and R2 are in BCNF"],"answer":1,"explanation":"A⁺ = ABCF, so the common part A, C is a key of R1 and the join is lossless; every FD lies inside R1 or R2. R1 has key A and the transitive B → F, so it is 2NF only. R2 has keys AD, CD and DE; E → A violates BCNF, but A is prime, so R2 is in 3NF.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-461","question":"R(A, B, C, D, E) has functional dependencies A → C, B → D and CD → E. It is decomposed into R1(A, C), R2(B, D) and R3(A, B, E). Is the decomposition lossless?","options":["No, because R1 and R2 share no attribute","No, because CD → E is not preserved, so information is lost","Yes, because joining R1 and R2 first gives a key of R","Yes: in the chase, R3's row gets C from A → C and D from B → D, becoming all-known"],"answer":3,"explanation":"Lossless-join is tested on the whole decomposition: R3's row matches R1's on A and R2's on B, so it gains C and D, and with E already present becomes a full row. Order of joining does not matter, and dependency preservation is a separate property.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-462","question":"R(A, B, C, D, E) has functional dependencies AB → CDE, C → A and D → E. What is the highest normal form R satisfies?","options":["BCNF","3NF","2NF","1NF"],"answer":2,"explanation":"Candidate keys are AB and BC, so A, B and C are prime. C → A is allowed in 3NF because A is prime. But D → E has a non-key left side and non-prime right side, a transitive dependency, so R is not in 3NF; there is no partial dependency of a non-prime attribute on part of a key, so it is in 2NF.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-463","question":"R(A, B, C, D, E) has functional dependencies BC → A, A → B, D → E and E → D. How many candidate keys does R have, and what is its highest normal form?","options":["2 keys; 2NF","4 keys; BCNF","4 keys; 3NF","2 keys; 3NF"],"answer":2,"explanation":"C is in every key, plus one of A or B (A → B, BC → A) and one of D or E: ACD, ACE, BCD, BCE. Every attribute is prime, so R is in 3NF, but A → B and D → E have non-superkey left sides, so it is not in BCNF.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-464","question":"A clinic stores Booking(patient, specialty, doctor). Each doctor has exactly one specialty, and each patient sees exactly one doctor per specialty. Which statement is correct?","options":["Booking is in BCNF because (patient, specialty) is a key","Booking is in 3NF but not BCNF, and every BCNF decomposition loses the rule (patient, specialty) → doctor","Booking is not in 3NF because doctor → specialty is transitive","Decomposing into (doctor, specialty) and (patient, doctor) is lossy"],"answer":1,"explanation":"Keys are (patient, specialty) and (patient, doctor). doctor → specialty breaks BCNF but specialty is prime, so 3NF holds. The BCNF split (doctor, specialty), (patient, doctor) is lossless (doctor is a key of the first) but cannot check (patient, specialty) → doctor locally.","difficulty":"hard","source":"GATE CS · Product-company placement"},
  {"id":"cs-dbms-sql-465","question":"Which serial order is conflict-equivalent to the schedule R2(A), R1(B), W3(A), W1(C), R3(C), R4(B), W4(A)?","options":["T1, T3, T2, T4","T1, T2, T4, T3","T2, T1, T3, T4","No serial order: the schedule is not conflict-serializable"],"answer":2,"explanation":"Conflicts give T2 → T3 (R2(A), W3(A)), T1 → T3 (W1(C), R3(C)), T2 → T4 (R2(A), W4(A)) and T3 → T4 (W3(A), W4(A)). The graph is acyclic and T2, T1, T3, T4 respects every edge; the others put T3 before T2 or T4 before T3.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-466","question":"Classify the schedule R2(X), W1(X), W2(X), W3(X) (all transactions commit afterwards).","options":["Conflict-serializable","View-serializable but not conflict-serializable","Neither conflict- nor view-serializable","Conflict-serializable but not view-serializable"],"answer":1,"explanation":"R2(X) → W1(X) gives T2 → T1 and W1(X) → W2(X) gives T1 → T2, a cycle, so it is not conflict-serializable. The serial order T2, T1, T3 has the same initial read (T2) and the same final write (T3), so it is view-serializable thanks to the blind writes.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-467","question":"Classify the schedule W1(X), W2(X), R3(X), C3, C1, C2 (Ci = commit of Ti).","options":["Recoverable but not cascadeless","Cascadeless but not strict","Strict","Not recoverable"],"answer":3,"explanation":"R3(X) reads the value written by T2, the latest writer before it, not T1. T3 commits before T2 does, so if T2 aborted, T3's committed result would depend on discarded data: the schedule is not recoverable.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-468","question":"Timestamp ordering with Thomas's write rule: TS(T1) = 5, TS(T2) = 10, TS(T3) = 15, and all read/write timestamps start at 0. The operations arrive as W2(A), R3(B), W1(A), W1(B). What happens to T1?","options":["T1 completes; W1(A) is ignored as obsolete","T1 is rolled back at W1(A) because a younger transaction wrote A","T1 is rolled back at W1(B), after W1(A) was ignored","T1 completes; W1(A) overwrites T2's value"],"answer":2,"explanation":"W1(A): W-ts(A) = 10 > 5 and R-ts(A) = 0, so Thomas's rule skips the outdated write. W1(B): R-ts(B) = 15 > 5, meaning a younger transaction already read B, so T1 must be rolled back. Basic TO (without Thomas) would have aborted at W1(A).","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-469","question":"Timestamps: T1 = 10 (oldest), T2 = 20, T3 = 30. T2 holds an exclusive lock on X. First T1 requests X, then T3 requests X. Which is correct?","options":["Wait-die: T1 waits and T3 is rolled back; wound-wait: T2 is rolled back for T1, and T3 waits","Wait-die: T1 is rolled back and T3 waits; wound-wait: T1 waits and T3 is rolled back","Wait-die: both T1 and T3 wait; wound-wait: T2 is rolled back for both","Wait-die: T1 waits and T3 waits; wound-wait: T1 and T3 are both rolled back"],"answer":0,"explanation":"Wait-die: an older requester waits, a younger one dies, so T1 waits and T3 dies. Wound-wait: an older requester wounds (aborts) the younger holder, a younger requester waits, so T2 is aborted for T1 and T3 waits.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-470","question":"A hospital requires at least one doctor on call. Doctors Ana and Ben are both on call. Each starts a transaction under snapshot isolation, checks that the number of on-call doctors is at least 2, and then sets only their own row to off-call; both commit. What is the result?","options":["Both commit and nobody is on call (write skew)","The second commit fails with a write-write conflict","Snapshot isolation serialises them, so exactly one is still on call","Both block forever waiting for each other's row lock"],"answer":0,"explanation":"Each transaction reads the same snapshot (2 on call) and writes a different row, so snapshot isolation's first-committer-wins check finds no write-write conflict. Both commit and the constraint breaks; only serializable isolation (e.g. SSI) or a lock on the read rows prevents this.","difficulty":"very-hard","source":"Product-company placement · GATE CS"},
  {"id":"cs-dbms-sql-471","question":"An account has balance 1000. Two sessions at READ COMMITTED each run SELECT bal (both read 1000 before either writes), then compute 1000 − 100 in the application and run UPDATE acct SET bal = 900, and commit. What is the final balance?","options":["800","900","800, because the second UPDATE waits for the first one's row lock","1000"],"answer":1,"explanation":"Both write the absolute value 900 computed from the same old read, so one withdrawal is lost: the classic lost update. READ COMMITTED only stops reading uncommitted data; to prevent it use UPDATE ... SET bal = bal − 100, SELECT ... FOR UPDATE or a stronger isolation level.","difficulty":"hard","source":"Product-company placement"},
  {"id":"cs-dbms-sql-472","question":"Two transactions each read row X under a shared lock and later want to update it, so each requests an upgrade to an exclusive lock. What happens under strict 2PL, and what is the usual remedy?","options":["Both upgrades succeed because they hold the same lock","They deadlock; taking an update (U) lock at read time lets only one of them plan an upgrade","The second upgrade waits until the first commits, so no deadlock is possible","Strict 2PL releases shared locks early, so the upgrades go through in turn"],"answer":1,"explanation":"Each waits for the other's shared lock to be released before it can get X, and neither releases until commit: a deadlock. U locks are compatible with S but not with other U locks, so only one transaction can be waiting to upgrade.","difficulty":"hard","source":"GATE CS · Product-company placement"},
  {"id":"cs-dbms-sql-473","question":"After ARIES analysis the dirty page table holds P1 (recLSN 40), P2 (recLSN 25) and P3 (recLSN 60); the last checkpoint began at LSN 30. Where does the redo pass start, and what happens to the log record at LSN 35 that updates P1?","options":["At LSN 30; the LSN 35 update is redone","At LSN 25; the LSN 35 update is redone because it is after the start","At LSN 25; the LSN 35 update is skipped without reading P1 because 35 < recLSN(P1) = 40","At LSN 40; LSN 35 is never examined"],"answer":2,"explanation":"Redo starts at the smallest recLSN in the dirty page table, 25. A record is skipped if its page is not dirty or its LSN is below that page's recLSN; 35 < 40 means P1's copy on disk already contains it, so no page read is needed.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-474","question":"A DBMS uses deferred database modification: no change reaches the database before its transaction commits (NO-STEAL), but committed changes may still be only in the log at a crash (NO-FORCE). What does crash recovery need?","options":["Undo of uncommitted transactions only","Both undo and redo","Neither undo nor redo","Redo of committed transactions only"],"answer":3,"explanation":"Uncommitted transactions never wrote to the database, so there is nothing to undo; committed ones might not be on disk yet, so they must be redone from the log.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-dbms-sql-475","question":"A B+ tree stores 1,000,000 keys. Each internal node has at most 50 children (at least 25, except the root, which needs at least 2), and each leaf holds 20 to 40 keys. Counting the leaf level, how many levels can the tree have?","options":["Exactly 4","3 to 4","4 to 5","3 to 5"],"answer":2,"explanation":"Fewest levels: at least 25,000 leaves are needed and 50³ = 125,000 ≥ 25,000 but 50² is not, so 4. Most levels: there are at most 50,000 leaves, and a tree of h levels has at least 2 × 25^(h−2) leaves, which is 31,250 for h = 5 but 781,250 for 6, so 5. Forgetting the root's lower limit of 2 gives exactly 4.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-476","question":"R occupies 1000 blocks and S 500 blocks; 50 buffer blocks are available. Ignoring the cost of writing the result, what does a Grace hash join of R and S cost in block I/Os?","options":["4500","1500","7500","3000"],"answer":0,"explanation":"Partitioning reads and writes both relations (2 × 1500) and the probe phase reads them once more (1500): 3(M + N) = 4500. 50 buffers are enough since each S partition must fit in memory (about √500 ≈ 23). 7500 is a sort-merge join with one merge pass per relation.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-477","question":"A table has 1,000,000 rows stored 20 per block. An unclustered B+ tree index fetches each matching row with one random block read (ignore index traversal). Above roughly what selectivity is a full table scan cheaper than using the index?","options":["20%","2%","50%","5%"],"answer":3,"explanation":"The scan reads 1,000,000 / 20 = 50,000 blocks; the index costs about one read per matching row, so it loses once matches exceed 50,000 rows, i.e. 5% = 1 / (rows per block). Optimisers therefore skip unclustered indexes for even moderately selective predicates.","difficulty":"hard","source":"Product-company placement · GATE CS"},
  {"id":"cs-dbms-sql-478","question":"R(A, B) = {(1, x), (2, y), (3, z)} and S(B, C) = {(x, 5), (x, 6), (w, 7)}. How many tuples are in the natural full outer join of R and S?","options":["5","4","6","3"],"answer":0,"explanation":"Matches: (1, x, 5) and (1, x, 6). Unmatched R tuples (2, y) and (3, z) are padded with NULL C, and the unmatched S tuple (w, 7) with NULL A: 2 + 2 + 1 = 5.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-dbms-sql-479","question":"Customer(cid, city) LEFT OUTER JOIN Orders(oid, cid, amt) on cid is followed by the selection amt > 100. An optimiser wants to push this selection down. Which statement is correct?","options":["σ_{amt>100} can be pushed onto Orders before the outer join without changing the result","The selection cannot be evaluated after an outer join at all","Pushing it down is valid only if cid is a key of Customer","Pushing it below the join keeps customers with no qualifying orders as NULL-padded rows, which the original query removes, so the rewrite is wrong"],"answer":3,"explanation":"After the join, σ_{amt>100} rejects NULL-padded rows, so the query is effectively an inner join. Pushing the selection onto Orders first and then outer-joining would bring those customers back with NULLs; the correct rewrite turns the outer join into an inner join and then pushes the selection.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-480","question":"An ER diagram has Student (key roll, multivalued attribute phone), Course (key cid) and Faculty (key fid). Enrols is many-to-many between Student and Course, and Advises is one-to-many from Faculty to Student, with total participation of Student. What is the minimum number of tables in a correct relational design?","options":["5","4","6","7"],"answer":0,"explanation":"Student, Course and Faculty need a table each, the multivalued phone needs Student_Phone(roll, phone), and the M:N Enrols needs its own table: 5. The 1:N Advises is absorbed as a non-null fid column in Student, so it needs no table.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-481","question":"R has 2000 tuples with 100 distinct values of attribute b; S has 5000 tuples with 250 distinct values of b. Assuming uniform values and that the smaller set of b-values is contained in the larger, what is the optimiser's estimate of |R ⋈ S| on b?","options":["100,000","28,571","400","40,000"],"answer":3,"explanation":"The standard estimate is |R| × |S| / max(V(R, b), V(S, b)) = 2000 × 5000 / 250 = 40,000: each R tuple meets 5000 / 250 = 20 S tuples. Dividing by the smaller count (100) overestimates, and 400 divides by the product of the two counts.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-482","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat does this query return?\nSELECT COUNT(*), COUNT(amt), COUNT(DISTINCT amt), COUNT(region) FROM Bill;","options":["7, 5, 4, 6","7, 7, 3, 7","7, 5, 3, 6","7, 5, 3, 7"],"answer":2,"explanation":"COUNT(*) counts all 7 rows; COUNT(amt) skips the two NULL amounts (5); DISTINCT over non-NULL amounts gives {200, 300, 450} = 3; COUNT(region) skips Nair's NULL region (6).","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-483","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhich rows does this query return?\nSELECT region, SUM(amt) FROM Bill GROUP BY region HAVING COUNT(amt) >= 2;","options":["('E', 750) and ('W', 750)","('E', 750) and ('W', NULL)","('E', 750) only","('E', 750), ('W', 750) and (NULL, 200)"],"answer":0,"explanation":"Each of E and W has two non-NULL amounts (300 + 450 = 750), and SUM simply skips the NULL; the NULL-region group has COUNT(amt) = 1 and fails HAVING.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-484","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat does this query return?\nSELECT COUNT(*) FROM Bill\nWHERE region NOT IN (SELECT region FROM Bill WHERE amt > 400);","options":["1","4","5","0"],"answer":3,"explanation":"The subquery yields {'E', 'W'} (no NULL), so every E or W row is excluded. Nair's region is NULL, and NULL NOT IN (...) is UNKNOWN, not TRUE, so that row is dropped too: 0.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-485","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat values does this query show for ids 1 and 4?\nSELECT id, SUM(amt) OVER (ORDER BY amt) AS run FROM Bill WHERE amt IS NOT NULL;","options":["500 and 800 (in some order)","800 and 800","300 and 600","200 and 500"],"answer":1,"explanation":"With ORDER BY and no frame clause the default frame is RANGE ... CURRENT ROW, which includes all peers. Ids 1 and 4 both have amt 300, so both get 200 + 300 + 300 = 800; 500 would need a ROWS frame.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-486","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nTable Cust(name, tier) rows: ('Kavi', 'Gold'), ('Lata', 'Silver'), ('Mona', 'Gold'), ('Ravi', 'Silver').\nQuery P: SELECT COUNT(*) FROM Cust c LEFT JOIN Bill b ON c.name = b.cust AND b.amt > 300;\nQuery Q: SELECT COUNT(*) FROM Cust c LEFT JOIN Bill b ON c.name = b.cust WHERE b.amt > 300;\nWhat do P and Q return?","options":["4 and 4","5 and 2","2 and 2","4 and 2"],"answer":3,"explanation":"In P the filter is part of the join: Kavi and Lata match one row each, Mona and Ravi are padded with NULLs, giving 4. In Q the WHERE removes the NULL-padded rows after the join, leaving only bills 3 and 6.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-487","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat does this query return?\nSELECT AVG(amt), AVG(COALESCE(amt, 0)) FROM Bill;","options":["340 and about 242.86","about 242.86 and 340","about 283.33 and about 242.86","340 and 340"],"answer":0,"explanation":"AVG(amt) ignores the 2 NULLs: 1700 / 5 = 340. COALESCE turns them into 0, so the second average divides 1700 by all 7 rows (about 242.86).","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-488","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhich ids does this query return?\nSELECT id FROM Bill b\nWHERE amt > (SELECT AVG(amt) FROM Bill x WHERE x.region = b.region);","options":["3, 5 and 6","3, 6 and 7","3 and 6","No rows"],"answer":2,"explanation":"E and W both average 375 over their non-NULL amounts, so only the 450 bills (3 and 6) pass. For Nair, x.region = NULL is never TRUE, the subquery's AVG is NULL and 200 > NULL is UNKNOWN; bill 7 has a NULL amt.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-489","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhich customers does this query return?\nSELECT cust FROM Bill GROUP BY cust HAVING COUNT(*) > COUNT(amt);","options":["Lata and Mona","Kavi and Lata","Mona only","Lata only"],"answer":0,"explanation":"COUNT(*) exceeds COUNT(amt) exactly when a group has a NULL amount: Lata (bill 2) and Mona (bill 7). Kavi's two bills both have amounts.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-490","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nTable Cust(name, tier) rows: ('Kavi', 'Gold'), ('Lata', 'Silver'), ('Mona', 'Gold'), ('Ravi', 'Silver').\nHow many rows does this query return?\nSELECT region FROM Bill UNION SELECT tier FROM Cust;","options":["6","5","4","11"],"answer":1,"explanation":"UNION removes duplicates and treats all NULLs as one value, so the result is {E, W, NULL, Gold, Silver} = 5 rows. UNION ALL would keep all 11; ignoring the NULL row gives 4.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-491","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nFor id 5, what are r and d?\nSELECT id, RANK() OVER (ORDER BY amt DESC) AS r, DENSE_RANK() OVER (ORDER BY amt DESC) AS d\nFROM Bill WHERE amt IS NOT NULL;","options":["3 and 3","5 and 5","4 and 3","5 and 3"],"answer":3,"explanation":"Order is 450, 450, 300, 300, 200. RANK leaves gaps (1, 1, 3, 3, 5) while DENSE_RANK does not (1, 1, 2, 2, 3), so bill 5 gets 5 and 3.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-492","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat does this query return?\nSELECT COUNT(*) FROM Bill a JOIN Bill b ON a.amt = b.amt AND a.id <> b.id;","options":["2","4","6","8"],"answer":1,"explanation":"Equal non-NULL amounts pair bills 1-4 and 3-6, and <> counts each pair in both orders: 4. NULL = NULL is UNKNOWN, so bills 2 and 7 never pair (that mistake gives 6); a.id < b.id would give 2.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-493","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhich customers does this query return?\nSELECT cust FROM Bill GROUP BY cust HAVING MAX(amt) = MIN(amt);","options":["Mona and Nair","Lata, Mona and Nair","Nair only","Kavi, Lata, Mona and Nair"],"answer":1,"explanation":"MAX and MIN skip NULLs. Lata has only 450 and Mona only 300 among non-NULL values, so both pass with Nair (200); Kavi has 300 and 450. Thinking a NULL makes the group fail drops Lata and Mona.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-494","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nHow many NULLs appear in the column diff?\nSELECT id, amt - LAG(amt) OVER (ORDER BY id) AS diff FROM Bill;","options":["2","3","5","4"],"answer":3,"explanation":"diff is NULL for id 1 (no previous row), id 2 (own amt NULL), id 3 (previous amt NULL) and id 7 (own amt NULL); ids 4, 5 and 6 give -150, -100 and 250. That is 4 NULLs.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-495","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nTable Cust(name, tier) rows: ('Kavi', 'Gold'), ('Lata', 'Silver'), ('Mona', 'Gold'), ('Ravi', 'Silver').\nWhat does this query return for tier 'Silver'?\nSELECT c.tier, COUNT(b.id), COUNT(*) FROM Cust c LEFT JOIN Bill b ON b.cust = c.name GROUP BY c.tier;","options":["('Silver', 2, 3)","('Silver', 3, 3)","('Silver', 2, 2)","('Silver', 1, 2)"],"answer":0,"explanation":"Silver customers are Lata (bills 2 and 6) and Ravi (no bills, one NULL-padded row). COUNT(*) counts all 3 joined rows; COUNT(b.id) skips Ravi's NULL, giving 2.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-496","question":"What does this query return (SQL:1999 recursive CTE; runs as written in SQLite and PostgreSQL)?\nWITH RECURSIVE t(n) AS (SELECT 1 UNION ALL SELECT n * 2 FROM t WHERE n < 50)\nSELECT COUNT(*), MAX(n) FROM t;","options":["6 and 32","7 and 32","7 and 64","6 and 64"],"answer":2,"explanation":"The WHERE tests the previous row, so 32 < 50 still produces 64; then 64 fails and recursion stops. Rows: 1, 2, 4, 8, 16, 32, 64, so 7 rows with maximum 64.","difficulty":"hard","source":"Product-company SDE · GATE CS"},
  {"id":"cs-dbms-sql-497","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nIn standard SQL (SQLite lacks ALL; the result was checked with the equivalent NOT EXISTS form), what does this return?\nSELECT COUNT(*) FROM Bill WHERE amt > ALL (SELECT amt FROM Bill WHERE region = 'X');","options":["0","5","7","6"],"answer":2,"explanation":"No row has region 'X', so the subquery is empty, and a comparison with ALL over an empty set is TRUE for every row, even rows whose amt is NULL. All 7 rows are counted.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-498","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nFor how many customers do SUM(amt) * 1.0 / COUNT(*) and AVG(amt) give different values?","options":["1","3","0","2"],"answer":3,"explanation":"AVG divides by the non-NULL count while COUNT(*) counts every row. Only Lata (450 / 2 vs 450) and Mona (300 / 2 vs 300) have NULL amounts, so they differ for 2 customers.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-499","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nHow many rows go into each tile?\nSELECT id, NTILE(3) OVER (ORDER BY id) FROM Bill;","options":["2, 2 and 3","3, 2 and 2","3, 3 and 1","2, 3 and 2"],"answer":1,"explanation":"NTILE splits 7 rows into 3 groups whose sizes differ by at most one, giving the extra rows to the earlier tiles: 3, 2, 2 (ids 1-3, 4-5, 6-7).","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-500","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat does this query return?\nSELECT COUNT(*) FROM Bill WHERE amt BETWEEN 450 AND 300;","options":["4","2","0","5"],"answer":2,"explanation":"x BETWEEN a AND b means x >= a AND x <= b, and no amount is both >= 450 and <= 300, so 0 rows. BETWEEN is not symmetric unless written BETWEEN SYMMETRIC; the swapped bounds would count 4.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-501","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat does this query return? (|| is standard string concatenation; in MySQL's default mode it means OR.)\nSELECT COUNT(DISTINCT region || cust) FROM Bill;","options":["4","6","7","5"],"answer":0,"explanation":"Concatenating with a NULL gives NULL, so Nair's row yields NULL and COUNT(DISTINCT ...) ignores it. The distinct non-NULL strings are EKavi, WLata, WMona and EMona: 4.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-502","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nThis statement is run once:\nUPDATE Bill SET amt = amt + 100 WHERE amt < (SELECT AVG(amt) FROM Bill);\nWhat is SUM(amt) afterwards?","options":["2000","2200","1900","2100"],"answer":0,"explanation":"The average is 340, so bills 1, 4 and 5 (300, 300, 200) each gain 100; NULL amounts fail the comparison and stay NULL. 1700 + 300 = 2000. Standard SQL evaluates the subquery as of before the update.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-503","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat values does the second column show for ids 2 and 7?\nSELECT id, COALESCE(amt, LAG(amt) OVER (ORDER BY id)) FROM Bill;","options":["NULL and NULL","300 and 450","300 and NULL","450 and 450"],"answer":1,"explanation":"LAG looks at the previous row by id: for id 2 that is bill 1 (300), and for id 7 it is bill 6 (450). COALESCE takes those because the row's own amt is NULL.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-504","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nFor id 4, what is the second column?\nSELECT id, FIRST_VALUE(id) OVER (PARTITION BY region ORDER BY amt DESC) FROM Bill WHERE amt IS NOT NULL;","options":["4","3","6","1"],"answer":2,"explanation":"Bill 4 is in region W, whose non-NULL rows are 6 (450) and 4 (300). Ordered by amt descending, the first is bill 6. Bill 3 is the first in region E, not W.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-505","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat values does the second column show for ids 5 and 1?\nSELECT id, LAST_VALUE(amt) OVER (ORDER BY amt) FROM Bill WHERE amt IS NOT NULL;","options":["450 and 450","200 and 450","200 and 300","450 and 300"],"answer":2,"explanation":"The default frame ends at the current row and its peers, so LAST_VALUE returns the current row's own peer-group value, not the partition's last: 200 for bill 5 and 300 for bill 1. Getting 450 needs ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-506","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat values does the second column show for ids 3 and 6?\nSELECT id, SUM(amt) OVER (PARTITION BY cust ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) FROM Bill;","options":["750 and NULL","450 and 450","300 and 450","750 and 450"],"answer":3,"explanation":"Kavi's partition is ids 1, 3, so id 3 sums 300 + 450 = 750. Lata's partition is ids 2, 6; id 6 sums NULL and 450, and SUM skips the NULL, giving 450.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-507","question":"Table Bill(id, cust, region, amt) rows: (1, 'Kavi', 'E', 300), (2, 'Lata', 'W', NULL), (3, 'Kavi', 'E', 450), (4, 'Mona', 'W', 300), (5, 'Nair', NULL, 200), (6, 'Lata', 'W', 450), (7, 'Mona', 'E', NULL).\nWhat does this query return?\nSELECT SUM(CASE WHEN amt > 300 THEN 1 WHEN amt <= 300 THEN 0 ELSE -1 END) FROM Bill;","options":["5","-2","0","NULL"],"answer":2,"explanation":"Bills 3 and 6 give 1 each, bills 1, 4 and 5 give 0, and for the two NULL amounts both comparisons are UNKNOWN, so CASE falls to ELSE -1. Total 2 + 0 - 2 = 0; CASE never returns NULL here.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-508","question":"R(A, B, C, D, E, F) has functional dependencies AB → C, C → D, D → A, BE → F and F → E. How many candidate keys does R have?","options":["4","8","2","6"],"answer":3,"explanation":"B is on no right side, so it is in every key. A, C, D form a cycle (pick any one of them) and E, F form another (pick one), giving 3 × 2 = 6 keys such as ABE, BCF, BDE.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-509","question":"R(A, B, C, D, E) has functional dependencies A → B, B → C, C → A and D → E. What is the highest normal form R satisfies?","options":["1NF","2NF","3NF","BCNF"],"answer":0,"explanation":"The keys are AD, BD and CD, so A, B, C, D are prime and A → B, B → C, C → A only violate BCNF. But D → E makes the non-prime E depend on part of every key, a partial dependency, so R is not even in 2NF.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-510","question":"R(A, B, C, D) has functional dependencies AB → C, C → D and D → B. Which statement is correct?","options":["R is in BCNF because every attribute is prime","R is in 2NF but not 3NF because C → D is transitive","R is in 3NF but not BCNF","R is only in 1NF because D → B is partial"],"answer":2,"explanation":"The keys are AB, AC and AD, so every attribute is prime and 3NF holds automatically. C → D has a determinant that is not a superkey, so BCNF fails; being prime does not rescue BCNF.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-511","question":"R(A, B, C, D, E) has functional dependencies AB → CD, D → A and C → E. What is the highest normal form R satisfies?","options":["2NF","3NF","1NF","BCNF"],"answer":0,"explanation":"The keys are AB and BD, so A, B, D are prime. D → A has a prime right side and no non-prime attribute depends on part of a key, so 2NF holds; C → E is a transitive dependency of non-prime E through non-prime C, which breaks 3NF.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-512","question":"R(A, B, C, D, E, F, G) has functional dependencies A → B, BC → D, D → E, E → C and F → G. How many candidate keys does R have?","options":["1","2","4","3"],"answer":3,"explanation":"A and F appear on no right side, so AF is in every key, and AF⁺ = ABFG. Adding any one of C, D, E closes the cycle (C → D via B, D → E, E → C), so the keys are ACF, ADF and AEF.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-513","question":"R(A, B, C, D, E) has functional dependencies A → BC, CD → E, B → D and E → A. What are all the candidate keys of R?","options":["A, E, BC and CD","A and E only","A, E and CD","A, E, BC, CD and BD"],"answer":0,"explanation":"A⁺ is everything, and E → A makes E a key. BC⁺: B → D, then CD → E → A, so BC is a key; CD → E → A → B also works. BD⁺ = BD only, so BD is not a key.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-514","question":"Which of these is a minimal (canonical) cover of F = {AB → C, A → D, D → C, BD → E, AB → E}?","options":["{A → D, D → C, AB → E}","{A → C, A → D, BD → E}","{A → D, D → C, BD → E}","{A → D, D → C, BD → E, AB → C}"],"answer":2,"explanation":"AB → C follows from A → D → C, and AB → E follows from A → D with BD → E, so both are redundant. Replacing BD → E by AB → E loses BD → E (BD⁺ would be only BD), and dropping D → C loses it too.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-515","question":"R(A, B, C, D, E, F) has functional dependencies AB → CDEF and CD → AB. How many superkeys does R have?","options":["32","28","24","16"],"answer":1,"explanation":"The candidate keys are AB and CD. Supersets of AB number 2⁴ = 16, supersets of CD also 16, and those containing both (ABCD plus any of E, F) are 4, so 16 + 16 − 4 = 28.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-516","question":"R(A, B, C, D, E) has functional dependencies A → B, BC → E and ED → A. It is decomposed into R1(A, B, C) and R2(A, C, D, E). Which statement is correct?","options":["Lossless and dependency preserving","Lossy but dependency preserving","Lossy and not dependency preserving","Lossless but not dependency preserving"],"answer":3,"explanation":"The common attributes AC determine B (A → B) and then E (BC → E), so AC → R1 and the join is lossless. BC → E is lost: R1 has no E and R2 has no B, and the projected FDs cannot rebuild it.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-517","question":"F = {A → B, AB → C, D → AC, D → E} and G = {A → BC, D → AE}. Which statement is correct?","options":["F and G are equivalent","F covers G, but G does not cover F","G covers F, but F does not cover G","Neither covers the other"],"answer":0,"explanation":"Under F, A⁺ = ABC and D⁺ = ABCDE, so A → BC and D → AE hold. Under G, A → B, AB → C, D → AC (via A → BC) and D → E all hold, so each set implies the other.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-dbms-sql-518","question":"For the schedule R3(A), W1(B), R2(B), W2(A), W4(C), R3(C), how many serial schedules are conflict equivalent to it?","options":["1","3","4","6"],"answer":1,"explanation":"The conflicts give edges T1 → T2 (B), T3 → T2 (A) and T4 → T3 (C). So T2 is last and T4 precedes T3, while T1 can sit in any of the 3 places before T2: T1T4T3T2, T4T1T3T2, T4T3T1T2.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-519","question":"For the schedule R1(A), W2(A), R3(B), R4(B), W3(C), R1(C), how many serial schedules are conflict equivalent to it?","options":["2","6","4","1"],"answer":2,"explanation":"Only two conflicts exist: R1(A)-W2(A) gives T1 → T2 and W3(C)-R1(C) gives T3 → T1. R3(B) and R4(B) are both reads, so T4 is free: insert it into T3 T1 T2 at any of 4 positions.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-520","question":"Classify the schedule R1(X), W2(X), W1(X), W3(X), R4(X).","options":["Conflict serializable, equivalent to T2 T1 T3 T4","View serializable (as T1 T2 T3 T4) but not conflict serializable","Neither conflict nor view serializable","Conflict serializable, equivalent to T1 T2 T3 T4"],"answer":1,"explanation":"R1(X) → W2(X) and W2(X) → W1(X) form a cycle, so it is not conflict serializable. In T1 T2 T3 T4, T1 reads the initial X, T4 reads T3's write and T3 writes last, exactly as here; the blind writes make the views match.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-521","question":"Classify the schedule W1(A), W2(A), C1, R3(A), C2, C3 (Ci = commit of Ti) by the strongest property it satisfies.","options":["Strict","Cascadeless but not strict","Not recoverable","Recoverable but not cascadeless"],"answer":3,"explanation":"R3(A) reads T2's write while T2 is still uncommitted (C1 does not help; T2 wrote last), so it is not cascadeless. T2 commits before T3, so it is recoverable. W2(A) over T1's uncommitted write also rules out strict.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-522","question":"For the schedule W1(A), W2(B), R1(B), W2(A), C2, C1, which statement is correct?","options":["It is recoverable but neither cascadeless nor conflict serializable","It is conflict serializable and cascadeless","It is conflict serializable but not recoverable","It is cascadeless but not conflict serializable"],"answer":0,"explanation":"T1 reads B from uncommitted T2 (not cascadeless), but T2 commits first (recoverable). W2(B) → R1(B) gives T2 → T1 and W1(A) → W2(A) gives T1 → T2, a cycle, so it is not conflict serializable.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-523","question":"For the schedule W2(B), R1(B), W1(A), R3(A), C3, C1, C2, which statement is correct?","options":["It is not conflict serializable but it is recoverable","It is conflict serializable (as T2 T1 T3) but not recoverable","It is conflict serializable and recoverable, but not cascadeless","It is neither conflict serializable nor recoverable"],"answer":1,"explanation":"The edges T2 → T1 and T1 → T3 are acyclic, giving T2 T1 T3. But T3 reads from T1 and commits before T1, and T1 reads from T2 and commits before T2, so it is not recoverable: serializability says nothing about commit order.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-524","question":"TS(T1) = 1, TS(T2) = 2, TS(T3) = 3; all read/write timestamps start at 0. The schedule R1(A), W3(A), W2(A), R2(B), W1(B) is run under timestamp ordering, and an aborted transaction's later operations are skipped. Which transaction is rolled back (a) under basic TO and (b) with Thomas' write rule?","options":["(a) T2  (b) T2","(a) T1  (b) T1","(a) T2  (b) T1","(a) T1  (b) T2"],"answer":2,"explanation":"Basic TO aborts T2 at W2(A) since WTS(A) = 3 > 2; R2(B) is then skipped, so W1(B) succeeds. With Thomas' rule W2(A) is just ignored, R2(B) runs and sets RTS(B) = 2, and then W1(B) with TS 1 < 2 aborts T1.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-525","question":"TS(T1) = 7, TS(T2) = 3, TS(T3) = 9; all read/write timestamps start at 0. The schedule W2(A), R3(A), W1(A), W3(B), R1(B), W2(B) is run, skipping an aborted transaction's later operations. Which transactions are rolled back under basic TO, and which with Thomas' write rule?","options":["Basic: T1 only; Thomas: T1 only","Basic: T1 and T2; Thomas: T1 only","Basic: T1 and T2; Thomas: T2 only","Basic: T2 only; Thomas: none"],"answer":1,"explanation":"W1(A) fails both ways because RTS(A) = 9 > 7 (a read, so Thomas cannot help). W2(B) has TS 3 < WTS(B) = 9 with RTS(B) = 0: basic TO aborts T2, Thomas' rule just ignores the obsolete write.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-526","question":"TS(T1) = 5, TS(T2) = 10, TS(T3) = 15. T2 holds an exclusive lock on X; then T1 and T3 each request X. What happens under wound-wait?","options":["T1 waits for T2, and T3 is rolled back","T1 is rolled back, and T3 waits for T2","T2 is rolled back (wounded) by T1, and T3 waits","T1 and T3 both wait, since neither holds a lock T2 needs"],"answer":2,"explanation":"In wound-wait an older requester wounds (aborts) the younger holder, while a younger requester waits. T1 (5) is older than T2 (10), so T2 is rolled back; T3 (15) is younger and waits. Option A describes wait-die.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-527","question":"T1 and T2 run the schedule R1(A), W2(A), R1(B), C1, C2, and each transaction may acquire any lock as early as it likes. Under which locking protocols can this exact schedule occur?","options":["Basic 2PL only, not strict or rigorous 2PL","None of the basic, strict or rigorous variants","Basic and strict 2PL, but not rigorous 2PL","All three: basic, strict and rigorous 2PL"],"answer":2,"explanation":"T1 can take S(A) and S(B) first and release S(A) before W2(A), still being two-phase. Strict 2PL holds only exclusive locks to commit, so releasing T1's shared lock early is allowed; rigorous 2PL holds every lock to commit, so W2(A) could not run before C1.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-528","question":"Under snapshot isolation, x = 50 and y = 50 with the rule x + y ≥ 0. T1 reads x and y and, if x + y ≥ 100, sets x = x − 100. T2 concurrently reads x and y and, if x + y ≥ 100, sets y = y − 100. Both start before either commits. What is x + y after both finish?","options":["0, because the second committer is rolled back","-50","100, because both checks fail","-100"],"answer":3,"explanation":"Each transaction reads the snapshot (50, 50), sees x + y = 100 and writes a different item, so first-committer-wins finds no write-write conflict and both commit: x = -50, y = -50, sum -100. This write skew is the classic SI anomaly.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-529","question":"How many of these statements are correct?\n(i) Under multiversion timestamp ordering, a read request is never rejected.\n(ii) Thomas' write rule can produce schedules that are view serializable but not conflict serializable.\n(iii) Basic two-phase locking guarantees freedom from cascading rollback.\n(iv) In wait-die, a rolled-back transaction restarts with its original timestamp, so it cannot starve.","options":["2","3","4","1"],"answer":1,"explanation":"(i), (ii) and (iv) are true. (iii) is false: under basic 2PL a transaction can release an exclusive lock before committing, so others may read uncommitted data; strict 2PL is needed for cascadeless schedules.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-530","question":"During ARIES restart, the analysis pass rebuilds a dirty page table with entries P1 (recLSN 140), P2 (recLSN 95) and P3 (recLSN 210). The last checkpoint's begin record is at LSN 180. Where does the redo pass start?","options":["At LSN 95","At LSN 180","At LSN 140","At LSN 210"],"answer":0,"explanation":"Redo starts at the smallest recLSN in the dirty page table, since that is the earliest update that might not have reached disk. Starting at the checkpoint (180) would skip P2's and P1's older unflushed updates.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-531","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return?\nSELECT COUNT(*) FROM Emp WHERE eid NOT IN (SELECT mgr FROM Emp);","options":["3","4","0","7"],"answer":2,"explanation":"The subquery returns {NULL, 1, 1, 2, 2, 3, 4}. For any eid not in the list, eid NOT IN (...) compares against the NULL and becomes UNKNOWN, never TRUE, so no row qualifies. NOT EXISTS would correctly return the 3 non-managers.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-532","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return?\nWITH RECURSIVE r(id) AS (\n  SELECT eid FROM Emp WHERE mgr = 2\n  UNION ALL\n  SELECT e.eid FROM Emp e JOIN r ON e.mgr = r.id)\nSELECT COUNT(*) FROM r;","options":["2","3","4","5"],"answer":1,"explanation":"The anchor gives Bin's direct reports Dev (4) and Eli (5); the next step adds Gus (7), who reports to Dev; nobody reports to Gus or Eli. Bin himself is not in the anchor, so the count is 3.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-533","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return?\nSELECT sal FROM Emp e\nWHERE 2 = (SELECT COUNT(DISTINCT sal) FROM Emp x WHERE x.sal > e.sal);","options":["75","60","90","70"],"answer":3,"explanation":"It keeps a salary with exactly 2 distinct higher salaries, i.e. the 3rd highest distinct salary. Distinct salaries descending are 90, 75, 70, 60, 40, 30, so the answer is 70.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-534","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhich employees does this query return?\nSELECT e.name FROM Emp e JOIN Emp m ON e.mgr = m.eid WHERE e.sal > m.sal;","options":["Fay","Fay and Dev","No rows","Cy and Fay"],"answer":0,"explanation":"Fay (75) earns more than her manager Cy (70). Dev's 60 equals Bin's 60, which is not strictly greater, and Cy (70) earns less than Aru (90). Aru has no manager, so the inner join drops him.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-535","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nHow many rows does this query count?\nSELECT COUNT(*) FROM Emp e JOIN Emp m ON e.mgr = m.eid WHERE e.dept <> m.dept;","options":["3","2","4","1"],"answer":1,"explanation":"Cy (D2, manager D1) and Eli (D2, manager D1) qualify. Fay's dept is NULL, so NULL <> 'D2' is UNKNOWN and she is dropped; Bin, Dev and Gus are in their manager's department.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-536","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return for Fay?\nSELECT name, AVG(sal) OVER (PARTITION BY dept) FROM Emp;","options":["NULL, since her dept is NULL","about 60.71, the overall average","75","60, the D1 average"],"answer":2,"explanation":"PARTITION BY puts all NULL keys into one partition, just as GROUP BY does. Fay is the only row with a NULL dept, so her partition average is her own 75.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-537","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return?\nSELECT COUNT(*), COUNT(CASE WHEN dept IS NULL THEN 1 END), COUNT(CASE WHEN dept = NULL THEN 1 END) FROM Emp;","options":["7, 1, 1","7, 1, 0","6, 1, 0","7, 0, 0"],"answer":1,"explanation":"COUNT(*) is 7. Only Fay's dept IS NULL, so the second is 1. dept = NULL is UNKNOWN for every row, so that CASE always gives NULL and COUNT ignores it: 0.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-538","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return? (LIMIT/OFFSET is the SQLite/PostgreSQL/MySQL form of standard OFFSET ... FETCH.)\nSELECT name FROM Emp ORDER BY sal DESC, name LIMIT 2 OFFSET 2;","options":["Fay and Cy","Bin and Dev","Cy and Dev","Cy and Bin"],"answer":3,"explanation":"Sorted by salary descending and then name: Aru 90, Fay 75, Cy 70, Bin 60, Dev 60, Eli 40, Gus 30. Skipping 2 and taking 2 gives Cy and Bin; the name tie-breaker puts Bin before Dev.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-539","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return?\nSELECT COUNT(*) FROM Emp a, Emp b WHERE a.sal > b.sal;","options":["21","20","42","19"],"answer":1,"explanation":"Of the 7 × 7 = 49 ordered pairs, 7 pair a row with itself and the Bin-Dev tie gives 2 more equal pairs, so 40 pairs have different salaries. Exactly half of them, 20, have a.sal > b.sal.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-540","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return?\nSELECT COUNT(*) FROM Emp e WHERE sal > (SELECT AVG(sal) FROM Emp x WHERE x.dept = e.dept);","options":["2","3","4","1"],"answer":0,"explanation":"D1 averages 60 (90, 60, 60, 30), so only Aru exceeds it; D2 averages 55, so Cy qualifies. For Fay, x.dept = NULL matches no row, the AVG is NULL and 75 > NULL is UNKNOWN, so the count is 2.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-541","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nThis statement is run:\nDELETE FROM Emp WHERE sal < (SELECT AVG(sal) FROM Emp);\nHow many rows remain, and what is their salary total?","options":["4 rows totalling 295","2 rows totalling 165","3 rows totalling 235","3 rows totalling 225"],"answer":2,"explanation":"The average is 425 / 7 ≈ 60.71, computed once before any row is deleted. Bin, Dev (60), Eli (40) and Gus (30) go, leaving Aru, Cy and Fay: 90 + 70 + 75 = 235.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-542","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat values does the third column show for Cy and Aru?\nSELECT name, sal, SUM(sal) OVER (ORDER BY sal ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) FROM Emp;","options":["205 and 165","205 and 235","190 and 165","235 and 165"],"answer":0,"explanation":"In salary order (30, 40, 60, 60, 70, 75, 90) Cy's frame is 60 + 70 + 75 = 205. Aru is last, so his frame has no following row: 75 + 90 = 165.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-543","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat does this query return?\nSELECT COUNT(*) FROM Emp e LEFT JOIN Emp m ON e.mgr = m.eid\nWHERE m.dept = 'D1' OR m.dept IS NULL;","options":["7","1","3","6"],"answer":3,"explanation":"Five employees (Bin, Cy, Dev, Eli, Gus) have a manager in D1, and Aru (no manager) survives because the left join pads m with NULLs: 6. 7 wrongly keeps Fay by reading her own NULL dept (her manager Cy is in D2); 3 counts distinct D1 managers and 1 only the padded row.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-544","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat is Fay's value in the second column?\nSELECT name, PERCENT_RANK() OVER (ORDER BY sal) FROM Emp;","options":["5/7","6/7","5/6","1"],"answer":2,"explanation":"PERCENT_RANK = (rank − 1) / (rows − 1). In ascending salary order Fay (75) has rank 6 of 7, so (6 − 1) / (7 − 1) = 5/6. CUME_DIST would give 6/7.","difficulty":"very-hard","source":"Google/Microsoft SDE · GATE CS"},
  {"id":"cs-dbms-sql-545","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhat is Bin's value in the second column?\nSELECT name, CUME_DIST() OVER (ORDER BY sal) FROM Emp;","options":["3/7","4/7","1/3","2/3"],"answer":1,"explanation":"CUME_DIST counts the rows with salary ≤ the current one, peers included, over the total. Bin's 60 ties with Dev, so 30, 40, 60, 60 give 4/7 for both of them.","difficulty":"very-hard","source":"Google/Microsoft SDE · GATE CS"},
  {"id":"cs-dbms-sql-546","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhich name does this query return?\nSELECT name FROM Emp WHERE sal = (SELECT MAX(sal) FROM Emp WHERE sal < (SELECT MAX(sal) FROM Emp WHERE dept = 'D1'));","options":["Cy","Fay","Aru","Bin and Dev"],"answer":1,"explanation":"The D1 maximum is 90 (Aru). The largest salary in the whole table below 90 is Fay's 75; the middle subquery is not restricted to D1, so Cy's 70 is not the answer.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-547","question":"Table Emp(eid, name, mgr, dept, sal) rows: (1, 'Aru', NULL, 'D1', 90), (2, 'Bin', 1, 'D1', 60), (3, 'Cy', 1, 'D2', 70), (4, 'Dev', 2, 'D1', 60), (5, 'Eli', 2, 'D2', 40), (6, 'Fay', 3, NULL, 75), (7, 'Gus', 4, 'D1', 30). mgr refers to eid.\nWhich rows does this query return?\nSELECT mgr, COUNT(*) FROM Emp GROUP BY mgr HAVING COUNT(*) >= 2;","options":["(1, 2) and (2, 2)","(1, 2), (2, 2) and (NULL, 1)","(1, 2) only","(1, 3) and (2, 3)"],"answer":0,"explanation":"Aru (1) manages Bin and Cy, Bin (2) manages Dev and Eli; Cy and Dev manage one each and the NULL group holds only Aru, so those groups fail HAVING COUNT(*) >= 2.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-548","question":"A B+ tree index uses 2048-byte blocks, 16-byte search keys, 8-byte block pointers and 10-byte record pointers; a leaf also holds one 8-byte next-leaf pointer. What are the maximum internal fan-out p and the maximum keys per leaf n?","options":["p = 85, n = 78","p = 86, n = 79","p = 85, n = 79","p = 86, n = 78"],"answer":3,"explanation":"Internal: 8p + 16(p − 1) ≤ 2048 gives 24p ≤ 2064, p = 86. Leaf: 26n + 8 ≤ 2048 gives n ≤ 78.46, so n = 78. Writing p keys instead of p − 1 in the internal node gives the wrong 85.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-549","question":"A file of 12,000 blocks is sorted by external merge sort with 25 buffer blocks: the run-creation pass makes runs of 25 blocks, and each merge pass merges up to 24 runs. Counting both reads and writes in every pass (including writing the final output), how many block transfers are needed?","options":["48,000","72,000","96,000","60,000"],"answer":1,"explanation":"Run creation makes ⌈12000 / 25⌉ = 480 runs. Merging with fan-in 24 needs 2 passes (24² = 576 ≥ 480), so 3 passes in all, each reading and writing every block: 3 × 2 × 12,000 = 72,000.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-550","question":"Relations R (800 blocks) and S (300 blocks) are joined by block nested-loop join with 52 buffer blocks (one for output, one for the inner relation, the rest for the outer). What is the minimum number of block transfers, ignoring the output?","options":["5,100","5,600","3,300","4,300"],"answer":0,"explanation":"With S outer: 300 + ⌈300 / 50⌉ × 800 = 300 + 6 × 800 = 5,100. With R outer: 800 + ⌈800 / 50⌉ × 300 = 5,600. The smaller relation should be the outer one.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-551","question":"R has 10,000 tuples in 500 blocks and is the outer relation of an indexed nested-loop join with S. S has a B+ tree on the join attribute (its primary key) of height 3, and each probe costs 3 index blocks plus 1 data block. How many block accesses does the join need?","options":["30,500","40,000","40,500","2,500"],"answer":2,"explanation":"Each of the 10,000 outer tuples needs one probe of 3 + 1 = 4 accesses, plus 500 accesses to scan R: 500 + 40,000 = 40,500. Counting probes per block of R instead of per tuple gives the much smaller wrong figure.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-dbms-sql-552","question":"A sorted file has 60,000 records of 200 bytes stored unspanned in 4096-byte blocks. A sparse primary index has 20-byte entries (one per data block), stored in 4096-byte blocks and made multilevel until the top level fits in one block. How many block accesses does a lookup need?","options":["4","5","2","3"],"answer":3,"explanation":"20 records fit per block, so 3,000 data blocks and 3,000 index entries; 204 entries fit per index block, giving 15 first-level blocks and a 1-block second level. Lookup: 2 index levels + 1 data block = 3.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-553","question":"R has 2000 tuples and S has 5000 tuples. The join attribute A has 50 distinct values in R and 200 in S. Under the usual uniformity and containment assumptions, what is the estimated size of R ⋈ S?","options":["200,000","10,000","50,000","40,000"],"answer":2,"explanation":"The estimate is |R| × |S| / max(V(A, R), V(A, S)) = 2000 × 5000 / 200 = 50,000. Dividing by the smaller count (50) overestimates it as 200,000.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-554","question":"R(S, C) = {(1, a), (1, b), (2, a), (3, a), (3, b), (3, c), (4, b)}. What is R ÷ π_C(σ_{S = 1}(R))?","options":["{3}","{1, 3}","{1, 2, 3, 4}","{1, 2, 3}"],"answer":1,"explanation":"The divisor is the set of C values of S = 1, i.e. {a, b}. Division keeps every S paired with both a and b: 1 and 3. Student 3 also has c, which does not matter.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-555","question":"An ER diagram has entity Employee (key eid, composite attribute name, multivalued attribute phone), weak entity Dependent (partial key dname) identified by Employee through a 1:N relationship, and entity Project linked to Employee by the M:N relationship WorksOn. What is the minimum number of relations in a correct relational schema?","options":["4","6","5","3"],"answer":2,"explanation":"Employee (with name flattened), EmpPhone for the multivalued attribute, Dependent (key eid + dname, absorbing its identifying relationship), Project and WorksOn: 5. Only the M:N relationship and the multivalued attribute need extra tables.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-556","question":"A ternary relationship Supplies links Supplier, Part and Project, and the rule is: for a given project and part there is at most one supplier. Which attributes form the key of the Supplies relation?","options":["(project, part)","(supplier, part)","(supplier, project, part)","(supplier, project)"],"answer":0,"explanation":"The rule says (project, part) → supplier, so that pair identifies a Supplies tuple. All three keys together form a superkey but not a minimal one; the other pairs allow several tuples per pair.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-557","question":"The system crashes after the last record of this log (immediate modification; <Ti, X, old, new>; at the checkpoint all dirty pages were flushed and T2, T3 were active):\n<T1 start> <T1, A, 10, 20> <T2 start> <T2, B, 5, 15> <T1 commit> <T3 start> <T3, A, 20, 30> <checkpoint {T2, T3}> <T2, C, 1, 2> <T2 commit> <T3, B, 15, 25>\nAfter undo/redo recovery, what are A, B and C?","options":["A = 30, B = 25, C = 2","A = 20, B = 5, C = 1","A = 20, B = 15, C = 2","A = 10, B = 15, C = 2"],"answer":2,"explanation":"T2 committed after the checkpoint, so it is redone (B = 15, C = 2); T3 never committed, so its writes are undone in reverse: B back to 15, A back to 20. T1 committed before the checkpoint and needs nothing, so A is not rolled back to 10.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-558","question":"A buffer manager uses NO-STEAL (pages with uncommitted changes are never written to disk) and FORCE (all pages a transaction changed are written at commit). What must the recovery manager do after a crash?","options":["Only undo the writes of uncommitted transactions","Neither undo nor redo for transaction effects","Only redo the writes of committed transactions","Both undo and redo, exactly as ARIES does"],"answer":1,"explanation":"NO-STEAL means no uncommitted change ever reaches disk, so nothing needs undoing; FORCE means every committed change is already on disk, so nothing needs redoing. The price is poor buffer performance, which is why real systems use STEAL/NO-FORCE.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-dbms-sql-559","question":"T1 reads the balance of account 7, then T2 updates that same row and commits, then T1 reads the row again and sees a different value. No rows are inserted or deleted. What is the lowest SQL-standard isolation level for T1 that rules this out?","options":["READ COMMITTED","SERIALIZABLE","READ UNCOMMITTED","REPEATABLE READ"],"answer":3,"explanation":"This is a non-repeatable read of an existing row. READ COMMITTED allows it; REPEATABLE READ forbids it (it still allows phantoms, which need new rows matching a predicate). SERIALIZABLE also prevents it but is not the lowest.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-560","question":"No transaction has committed. T1 writes A; T2 reads A and writes B; T3 reads B; T4 reads C, which only T5 wrote; T5 reads nothing written by others. If T1 now aborts, how many OTHER transactions must be rolled back?","options":["1","3","4","2"],"answer":3,"explanation":"T2 read T1's uncommitted A, and T3 read T2's uncommitted B, so both cascade. T4 depends only on T5 and T5 on nobody, so they are unaffected: 2 transactions.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-561","question":"A table has 1,000,000 rows in 10,000 blocks. A range predicate selects 20% of the rows, which are spread evenly across the table. There is an UNCLUSTERED B+ tree on the predicate column. Which plan is likely cheapest?","options":["The unclustered index, because it reads only the 200,000 matching rows and nothing else","A full table scan, because the index would cost one random block read per matching row","A hash index lookup on the same column, built on the fly","The index for half the range and a scan for the rest"],"answer":1,"explanation":"200,000 matching rows through an unclustered index means up to 200,000 random block reads, far more than scanning all 10,000 blocks sequentially. Unclustered indexes pay off only for highly selective predicates.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-562","question":"Table T(a, b, c) has a composite B+ tree index on (a, b), and the query is SELECT b FROM T WHERE a = 5. What is the main benefit of this index here?","options":["It can answer the query with an index-only scan, never touching the table","It is unusable, because the query does not filter on b","It helps only if the table is clustered on (a, b)","It can be used only with a full scan of all leaves"],"answer":0,"explanation":"The predicate uses the leading column a, and the only output column b is also in the index, so the index covers the query and the base table need not be read. A filter on the leading column alone is enough to use a composite index.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-563","question":"In extendible hashing, the global depth is 3 and a full bucket with local depth 2 must split on an insert. What happens?","options":["The directory doubles to 16 entries and the bucket splits","The bucket splits into two with local depth 3, the directory stays at 8 entries and some of its pointers are updated","The bucket gets an overflow page, since only buckets of local depth 3 may split","All buckets are rehashed with a new hash function"],"answer":1,"explanation":"When local depth < global depth, several directory entries point to the bucket, so it can split (local depth becomes 3) by redirecting half of those pointers. The directory doubles only when the splitting bucket's local depth equals the global depth.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-564","question":"R(Emp, Skill, Lang) satisfies Emp ↠ Skill (so also Emp ↠ Lang), and it is decomposed into the 4NF relations (Emp, Skill) and (Emp, Lang). Employee Rao has 3 skills and 4 languages. How many tuples about Rao are there in R, and in the two 4NF relations together?","options":["12 and 7","7 and 7","12 and 12","7 and 12"],"answer":0,"explanation":"The MVD forces every skill to pair with every language, so R stores 3 × 4 = 12 tuples for Rao. After decomposition he needs only 3 + 4 = 7. Removing this redundancy is the point of 4NF.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-565","question":"R(a) = {1, 2, 3} and S(a) = {2, 3, 3, 4} (S is a bag). How many rows does SELECT * FROM R FULL OUTER JOIN S ON R.a = S.a return? (Checked in SQLite 3.39+, which supports FULL OUTER JOIN.)","options":["4","6","5","3"],"answer":2,"explanation":"Matches: 2 pairs with one 2, and 3 pairs with both 3s, giving 3 rows. Unmatched R row 1 and unmatched S row 4 add one NULL-padded row each: 5. Forgetting the duplicate 3 gives 4.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-566","question":"A relation has 6 attributes. What is the largest possible number of candidate keys it can have under some set of functional dependencies?","options":["6","15","64","20"],"answer":3,"explanation":"Candidate keys cannot contain one another, so they form an antichain of subsets; by Sperner's theorem the largest has C(6, 3) = 20 sets, achieved when every 3-attribute set is a key (any 3 attributes determine the rest).","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-567","question":"In multiple-granularity locking, how many of these lock-mode pairs (held, requested) on the same node are compatible?\nIS–IX, IX–IX, S–IX, SIX–IS, SIX–IX","options":["2","4","3","5"],"answer":2,"explanation":"IS–IX, IX–IX and SIX–IS are compatible. S conflicts with IX (someone may write below a node another reads in full), and SIX conflicts with IX for the same reason, since SIX contains S.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-568","question":"Which statement correctly states the write-ahead logging (WAL) rule?","options":["A page is written only after the log records for its changes are stable, and commit waits for all its log records","The data page must reach disk before its log record, so the log can later be verified against it","Log records are written only at checkpoints, together with every dirty page in the buffer pool","Only the commit record must be forced at commit; earlier update records may still be lost in a crash"],"answer":0,"explanation":"WAL forces undo information to the log before the page it describes can overwrite the old value, and forces all of a transaction's log records (including commit) before reporting the commit. Writing the page first could leave an uncommitted change with no undo record.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-dbms-sql-569","question":"Which statement about compensation log records (CLRs) in ARIES is correct?","options":["CLRs are undone during a later restart if a crash interrupts recovery","CLRs record only the transaction id, not the page changed","CLRs are redo-only and carry an UndoNextLSN, so a crash during undo never undoes the same update twice","CLRs are written during the redo pass to mark pages already brought up to date"],"answer":2,"explanation":"Each undo action writes a CLR that is redone but never undone; its UndoNextLSN points to the next record still to undo, so repeated crashes during rollback do bounded work. CLRs are written in the undo pass, not the redo pass.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-570","question":"Which locking scheme guarantees BOTH freedom from deadlock and schedules without cascading rollback?","options":["Strict 2PL alone, holding exclusive locks until commit","Conservative 2PL alone, taking all locks before starting","Basic 2PL with lock upgrades from shared to exclusive","Conservative 2PL that also holds exclusive locks until commit"],"answer":3,"explanation":"Conservative 2PL acquires every lock before starting, so no transaction waits while holding locks (no deadlock), but it may release X locks early. Strict 2PL holds X locks to commit (cascadeless) but can deadlock. Combining both gives both guarantees.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-571","question":"Table T has 7 rows. What does SELECT COUNT(*) FROM T HAVING COUNT(*) > 10; return? (Standard SQL; SQLite accepts HAVING without GROUP BY from 3.39.)","options":["One row containing 0","One row containing 7","An error, since HAVING needs GROUP BY","No rows at all"],"answer":3,"explanation":"Without GROUP BY the whole table is a single group of 7 rows; HAVING tests that group, 7 > 10 is false, so the group and hence the only output row is removed. The result is empty, not 0.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-572","question":"Table U(x INT UNIQUE) is empty. These statements run one at a time: INSERT (1); INSERT (NULL); INSERT (NULL); INSERT (1). How many succeed in standard SQL (as in SQLite and PostgreSQL by default)?","options":["2","4","3","1"],"answer":2,"explanation":"UNIQUE rejects only equal non-NULL values, and NULLs are not considered equal to each other, so both NULLs are accepted and only the second 1 fails: 3. SQL Server is the well-known exception that allows a single NULL.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-573","question":"Table K(amt INT CHECK (amt > 0)) is empty. These run one at a time: INSERT (-5); INSERT (NULL); INSERT (0); INSERT (3). How many rows does K end up with?","options":["2","1","3","0"],"answer":0,"explanation":"A CHECK constraint rejects a row only when the condition is FALSE. For NULL, amt > 0 is UNKNOWN, so the NULL row is accepted along with 3; -5 and 0 fail. Use NOT NULL as well to forbid the NULL.","difficulty":"hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-574","question":"P(id PRIMARY KEY) has rows 1, 2. C(id, pid REFERENCES P ON DELETE CASCADE) has (10, 1), (11, 1), (12, 2). G(id, cid REFERENCES C ON DELETE SET NULL) has (100, 10), (101, 10), (102, 11), (103, 12), (104, NULL). After DELETE FROM P WHERE id = 1 (foreign keys enforced), how many rows of G have a NULL cid?","options":["3","4","2","1"],"answer":1,"explanation":"Deleting P 1 cascades to C rows 10 and 11. That fires SET NULL in G for 100, 101 and 102, which joins the already-NULL 104: 4 NULLs, and no G row is deleted. Thinking the cascade continues into G would delete rows instead.","difficulty":"very-hard","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-575","question":"R(A, B, C) is decomposed into R1(A, B) and R2(B, C). Which condition is necessary and sufficient (under FDs only) for the decomposition to be lossless?","options":["B → A or B → C holds","A → B and B → C both hold","B is a candidate key of R","A → C holds"],"answer":0,"explanation":"A binary decomposition is lossless exactly when the common attributes (B) functionally determine all of R1 or all of R2, i.e. B → A or B → C. B need not be a key of R, and A → B with B → C is sufficient but not necessary.","difficulty":"moderate","source":"GATE CS"},
  {"id":"cs-dbms-sql-576","question":"R(A, B, C) with FDs A → B and B → C has primary key A. A designer moves to R1(A, B) and R2(B, C). Which statement is correct?","options":["The decomposition is lossy because A does not appear in R2","It is lossless and dependency preserving, and both parts are in BCNF","It is lossless but loses A → C, so it is not dependency preserving","Both parts are in 3NF but not BCNF"],"answer":1,"explanation":"The common attribute B determines C, so the join is lossless. A → B lives in R1, B → C lives in R2, and A → C follows from them, so dependencies are preserved; each two-attribute part has a key on its left side, so both are in BCNF.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-577","question":"In a wait-for graph the edges are T1 → T2, T2 → T3, T3 → T1, T3 → T4 and T5 → T2. What is the minimum number of transactions that must be aborted to break every deadlock?","options":["0, because T4 can finish","1","2","3"],"answer":1,"explanation":"The only cycle is T1 → T2 → T3 → T1, and aborting any one of those three breaks it. T4 is not in the cycle, and T5 merely waits on T2; it is blocked but not deadlocked.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-578","question":"Under basic two-phase locking, which order of serial execution is a schedule conflict equivalent to?","options":["The order in which they started","The order of their commit records","The order of their lock points","The order of their timestamps"],"answer":2,"explanation":"In 2PL, if Ti's lock point precedes Tj's, every conflict between them goes from Ti to Tj, so ordering by lock point (when each takes its last lock) gives an equivalent serial schedule. Start order can differ; commit order equals it only under strict variants.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-579","question":"A query plan computes σ_{dept = 'D1' ∧ sal > 50}(Emp ⋈ Dept). Which rewrite is a heuristic optimizer most likely to apply first, and why?","options":["Replace the join with a Cartesian product, since products need no index","Push the selections below the join so fewer tuples enter it","Pull projections above the selection so every attribute stays available","Split the conjunction into two separate joins on Emp and on Dept"],"answer":1,"explanation":"Selections are pushed as low as possible (here onto Emp, or onto whichever relation owns each attribute) to shrink the join input; this is usually the biggest win. Products are never cheaper than an equivalent join, and projections are pushed down, not up.","difficulty":"moderate","source":"GATE CS · Amazon/Microsoft SDE MCQ"},
  {"id":"cs-dbms-sql-580","question":"A B+ tree has order p = 4 (at most 4 children per internal node, at most 3 keys per leaf) and every node except the root is at least half full. The tree has exactly 3 levels: root, one internal level and leaves. What is the MINIMUM number of keys it can hold?","options":["8","6","4","12"],"answer":0,"explanation":"The root needs at least 2 children; each internal node at least ⌈4 / 2⌉ = 2 children, giving 4 leaves; each leaf at least ⌈3 / 2⌉ = 2 keys. So 4 × 2 = 8 keys.","difficulty":"very-hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-581","question":"A relation R has candidate keys AB and BC, and FDs AB → C, C → A. Which statement explains why R is in 3NF but not BCNF?","options":["C → A has a determinant that is not a superkey, but A is prime","AB → C is a partial dependency on the key BC","C → A makes A a non-prime attribute that depends transitively on AB","R has two overlapping candidate keys, which BCNF forbids"],"answer":0,"explanation":"C is not a superkey, so C → A breaks BCNF; 3NF tolerates it because A belongs to a candidate key. Overlapping keys alone do not break BCNF; it is the non-superkey determinant that does.","difficulty":"hard","source":"GATE CS"},
  {"id":"cs-dbms-sql-582","question":"Which relational-algebra equivalence is NOT valid in general?","options":["σ_p(R − S) = σ_p(R) − S (selection over difference)","σ_p(R ∪ S) = σ_p(R) ∪ σ_p(S) (selection over union)","π_A(R − S) = π_A(R) − π_A(S) (projection over difference)","π_A(R ∪ S) = π_A(R) ∪ π_A(S) (projection over union)"],"answer":2,"explanation":"Projection does not distribute over difference: with R = {(1, x)} and S = {(1, y)}, π_A(R − S) = {1} but π_A(R) − π_A(S) is empty. Selection does distribute over difference and union, and projection over union.","difficulty":"very-hard","source":"GATE CS"},
];

export default questions;
